typedef struct {
    int idAP;
    char* APssid;
    char APbssid[18];
    int channel;
    int rssi;
    int security;
    // 5Ghost P4: precise PMF from LISTAP's RSN IE parse
    // (0=none, 1=capable/MFPC, 2=required/MFPR-SAE; -1=unknown/legacy LIST path)
    int pmf;
    bool deauth;
    // 5Ghost MULTI-AP C2: this AP is ticked in the scan list for a cross-SSID multi-deauth.
    // Distinct from `deauth` ("actively being deauthed"): `selected` is the pick, `deauth` the
    // running state. Initialised false where each row is filled (malloc'd list, not calloc — see
    // [[fap-app-malloc-uninit-fields]]).
    bool selected;
} APDetails;

// 5Ghost P6: one BLE device from a BLESCAN sweep. type: 'F'=Flipper Zero,
// 'A'=location tracker — Apple Find My (0x004C+OF 0x12/0x07), Tile (0x067C /
// svc 0xFEED), or Samsung SmartTag (svc 0xFD5A); '.'=plain. Fixed-width
// fields (name is NOT strdup'd, unlike APssid) so the list frees with a single
// free(bleList). Mirrors the firmware line BLE:<idx>|<type>|<addr>|<rssi>|<mfg>|<name>.
typedef struct {
    int idx;
    char type;
    char addr[18];   // "AA:BB:CC:DD:EE:FF"
    int rssi;
    unsigned mfg;    // manufacturer company id (hex); 0x004C = Apple
    char name[24];
    int seen;        // 5Ghost FUNC-C: BLESCAN rounds this device appeared in (accumulate mode; 1 = fresh)
    uint8_t raw[31]; // 5Ghost ③④: full raw advert bytes (from the firmware BLERAW: line)
    uint8_t raw_len; // 5Ghost ③④: bytes in raw[] (0 if no BLERAW line seen for this device)
} BLEDeviceDetails;

// 5Ghost FUNC-A: one WiFi station (client) from a STASCAN of a single AP. Fixed-width
// (frees with one free(staList), like BLEDeviceDetails). Mirrors the firmware line
// STA:<idx>|<mac>|<rssi>|<frames>. mac is colon-less 12hex so it feeds DEAUTH's
// <client> token with zero conversion (A3 precise deauth).
typedef struct {
    int idx;
    char mac[13]; // "AABBCCDDEEFF" + NUL
    int rssi;
    int frames;
} StaDetails;

// 5Ghost ②: one known-GATT-service hit from a BLEGATTPROBE. Mirrors the firmware line
// GATT:SVC <label> <uuid> (kGattKnownSvcs in ble.cpp: GenericAccess/DeviceInfo/Battery/
// HID/HeartRate/NordicUART). Fixed-width, lives inline in Ghost5App (no malloc/free).
typedef struct {
    char label[24];
    char uuid[40];
} GattSvcHit;

