bool parse_mac(const char* mac_str, uint8_t* out_bytes) {
    if(!mac_str || !out_bytes) return false;

    // strtok() is disabled in the official firmware API; walk the string by hand instead.
    // strtol() already stops at the ':' separator (or NUL), so we just chain conversions.
    const char* p = mac_str;
    int i = 0;
    while(i < 6) {
        char* endptr;
        long value = strtol(p, &endptr, 16);
        if(endptr == p || value < 0 || value > 255) return false; // no hex digits / out of range
        out_bytes[i++] = (uint8_t)value;
        p = endptr;
        if(*p == ':') {
            p++; // skip separator
        } else if(*p == '\0') {
            break;
        } else {
            return false; // unexpected character
        }
    }

    return i == 6;
}

// TX-legal 20 MHz channels — single table in guided_audit.c, must match
