// 5Ghost: capability check. Official firmware -> trust reported caps;
// unofficial / no module -> allow basic features, gate premium (e.g. 'H' handshake).
static bool fw_has_cap(Ghost5App* app, char cap) {
    if(app->fw_status == FwOfficial) {
        return strchr(app->fw_caps, cap) != NULL;
    }
    return (cap != 'H');
}

// 5Ghost task11: true when an official module reports a firmware older than the
// latest the FAP ships knowledge of (semver major.minor.patch compare).
static bool fw_update_available(Ghost5App* app) {
    if(app->fw_status != FwOfficial) return false;
    int cur[3] = {0, 0, 0}, latest[3] = {0, 0, 0};
    sscanf(app->fw_version, "%d.%d.%d", &cur[0], &cur[1], &cur[2]);
    sscanf(GHOST_LATEST_FW, "%d.%d.%d", &latest[0], &latest[1], &latest[2]);
    for(int i = 0; i < 3; i++) {
        if(cur[i] < latest[i]) return true;
        if(cur[i] > latest[i]) return false;
    }
    return false;
}

// 5Ghost task8: derive PMF/802.11w from the Realtek security bitmask the firmware
// already reports per AP. WPA3-SAE mandates PMF; mixed WPA2/WPA3 negotiates it;
// AES_CMAC is the BIP cipher. When PMF is active the AP ignores our deauth frames,
// so we flag it instead of letting the user think the attack silently failed.
// Limitation: a WPA2 AP with PMF-optional (MFPC=1,MFPR=0) is not distinguishable
// here and may still report as plain WPA2 — verified case coverage only.
static bool ap_has_pmf(int security) {
    return (security & WPA3_SECURITY) || (security & AES_CMAC_ENABLED);
}

// ============================================================================
// 5Ghost UI design system (P8 redesign). Shared Canvas primitives so every screen
// speaks one visual language instead of the upstream's ad-hoc widget/submenu
// strings. 128x64 mono; the title bar occupies y 0..11, the body starts at y>=13.
// Primitives draw in the CURRENT canvas color so they render correctly on an
// inverted (selected) row — the caller sets ColorBlack/ColorWhite.
// ============================================================================

// Full band label from a channel number; shown spelled out on the detail card (the
// short "2G/5G" form was dropped — "2G" reads as cellular and felt generic).
static const char* ghost_ui_band(int channel) {
    return channel > 14 ? "5 GHz" : "2.4 GHz";
}

// Long Realtek-bitmask security label for the detail card (was an inline switch).
static const char* ghost_ui_sec_full(int security) {
    switch(security) {
    case 0:
        return "OPEN";
    case(WEP_ENABLED):
        return "WEP_PSK";
    case(WEP_ENABLED | SHARED_ENABLED):
        return "WEP_SHARED";
    case(WPA_SECURITY | TKIP_ENABLED):
        return "WPA_TKIP_PSK";
    case(WPA_SECURITY | AES_ENABLED):
        return "WPA_AES_PSK";
    case(WPA2_SECURITY | AES_ENABLED):
        return "WPA2_AES_PSK";
    case(WPA2_SECURITY | TKIP_ENABLED):
        return "WPA2_TKIP_PSK";
    case(WPA2_SECURITY | AES_ENABLED | TKIP_ENABLED):
        return "WPA2_MIXED_TKIP";
    case(WPA_SECURITY | WPA2_SECURITY):
        return "WPA_WPA2_MIXED";
    case(WPA_SECURITY | WPA2_SECURITY | TKIP_ENABLED):
        return "WPA_WPA2_MIXED_TKIP";
    case(WPA_SECURITY | WPA2_SECURITY | AES_ENABLED):
        return "WPA_WPA2_MIXED_AES";
    case(WPA_SECURITY | WPA2_SECURITY | TKIP_ENABLED | AES_ENABLED):
        return "WPA_WPA2_MIXED_MIXED";
    case(WPA3_SECURITY | AES_ENABLED):
        return "WPA3_AES_PSK";
    case(WPA2_SECURITY | WPA3_SECURITY | AES_ENABLED):
        return "WPA2_WPA3_MIXED";
    default:
        return "";
    }
}

// 5Ghost UI — traditional-minimal layout (light, lots of white; on 128x64 heavy fills and
// decoration just read as noise) lifted out of "generic" by ONE signature: the ghost is the
// selection cursor — it haunts the current row. No black header bar, no full-row inversion;
// identity comes from the ghost mark + clean type + functional data glyphs (signal/lock).

// Light header: bold title (FontPrimary) + a thin rule, optional right-aligned stat. No fill.
static void ghost_ui_header(Canvas* canvas, const char* title, const char* stat) {
    canvas_set_color(canvas, ColorBlack);
    canvas_set_font(canvas, FontPrimary);
    canvas_draw_str(canvas, 2, 9, title);
    if(stat && stat[0]) {
        canvas_set_font(canvas, FontSecondary);
        int sw = canvas_string_width(canvas, stat);
        canvas_draw_str(canvas, 123 - sw, 9, stat); // right margin so the last glyph isn't clipped
    }
    canvas_draw_line(canvas, 0, 12, 127, 12);
}

// (v1 traditional simplification: dropped the ghost cursor / ghost mascot / signal-bar
// glyphs — selection is now a conventional inverted row and RSSI shows as a plain number.)

// Security padlock glyph at (x,y), ~6x9. Open = hollow padlock w/ raised shackle;
// secured (WPA/WPA2/WPA3) = filled padlock. Drawn in the current color.
static void ghost_ui_lock(Canvas* canvas, int x, int y, int security) {
    if(security == 0) {
        canvas_draw_frame(canvas, x + 2, y, 4, 3); // open shackle, shifted
        canvas_draw_frame(canvas, x, y + 3, 6, 6); // hollow body
    } else {
        canvas_draw_frame(canvas, x + 1, y, 4, 3); // closed shackle
        canvas_draw_box(canvas, x, y + 3, 6, 6); // filled body
    }
}

// Precise PMF tag for the detail card ("PMF!" required / "PMF" capable / "" none).
// Required PMF = deauth-immune, the high-value warning. pmf<0 falls back to heuristic.
static const char* ghost_ui_pmf_tag(int security, int pmf) {
    if(pmf >= 2) return "PMF!";
    if(pmf == 1) return "PMF";
    if(pmf < 0 && ap_has_pmf(security)) return "PMF!";
    return "";
}

// 5Ghost 阶段1 (defense+education moat): a one-word threat verdict for the AP
// detail card header. An AP that advertises no PMF has forgeable management frames
// -> it is deauth-able, so it is a valid target for the deauth / Evil-Portal
// teaching demo. When PMF is present the "PMF"/"PMF!" chip on the security line
// already conveys the protection, so the header stays clean. Mirrors the pmf-tag
// condition exactly so the two never contradict. Wording/fit tuned on hardware.
static const char* ghost_ui_threat_hint(int security, int pmf) {
    if(ghost_ui_pmf_tag(security, pmf)[0]) return ""; // has a PMF chip -> protected
    return "exposed";
}

