// Catalog requires writes under /ext/apps_data/<appid>/. Keep the literal path (not /data)
// so Dialogs file-browser base_path matches. PROTOCOL.md §9.
#define GHOST_DATA_DIR        "/ext/apps_data/5ghost_wifi_lab"
#define GHOST_DATA_DIR_LEGACY "/ext/apps_data/5ghost"

static void ghost_ensure_data_dir(Storage* storage) {
    storage_simply_mkdir(storage, "/ext/apps_data");
    storage_simply_mkdir(storage, GHOST_DATA_DIR);
}

// Move leftover 2.7.5 files before any mkdir/seed of the new dir. migrate copies then
// deletes the source on success; on failure the old folder is left intact and we still
// only write the new path.
static void ghost_migrate_legacy_data(void) {
    Storage* storage = furi_record_open(RECORD_STORAGE);
    if(storage_dir_exists(storage, GHOST_DATA_DIR_LEGACY)) {
        const FS_Error err =
            storage_common_migrate(storage, GHOST_DATA_DIR_LEGACY, GHOST_DATA_DIR);
        if(err != FSE_OK) {
            FURI_LOG_W(TAG, "legacy data migrate: %s", storage_error_get_desc(err));
        }
    }
    furi_record_close(RECORD_STORAGE);
}

// RFC4180 CSV quoting: wrap in quotes, double any embedded quote. Keeps SSIDs with
// commas/quotes from breaking the column layout.
static void csv_escape(const char* in, char* out, size_t out_sz) {
    size_t j = 0;
    if(j < out_sz - 1) out[j++] = '"';
    for(size_t i = 0; in[i] && j < out_sz - 2; i++) {
        if(in[i] == '"' && j < out_sz - 3) out[j++] = '"';
        out[j++] = in[i];
    }
    if(j < out_sz - 1) out[j++] = '"';
    out[j] = '\0';
}

// 5Ghost P3: non-intrusive SD-write feedback. A security tool's user needs to know a capture
// actually landed on the card — a blank screen leaves "did it save?" ambiguous. Green pulse on
// success, red+vibro on failure. Opens the shared notification record per call (cheap).
static void ghost_notify_saved(bool ok) {
    NotificationApp* notif = furi_record_open(RECORD_NOTIFICATION);
    notification_message(notif, ok ? &sequence_success : &sequence_error);
    furi_record_close(RECORD_NOTIFICATION);
}

// 5Ghost task8: low-brightness "scanning" LED. The stock blink sequences run the LED at 255,
// which is glaring in a dark room; a recon tool sweeping ~10s wants a calm pulse, not a strobe.
// A custom dim-blue message (~12% brightness) is pulsed once per 500ms scan-loop tick and the
// LED reset when the sweep ends. Scanning is a synchronous loop, so this needs no extra timer.
static const NotificationMessage msg_scan_blue_dim = {
    .type = NotificationMessageTypeLedBlue,
    .data.led.value = 0x20, // 32/255 ~12% — visible but not harsh; tune on hardware
};
static const NotificationSequence seq_scan_pulse = {
    &msg_scan_blue_dim,
    &message_delay_100,
    &message_blue_0,
    NULL,
};

// 5Ghost task10: send one PHTML* line and block until the module ACKs it (PHTMLOK, set on the
// UART worker thread). ~1.5s budget per chunk — plenty for a 203-byte line at the module's slow
// reader. Returns false on timeout so the caller can abort the upload.
static bool ghost_phtml_send_wait(Ghost5App* app, const char* line, size_t len) {
    app->phtml_ok = false;
    uart_helper_send(app->uart_helper, line, len);
    for(int t = 0; !app->phtml_ok && t < 30; t++) furi_delay_ms(50);
    return app->phtml_ok;
}

// 5Ghost: on launch, seed the bundled example portals into the user-writable portals dir. The
// FAP ships ghost/terminal/freewifi.html via fap_file_assets; the loader unpacks them to
// /ext/apps_assets/<appid>/portals, and we copy any that are missing into the SD dir that Load
// Custom Portal browses — so the playful demo pages work out of the box without manually copying
// to the card. storage_common_copy returns FSE_EXIST for files already there, so user edits and
// any pages the user added themselves are left untouched.
static void ghost_seed_portals(void) {
    Storage* storage = furi_record_open(RECORD_STORAGE);
    storage_simply_mkdir(storage, GHOST_DATA_DIR);
    storage_simply_mkdir(storage, GHOST_DATA_DIR "/portals");
    const char* src = "/ext/apps_assets/5ghost_wifi_lab/portals";
    File* dir = storage_file_alloc(storage);
    if(storage_dir_open(dir, src)) {
        FileInfo info;
        char name[48];
        while(storage_dir_read(dir, &info, name, sizeof(name))) {
            if(info.flags & FSF_DIRECTORY) continue;
            FuriString* s = furi_string_alloc_printf("%s/%s", src, name);
            FuriString* d = furi_string_alloc_printf("%s/%s", GHOST_DATA_DIR "/portals", name);
            storage_common_copy(storage, furi_string_get_cstr(s), furi_string_get_cstr(d));
            furi_string_free(s);
            furi_string_free(d);
        }
    }
    storage_dir_close(dir);
    storage_file_free(dir);
    furi_record_close(RECORD_STORAGE);
}

static void ghost_portal_copy_basename(char* out, size_t out_size, const char* path) {
    furi_check(out);
    furi_check(out_size > 0);
    const char* basename = strrchr(path, '/');
    basename = basename ? basename + 1 : path;

    size_t written = 0;
    while(*basename && written < out_size - 1) {
        const unsigned char c = (unsigned char)*basename++;
        out[written++] = (c >= 0x20 && c <= 0x7E) ? (char)c : '?';
    }
    out[written] = '\0';
    if(written == 0) snprintf(out, out_size, "portal.html");
}

static void ghost_portal_mark_failed(Ghost5App* app) {
    app->custom_portal_ready = false;
    app->custom_portal_load_failed = true;
    app->custom_portal_basename[0] = '\0';
}

// 5Ghost task10: let the user pick an HTML file from the SD and use it as the captive portal.
// The blocking browser is called only by customPortalFileScene, after the VariableItemList input
// callback and dispatcher event have returned. Cancel preserves an earlier successful upload.
// Any read/size/ACK failure fails closed because PHTMLBEGIN may already have invalidated the
// module's previous page. Only a complete, ACKed upload records the safe basename and ready gate.
static GhostPortalLoadResult ghost_load_custom_portal(Ghost5App* app) {
    Storage* storage = furi_record_open(RECORD_STORAGE);
    storage_simply_mkdir(storage, GHOST_DATA_DIR "/portals");

    DialogsApp* dialogs = furi_record_open(RECORD_DIALOGS);
    FuriString* path = furi_string_alloc_set(GHOST_DATA_DIR "/portals");
    DialogsFileBrowserOptions opts;
    dialog_file_browser_set_basic_options(&opts, ".html", NULL);
    opts.base_path = GHOST_DATA_DIR "/portals";
    bool picked = dialog_file_browser_show(dialogs, path, path, &opts);
    furi_record_close(RECORD_DIALOGS);
    if(!picked) {
        furi_string_free(path);
        furi_record_close(RECORD_STORAGE);
        return GhostPortalLoadCancelled;
    }

    char selected_basename[CUSTOM_PORTAL_BASENAME_MAX];
    ghost_portal_copy_basename(
        selected_basename, sizeof(selected_basename), furi_string_get_cstr(path));

    // Read the file into a static buffer (the FAP stack is only 2KB — never put 4KB on it).
    static uint8_t htmlbuf[CUSTOM_PORTAL_MAX];
    size_t htmllen = 0;
    File* file = storage_file_alloc(storage);
    const bool opened =
        storage_file_open(file, furi_string_get_cstr(path), FSAM_READ, FSOM_OPEN_EXISTING);
    bool read_ok = false;
    if(opened) {
        const uint64_t file_size = storage_file_size(file);
        if(file_size > 0 && file_size <= CUSTOM_PORTAL_MAX) {
            htmllen = storage_file_read(file, htmlbuf, (size_t)file_size);
            read_ok = htmllen == (size_t)file_size;
        }
        storage_file_close(file);
    }
    storage_file_free(file);
    furi_string_free(path);
    furi_record_close(RECORD_STORAGE);
    if(!read_ok) {
        ghost_portal_mark_failed(app);
        ghost_notify_saved(false);
        return GhostPortalLoadFailed;
    }

    // Upload in small hex chunks, each ACKed (PHTMLOK), because the module's command reader drains
    // ~1 byte / 3ms while the line lands as a burst — anything bigger than the UART RX ring is lost
    // mid-line, garbling the page. The AmebaD ring is SERIAL_BUFFER_SIZE = 128 B (RingBuffer.h), so
    // a line must fit whole inside it before any draining: 40 HTML bytes -> 80 hex + "PHTMLDATA " +
    // '\n' = 91 B/line < 128, leaving margin. (96-byte chunks = 203 B/line overran the 128 ring and
    // dropped ~1/3 of every chunk — observed on hardware as a corrupted portal.) ACK paces the FAP.
    // Show the loading spinner: the upload blocks the UI for a few seconds on a multi-KB page.
    view_dispatcher_switch_to_view(app->view_dispatcher, loadingView);

    static const char hexd[] = "0123456789abcdef";
    const size_t CHUNK = 40;
    char line[10 + CHUNK * 2 + 2]; // "PHTMLDATA " + hex + '\n'
    bool ok = ghost_phtml_send_wait(app, "PHTMLBEGIN\n", 11); // clear the module's buffer first
    for(size_t off = 0; ok && off < htmllen; off += CHUNK) {
        size_t n = (htmllen - off < CHUNK) ? (htmllen - off) : CHUNK;
        memcpy(line, "PHTMLDATA ", 10);
        for(size_t i = 0; i < n; i++) {
            line[10 + i * 2] = hexd[htmlbuf[off + i] >> 4];
            line[10 + i * 2 + 1] = hexd[htmlbuf[off + i] & 0x0F];
        }
        line[10 + n * 2] = '\n';
        line[10 + n * 2 + 1] = '\0'; // keep debug logging bounded; UART still sends the exact length
        ok = ghost_phtml_send_wait(app, line, 10 + n * 2 + 1);
    }

    if(ok) {
        app->captivePortal = CUSTOM_PORTAL_IDX;
        app->custom_portal_ready = true;
        app->custom_portal_load_failed = false;
        snprintf(
            app->custom_portal_basename,
            sizeof(app->custom_portal_basename),
            "%s",
            selected_basename);
    } else {
        ghost_portal_mark_failed(app);
    }
    ghost_notify_saved(ok);
    return ok ? GhostPortalLoadReady : GhostPortalLoadFailed;
}

void custom_portal_file_scene_on_enter(void* context) {
    Ghost5App* app = context;
    const GhostPortalLoadResult result = ghost_load_custom_portal(app);
    FURI_LOG_I(TAG, "Custom portal file result=%d ready=%d", result, app->custom_portal_ready);
    scene_manager_previous_scene(app->scene_manager);
}

