void config_attack_scene_on_enter(void* context);
void generate_mac_address(unsigned char mac[6]) {
    furi_hal_random_fill_buf(mac, 6);

    mac[0] &= 0xFE;
    mac[0] |= 0x02;
}
void mac_type_change_call_back(VariableItem* item) {
    FURI_LOG_D(TAG, __func__);
    int index = variable_item_get_current_value_index(item);
    Ghost5App* app = variable_item_get_context(item);
    variable_item_set_current_value_text(item, mac_type[index]);
    app->mac_type = index;
    if(app->mac_type == 0) {
        strncpy(app->customMac, "00:E0:4C:01:02:03", 18);
        //snprintf(app->customMac, sizeof(app->customMac), "00:E0:4C:01:02:03");
        parse_mac(app->customMac, app->byte_input_store);

    } else if(app->mac_type == 3) {
        strcpy(app->customMac, app->wifiList[app->selectedWifi].APbssid);
        parse_mac(app->customMac, app->byte_input_store);

    } else if(app->mac_type == 1) {
        unsigned char random_mac[6];
        generate_mac_address(random_mac);
        snprintf(
            app->customMac,
            18,
            "%02X:%02X:%02X:%02X:%02X:%02X",
            random_mac[0],
            random_mac[1],
            random_mac[2],
            random_mac[3],
            random_mac[4],
            random_mac[5]);
        parse_mac(app->customMac, app->byte_input_store);
    }

    if(app->menuIndex == ListWifis) {
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_CONFIG_ATTACK_REBUILD);
    } else if(app->menuIndex == CreateAP) {
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_CONFIG_AP_REBUILD);
    }
}

void config_attack_change_call_back(void* context, uint32_t index) {
    FURI_LOG_D(TAG, __func__);
    FURI_LOG_D(TAG, "%p %ld", context, index);
    Ghost5App* app = context;
    // Items: 0 Deauth Reason, 1 Portal Type, 2 Load Custom Portal, 3 Mac Type, 4 customMac (only
    // when Mac Type == "Custom"). task10 added item 2, shifting the MAC editor from 3 to 4.
    if(index == 2) {
        // Don't open the blocking file browser here: this runs inside the VariableItemList input
        // callback, and nesting dialog_file_browser_show's GUI loop in that stack frame deadlocks
        // (all buttons freeze). Defer it — the custom event is handled from the dispatcher loop
        // after this callback returns and the input stack unwinds. (Scene transitions like index 4
        // are fine from here because they only swap views; the dialog starts a nested GUI loop.)
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_LOAD_PORTAL);
    } else if(index == 4) {
        scene_manager_next_scene(app->scene_manager, aPmacAddresScene);
    }
}

void config_attack_scene_on_enter(void* context) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;
    VariableItem* item;
    variable_item_list_reset(app->variableList);
    item = variable_item_list_add(
        app->variableList, "Deauth Reason", 25, deauth_reason_change_call_back, app);
    variable_item_set_current_value_index(item, app->deauthReason);
    variable_item_set_current_value_text(item, deauth_reasons[app->deauthReason]);
    item = variable_item_list_add(
        app->variableList, "Portal Type", CAPTIVE_PORTAL_SIZE, portal_type_change_call_back, app);
    variable_item_set_current_value_index(item, app->captivePortal);
    variable_item_set_current_value_text(item, captive_portals[app->captivePortal]);

    // 5Ghost task10: index 2 — click to pick an HTML file from SD and upload it as a custom portal
    // (also selects Portal Type = Custom). Routed in config_attack_change_call_back.
    variable_item_list_add(app->variableList, "Load Custom Portal", 0, NULL, app);

    item =
        variable_item_list_add(app->variableList, "Mac Type", 4, mac_type_change_call_back, app);
    variable_item_set_current_value_index(item, app->mac_type);
    variable_item_set_current_value_text(item, mac_type[app->mac_type]);
    view_dispatcher_switch_to_view(app->view_dispatcher, configAttackView);

    if(app->mac_type == 2) {
        item = variable_item_list_add(app->variableList, app->customMac, 0, NULL, NULL);
    }
    variable_item_list_set_enter_callback(app->variableList, config_attack_change_call_back, app);
}
bool config_attack_scene_on_event(void* context, SceneManagerEvent event) {
    Ghost5App* app = context;
    // The VariableItemList callback only posts this event. The dispatcher now enters a dedicated
    // SceneManager scene; that scene owns the blocking file browser and returns here afterwards.
    if(event.type == SceneManagerEventTypeCustom && event.event == GHOST_EVT_LOAD_PORTAL) {
        scene_manager_next_scene(app->scene_manager, customPortalFileScene);
        return true;
    }
    if(event.type == SceneManagerEventTypeCustom &&
       event.event == GHOST_EVT_CONFIG_ATTACK_REBUILD) {
        config_attack_scene_on_enter(app);
        return true;
    }
    return false;
}
