bool custom_beacon_scene_on_event(void* context, SceneManagerEvent event) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;

    FURI_LOG_I("5Ghost", "%s event.type: %d", __func__, event.type);
    FURI_LOG_I("5Ghost", "%s event.event: %ld", __func__, event.event);
    char cmd[40];
    switch(event.type) {
    case SceneManagerEventTypeCustom:
        switch(event.event) {
        case SsidAPInputSceneSaveEvent:
            FURI_LOG_D(TAG, "ssidAPLenght %d", strlen(app->ssidAP));

            // P4 BP-3: custom beacon uses the unified BEACON verb (continuous, single SSID).
            // Send strlen(cmd), not sizeof(cmd) — the old code shipped the whole 40-byte
            // stack buffer including uninitialised tail bytes after the '\n'.
            snprintf(cmd, sizeof(cmd), "BEACON %s\n", app->ssidAP);
            uart_helper_send(app->uart_helper, cmd, strlen(cmd));
            FURI_LOG_D(TAG, cmd);
            scene_manager_next_scene(app->scene_manager, beaconInfoScene);
            break;
        }
        return true;
    default:
        break;
    }
    return false;
}

