void ibeacon_input_scene_on_exit(void* context) {
    UNUSED(context);
}

void ibeacon_broadcast_scene_on_enter(void* context) {
    Ghost5App* app = context;
    const uint8_t* b = app->ibeacon_store;
    uint16_t major = ((uint16_t)b[16] << 8) | b[17];
    uint16_t minor = ((uint16_t)b[18] << 8) | b[19];
    // BLEIBEACON <uuid32hex> <major> <minor> <secs>\n  (major/minor decimal, big-endian input)
    char cmd[80];
    int off = snprintf(cmd, sizeof(cmd), "BLEIBEACON ");
    for(int i = 0; i < 16; i++) off += snprintf(cmd + off, sizeof(cmd) - off, "%02X", b[i]);
    snprintf(cmd + off, sizeof(cmd) - off, " %u %u %d\n", major, minor, app->ibeacon_secs);
    uart_helper_send(app->uart_helper, cmd, strlen(cmd));

    // Broadcast status page (reuses beacon-info widget/view). Firmware self-releases after
    // ibeacon_secs; Back returns to the menu (no STOP needed for a timed command).
    widget_reset(app->widget);
    widget_add_string_element(app->widget, 64, 8, AlignCenter, AlignTop, FontPrimary, "iBeacon TX");
    char line[32];
    snprintf(line, sizeof(line), "Major %u  Minor %u", major, minor);
    widget_add_string_element(app->widget, 64, 28, AlignCenter, AlignTop, FontSecondary, line);
    snprintf(line, sizeof(line), "Broadcasting %ds", app->ibeacon_secs);
    widget_add_string_element(app->widget, 64, 42, AlignCenter, AlignTop, FontSecondary, line);
    widget_add_string_element(
        app->widget, 64, 54, AlignCenter, AlignTop, FontSecondary, "Back to exit");
    view_dispatcher_switch_to_view(app->view_dispatcher, beaconInfoView);
}

bool ibeacon_broadcast_scene_on_event(void* context, SceneManagerEvent event) {
    UNUSED(context);
    UNUSED(event);
    return false;
}

void ibeacon_broadcast_scene_on_exit(void* context) {
    Ghost5App* app = context;
    widget_reset(app->widget);
}

// ── 5Ghost ⑧b: BadBLE HID ────────────────────────────────────────────────────────────
// Flow: menu -> badbleConfigScene (VariableItemList: Payload / Duration / Start)
//   -> Payload OK: [preset] upload inline / [Custom SD] badbleFileScene (pick .txt + upload)
//   -> Start (ready-gated) -> badbleRunScene (send BADBLE <secs>, show CCCD-gated inject status).
// Payload bytes upload to the firmware buffer (BADBLEBEGIN/BADBLEDATA) exactly like the custom-portal
// PHTML* flow; the firmware types them once the host enables the keyboard-report CCCD (ble.cpp
// g5_ble_badble). Views reused: VariableItemList -> configAPView, widget -> beaconInfoView, browser
// -> DialogsApp (no new views/modules). "Repeatable" = Back to config then Start again = a fresh
// window (the firmware also re-injects on a CCCD disable->enable within one window).

#define BADBLE_MAX 512 // keystroke-payload cap; MUST match firmware G5_BADBLE_MAX (ble.h)

// Built-in payloads — HARMLESS by design (a demo line + a monospace 5Ghost banner). The point is to
// prove the injection path + user-controllable output, not to ship a script. Short enough that
// keySequence (~10ms/char) types them well inside the window. '\n' => Enter on the target.
typedef struct {
    const char* name;
    const char* text;
} BadblePreset;
static const BadblePreset badble_presets[] = {
    {"Demo text", "5Ghost BadBLE HID test "},
    {"Banner", "== 5Ghost WiFi Lab ==\nBadBLE HID demo\n"},
};
#define BADBLE_PRESET_COUNT ((int)(sizeof(badble_presets) / sizeof(badble_presets[0])))
#define BADBLE_SOURCE_CUSTOM BADBLE_PRESET_COUNT // Payload index past the last preset = Custom (SD)

static const char* badble_secs_text(int s) {
    return (s == 120) ? "120s" : (s == 60) ? "60s" : "30s";
}
static const char* badble_source_name(int idx) {
    return (idx >= 0 && idx < BADBLE_PRESET_COUNT) ? badble_presets[idx].name : "Custom (SD)";
}

// Send one BADBLE* line and block until the firmware ACKs it (BADBLEOK, set on the UART worker).
// Mirrors ghost_phtml_send_wait; false on timeout so the caller aborts the upload.
static bool ghost_badble_send_wait(Ghost5App* app, const char* line, size_t len) {
    app->badble_ack = false;
    uart_helper_send(app->uart_helper, line, len);
    for(int t = 0; !app->badble_ack && t < 30; t++) furi_delay_ms(50);
    return app->badble_ack;
}

// Upload keystroke bytes to the firmware buffer in ACKed hex chunks (BADBLEBEGIN + BADBLEDATA), same
// pacing as the custom-portal upload: 40 bytes -> 80 hex + "BADBLEDATA " + '\n' = 92 B/line < the
// module's 128 B UART RX ring. Sets badble_ready/name on a fully-ACKed upload, fails closed otherwise
// (BADBLEBEGIN may already have cleared the module's previous payload). len clamped to BADBLE_MAX.
static bool ghost_badble_upload(Ghost5App* app, const uint8_t* data, size_t len, const char* name) {
    if(len > BADBLE_MAX) len = BADBLE_MAX;
    static const char hexd[] = "0123456789abcdef";
    const size_t CHUNK = 40;
    char line[11 + CHUNK * 2 + 2]; // "BADBLEDATA " + hex + '\n'
    bool ok = ghost_badble_send_wait(app, "BADBLEBEGIN\n", 12); // clear the module buffer first
    for(size_t off = 0; ok && off < len; off += CHUNK) {
        size_t n = (len - off < CHUNK) ? (len - off) : CHUNK;
        memcpy(line, "BADBLEDATA ", 11);
        for(size_t i = 0; i < n; i++) {
            line[11 + i * 2] = hexd[data[off + i] >> 4];
            line[11 + i * 2 + 1] = hexd[data[off + i] & 0x0F];
        }
        line[11 + n * 2] = '\n';
        line[11 + n * 2 + 1] = '\0';
        ok = ghost_badble_send_wait(app, line, 11 + n * 2 + 1);
    }
    if(ok) {
        app->badble_ready = true;
        app->badble_load_failed = false;
        snprintf(app->badble_name, sizeof(app->badble_name), "%s", name);
    } else {
        app->badble_ready = false;
        app->badble_load_failed = true;
        app->badble_name[0] = '\0';
    }
    ghost_notify_saved(ok);
    return ok;
}

// Upload the selected built-in preset. Called from the dispatcher loop (never the input callback —
// the paced ACK wait would hold the ViewPort lock).
static void ghost_badble_upload_preset(Ghost5App* app) {
    if(app->badble_source < 0 || app->badble_source >= BADBLE_PRESET_COUNT) return;
    const BadblePreset* p = &badble_presets[app->badble_source];
    view_dispatcher_switch_to_view(app->view_dispatcher, loadingView);
    ghost_badble_upload(app, (const uint8_t*)p->text, strlen(p->text), p->name);
}

// Pick a .txt keystroke file from SD and upload it. The blocking browser is called only from
// badbleFileScene on_enter (after the input callback + dispatcher event returned). Cancel keeps any
// earlier ready payload. Any read/upload failure fails closed. Mirrors ghost_load_custom_portal.
static void ghost_load_custom_payload(Ghost5App* app) {
    Storage* storage = furi_record_open(RECORD_STORAGE);
    storage_simply_mkdir(storage, GHOST_DATA_DIR "/badble");
    DialogsApp* dialogs = furi_record_open(RECORD_DIALOGS);
    FuriString* path = furi_string_alloc_set(GHOST_DATA_DIR "/badble");
    DialogsFileBrowserOptions opts;
    dialog_file_browser_set_basic_options(&opts, ".txt", NULL);
    opts.base_path = GHOST_DATA_DIR "/badble";
    bool picked = dialog_file_browser_show(dialogs, path, path, &opts);
    furi_record_close(RECORD_DIALOGS);
    if(!picked) {
        furi_string_free(path);
        furi_record_close(RECORD_STORAGE);
        return; // cancel: keep any earlier successful upload
    }
    char basename[CUSTOM_PORTAL_BASENAME_MAX];
    ghost_portal_copy_basename(basename, sizeof(basename), furi_string_get_cstr(path));
    static uint8_t buf[BADBLE_MAX]; // 512 — fits the fw cap; static (the FAP stack is only 2KB)
    size_t buflen = 0;
    File* file = storage_file_alloc(storage);
    bool read_ok = false;
    if(storage_file_open(file, furi_string_get_cstr(path), FSAM_READ, FSOM_OPEN_EXISTING)) {
        uint64_t fsz = storage_file_size(file);
        size_t toread = (fsz > BADBLE_MAX) ? BADBLE_MAX : (size_t)fsz; // longer files truncate to cap
        if(toread > 0) {
            buflen = storage_file_read(file, buf, toread);
            read_ok = (buflen == toread);
        }
        storage_file_close(file);
    }
    storage_file_free(file);
    furi_string_free(path);
    furi_record_close(RECORD_STORAGE);
    if(!read_ok) {
        app->badble_ready = false;
        app->badble_load_failed = true;
        app->badble_name[0] = '\0';
        ghost_notify_saved(false);
        return;
    }
    view_dispatcher_switch_to_view(app->view_dispatcher, loadingView);
    ghost_badble_upload(app, buf, buflen, basename);
}

// ── config scene (VariableItemList: Payload / Duration / Start) ──
static void badble_payload_change_cb(VariableItem* item) {
    Ghost5App* app = variable_item_get_context(item);
    int idx = variable_item_get_current_value_index(item);
    app->badble_source = idx;
    app->badble_ready = false; // source changed: must (re)load before Start
    app->badble_load_failed = false;
    variable_item_set_current_value_text(item, badble_source_name(idx));
}
static void badble_duration_change_cb(VariableItem* item) {
    Ghost5App* app = variable_item_get_context(item);
    int idx = variable_item_get_current_value_index(item);
    const int secs[] = {30, 60, 120};
    app->badble_secs = secs[(idx >= 0 && idx < 3) ? idx : 0];
    variable_item_set_current_value_text(item, badble_secs_text(app->badble_secs));
}
static void badble_config_enter_cb(void* context, uint32_t index) {
    Ghost5App* app = context;
    if(index == 0) {
        // Load: never open the browser / run paced UART in this input callback — defer to dispatcher.
        view_dispatcher_send_custom_event(
            app->view_dispatcher,
            (app->badble_source == BADBLE_SOURCE_CUSTOM) ? GHOST_EVT_BADBLE_LOAD_FILE :
                                                           GHOST_EVT_BADBLE_LOAD_PRESET);
    } else if(index == 2) {
        if(!app->badble_ready) {
            snprintf(
                message, sizeof(message), "%s",
                app->badble_load_failed ? "Payload upload failed.\nOpen Payload, press OK." :
                                          "No payload loaded.\nOpen Payload, press OK.");
            scene_manager_next_scene(app->scene_manager, popupScene);
            return;
        }
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_BADBLE_START);
    }
}
static void badble_config_build(Ghost5App* app) {
    VariableItem* item;
    variable_item_list_reset(app->variableList);
    item = variable_item_list_add(
        app->variableList, "Payload", BADBLE_PRESET_COUNT + 1, badble_payload_change_cb, app);
    variable_item_set_current_value_index(item, app->badble_source);
    variable_item_set_current_value_text(item, badble_source_name(app->badble_source));
    item = variable_item_list_add(app->variableList, "Duration", 3, badble_duration_change_cb, app);
    int di = (app->badble_secs == 120) ? 2 : (app->badble_secs == 60) ? 1 : 0;
    variable_item_set_current_value_index(item, di);
    variable_item_set_current_value_text(item, badble_secs_text(app->badble_secs));
    // "Go" (not "Start"): this only opens the run console; the actual inject is started there by
    // the user pressing OK. Naming it "Start" here made users expect an immediate send (it didn't).
    item = variable_item_list_add(app->variableList, "Go", 1, NULL, app);
    variable_item_set_current_value_text(item, app->badble_ready ? app->badble_name : "load 1st");
    variable_item_list_set_enter_callback(app->variableList, badble_config_enter_cb, app);
    view_dispatcher_switch_to_view(app->view_dispatcher, configAPView);
}
void badble_config_scene_on_enter(void* context) {
    Ghost5App* app = context;
    app->menuIndex = BadBleHid;
    badble_config_build(app);
}
bool badble_config_scene_on_event(void* context, SceneManagerEvent event) {
    Ghost5App* app = context;
    if(event.type == SceneManagerEventTypeCustom) {
        switch(event.event) {
        case GHOST_EVT_BADBLE_LOAD_FILE:
            scene_manager_next_scene(app->scene_manager, badbleFileScene);
            return true;
        case GHOST_EVT_BADBLE_LOAD_PRESET:
            ghost_badble_upload_preset(app);
            badble_config_build(app); // refresh Start row (ready state) + return to configAPView
            return true;
        case GHOST_EVT_BADBLE_START:
            scene_manager_next_scene(app->scene_manager, badbleRunScene);
            return true;
        default:
            break;
        }
    }
    return false;
}
void badble_config_scene_on_exit(void* context) {
    UNUSED(context);
}

// ── file scene (blocking SD .txt picker + upload, then back to config) ──
void badble_file_scene_on_enter(void* context) {
    Ghost5App* app = context;
    ghost_load_custom_payload(app);
    scene_manager_previous_scene(app->scene_manager); // back to config; its on_enter rebuilds -> ready
}
bool badble_file_scene_on_event(void* context, SceneManagerEvent event) {
    UNUSED(context);
    UNUSED(event);
    return false;
}
void badble_file_scene_on_exit(void* context) {
    UNUSED(context);
}

// ── run console — MANUAL send / stop / re-send (no auto-send; the user owns the timing) ──
// Reworked to the official Flipper BadUSB run range (OK = Start/Stop toggle) adapted to BadBLE's
// reality: the firmware runs the whole advertise -> pair -> CCCD -> settle -> inject window itself,
// so OK controls the SESSION (start / stop / re-send). The exact keystroke instant is still decided
// by the target's BLE pairing/CCCD subscribe — a HID physical constraint, identical to official
// BadUSB's BLE mode ("runs on connection"), not something the user can or should time. on_exit
// ALWAYS sends STOP so the fw window can never outlive this scene; that is what previously left the
// window blocking Serial1 and made a following payload re-upload time out (the reload bug).
static void badble_run_ok_cb(GuiButtonType result, InputType type, void* context) {
    Ghost5App* app = context;
    if(result != GuiButtonTypeCenter || type != InputTypeShort) return;
    // Running -> Stop (abort the window); idle/done -> Start (begin a new inject session). Only post
    // an event here (dispatcher ctx sends the UART command), same ViewPort-lock safety as elsewhere.
    view_dispatcher_send_custom_event(
        app->view_dispatcher,
        app->badble_running ? GHOST_EVT_BADBLE_STOP : GHOST_EVT_BADBLE_START);
}
static void badble_run_draw(Ghost5App* app) {
    widget_reset(app->widget);
    widget_add_string_element(app->widget, 64, 2, AlignCenter, AlignTop, FontPrimary, "BadBLE HID");
    char l[48];
    snprintf(
        l, sizeof(l), "%s  %ds", app->badble_name[0] ? app->badble_name : "payload", app->badble_secs);
    widget_add_string_element(app->widget, 64, 18, AlignCenter, AlignTop, FontSecondary, l);
    const char* state = app->badble_done              ? "Window done" :
                        !app->badble_running          ? "Ready to start" :
                        app->badble_inject_count > 0  ? "Injected!" :
                        app->badble_conn              ? "Connected, pairing.." :
                                                        "Advertising 5Ghost-HID";
    widget_add_string_element(app->widget, 64, 31, AlignCenter, AlignTop, FontSecondary, state);
    if(app->badble_inject_count > 0) {
        snprintf(
            l, sizeof(l), "TX x%d %s", app->badble_inject_count,
            app->badble_last_fallback ? "(fallback)" : "(cccd-ready)");
        widget_add_string_element(app->widget, 64, 43, AlignCenter, AlignTop, FontSecondary, l);
    }
    // OK soft-key toggles the session (Start/Stop); Back exits (on_exit sends STOP). Label tracks state.
    widget_add_button_element(
        app->widget, GuiButtonTypeCenter, app->badble_running ? "Stop" : "Start", badble_run_ok_cb,
        app);
}
void badble_run_scene_on_enter(void* context) {
    Ghost5App* app = context;
    // IDLE: do NOT auto-send. The inject window starts only when the user presses OK (Start).
    app->badble_running = false;
    app->badble_done = false;
    app->badble_inject_count = 0;
    app->badble_last_fallback = false;
    app->badble_conn = 0;
    app->badble_notify_ready = 0;
    badble_run_draw(app);
    view_dispatcher_switch_to_view(app->view_dispatcher, beaconInfoView);
}
bool badble_run_scene_on_event(void* context, SceneManagerEvent event) {
    Ghost5App* app = context;
    if(event.type != SceneManagerEventTypeCustom) return false;
    switch(event.event) {
    case GHOST_EVT_BADBLE_START: {
        // Start pressed: begin one inject session. Optimistically enter RUNNING so the soft-key
        // flips to Stop immediately; the fw's BADBLE:START/INJECT/OK lines refine the status.
        app->badble_running = true;
        app->badble_done = false;
        app->badble_inject_count = 0;
        app->badble_last_fallback = false;
        app->badble_conn = 0;
        app->badble_notify_ready = 0;
        char cmd[24];
        snprintf(cmd, sizeof(cmd), "BADBLE %d\n", app->badble_secs);
        uart_helper_send(app->uart_helper, cmd, strlen(cmd));
        badble_run_draw(app);
        return true;
    }
    case GHOST_EVT_BADBLE_STOP:
        // Stop pressed: abort the fw window. The fw breaks its loop and emits BADBLE:OK, which the
        // UART worker turns into DONE (running->false, done->true) — the UI settles on "Window done".
        uart_helper_send(app->uart_helper, "STOP\n", 5);
        badble_run_draw(app);
        return true;
    case GHOST_EVT_BADBLE_UPDATE:
    case GHOST_EVT_BADBLE_DONE:
        badble_run_draw(app); // worker already updated the state fields; just refresh in place
        return true;
    default:
        return false;
    }
}
void badble_run_scene_on_exit(void* context) {
    Ghost5App* app = context;
    // Always end the fw window on exit (Back). Without this the fw keeps blocking Serial1 for the
    // rest of the duration, so a payload re-upload from config would BADBLEBEGIN-timeout (reload bug).
    uart_helper_send(app->uart_helper, "STOP\n", 5);
    app->badble_running = false;
    widget_reset(app->widget);
}

// 5Ghost About — four fixed pages (Up/Down flips a whole page, Back exits to the menu).
// P1 brand + GitHub QR, P2 repo + GitHub QR, P3 legal, P4 firmware/version (hero fw
// version + Official/Unofficial/No-module badge + 6 caps blocks + up-to-date/update hint).
typedef struct {
    Ghost5App* app;
    int page; // 0 = brand, 1 = repo, 2 = legal, 3 = firmware/version
} AboutModel;
#define ABOUT_PAGES 4

static void ghost_about_draw_callback(Canvas* canvas, void* model) {
    AboutModel* m = model;
    canvas_clear(canvas);
    canvas_set_color(canvas, ColorBlack);

    // Unified layout (redesign per on-device feedback that the old mixed per-page layouts read
    // messy / uneven, with mismatched QR sizes and too much whitespace): every page is a 50px
    // visual on the left (QR or ghost mascot) + a right text column (FontPrimary heading, rule,
    // two FontSecondary lines), with a 3-dot page indicator top-right. No header bar — the
    // left/right blocks fill the screen instead of leaving a gap under a title.
    for(int i = 0; i < ABOUT_PAGES; i++) {
        int dy = 4 + i * 6;
        if(i == m->page)
            canvas_draw_box(canvas, 122, dy, 4, 4);
        else
            canvas_draw_frame(canvas, 122, dy, 4, 4);
    }

    const int tx = 56; // right-hand text column
    if(m->page == 0) {
        canvas_draw_icon(canvas, 3, 8, &I_qr_pingequa); // 50x50 GitHub short-link QR
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str(canvas, tx, 18, "5Ghost");
        canvas_set_font(canvas, FontSecondary);
        canvas_draw_str(canvas, tx, 30, "WiFi Lab");
        canvas_draw_line(canvas, tx, 34, 119, 34);
        canvas_draw_str(canvas, tx, 46, "v" GHOST_APP_VERSION);
        canvas_draw_str(canvas, tx, 58, "2.4 / 5 GHz");
    } else if(m->page == 1) {
        canvas_draw_icon(canvas, 3, 8, &I_qr_github); // 50x50 GitHub QR (gh.pingequa.com -> repo 302)
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str(canvas, tx, 18, "Source");
        canvas_set_font(canvas, FontSecondary);
        canvas_draw_str(canvas, tx, 30, "& docs");
        canvas_draw_line(canvas, tx, 34, 119, 34);
        canvas_draw_str(canvas, tx, 46, "GitHub");
        canvas_draw_str(canvas, tx, 58, "pingequalab");
    } else if(m->page == 2) {
        canvas_draw_icon(canvas, 4, 9, &I_ghost_about); // 48x48 brand ghost mascot
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str(canvas, tx, 18, "Legal");
        canvas_set_font(canvas, FontSecondary);
        canvas_draw_str(canvas, tx, 30, "Authorized");
        canvas_draw_line(canvas, tx, 34, 119, 34);
        canvas_draw_str(canvas, tx, 46, "Test what");
        canvas_draw_str(canvas, tx, 58, "you own.");
    } else {
        // ── page 4: firmware / version — hero fw version + status badge + caps blocks ──
        Ghost5App* app = m->app;
        canvas_set_font(canvas, FontSecondary);
        canvas_draw_str(canvas, 3, 9, "5Ghost FW");
        // status badge (inverted), right-aligned but clear of the page-dot column
        const char* badge = (app->fw_status == FwOfficial)     ? "OFFICIAL" :
                            (app->fw_status == FwUnofficial)   ? "UNOFFIC." :
                                                                 "NO MODULE";
        int bw = canvas_string_width(canvas, badge) + 6;
        canvas_draw_box(canvas, 118 - bw, 1, bw, 10);
        canvas_set_color(canvas, ColorWhite);
        canvas_draw_str(canvas, 118 - bw + 3, 9, badge);
        canvas_set_color(canvas, ColorBlack);
        // hero version box — frame spans pixel rows 14..31, vertical centre = row 22
        canvas_draw_frame(canvas, 3, 14, 116, 18);
        if(app->fw_status == FwNoModule) {
            canvas_set_font(canvas, FontPrimary);
            canvas_draw_str_aligned(canvas, 10, 22, AlignLeft, AlignCenter, "No module");
        } else {
            // FontPrimary (not FontBigNumbers) — on-device feedback: BigNumbers version was oversized.
            // AlignCenter (vertical) anchors the glyph centre to the box centre — no manual baseline math.
            canvas_set_font(canvas, FontPrimary);
            canvas_draw_str_aligned(canvas, 8, 22, AlignLeft, AlignCenter, app->fw_version); // e.g. "2.3.0"
            canvas_set_font(canvas, FontSecondary);
            if(fw_update_available(app)) {
                char up[22];
                snprintf(up, sizeof(up), ">%s upd", GHOST_LATEST_FW);
                canvas_draw_str_aligned(canvas, 52, 22, AlignLeft, AlignCenter, up);
            } else {
                // up-to-date: check mark (centred on row 22) + "newest"
                canvas_draw_line(canvas, 52, 22, 55, 25);
                canvas_draw_line(canvas, 55, 25, 61, 18);
                canvas_draw_str_aligned(canvas, 65, 22, AlignLeft, AlignCenter, "newest");
            }
        }
        // caps blocks: filled = firmware actually reports the cap (raw IDENT caps string)
        canvas_set_font(canvas, FontSecondary);
        canvas_draw_str(canvas, 3, 44, "CAPS");
        static const char CAPS[] = "DSEBHLICK";
        for(int i = 0; i < 9; i++) {
            int bx = 30 + i * 10; // 9 blocks, pitch 10 / width 9: 30+8*10=110, +9=119 < 122 page-dots
            char c[2] = {CAPS[i], '\0'};
            bool has = (app->fw_caps[0] != '\0') && (strchr(app->fw_caps, CAPS[i]) != NULL);
            // block = cols bx..bx+9, rows 36..44. Manual centring (NOT AlignCenter — its vertical anchor
            // uses the full font box incl. descender space, which pushes descender-less caps too high):
            //  · horizontal: (9 - glyph width)/2 so every letter's L/R margins are equal
            //  · vertical: baseline 44 (on-device calibrated — AlignCenter can't be trusted here because
            //    FontSecondary's ascent includes tall Cyrillic/accented glyphs, not these plain caps)
            int lx = bx + (9 - (int)canvas_string_width(canvas, c)) / 2;
            if(has) {
                canvas_draw_box(canvas, bx, 36, 9, 9);
                canvas_set_color(canvas, ColorWhite);
                canvas_draw_str(canvas, lx, 44, c);
                canvas_set_color(canvas, ColorBlack);
            } else {
                canvas_draw_frame(canvas, bx, 36, 9, 9);
                canvas_draw_str(canvas, lx, 44, c);
            }
        }
        // footer — line at 49 leaves 4px blank below the CAPS row (rows 45..48), symmetric with the 4px above (rows 32..35)
        canvas_draw_line(canvas, 3, 49, 124, 49);
        canvas_draw_str(canvas, 3, 59, "App v" GHOST_APP_VERSION);
    }
}

static bool ghost_about_input_callback(InputEvent* event, void* context) {
    Ghost5App* app = context;
    if(event->type != InputTypeShort && event->type != InputTypeRepeat) return false;
    bool handled = false;
    with_view_model(
        app->about_view,
        AboutModel * m,
        {
            // Up/Down flip a whole page and wrap; Back falls through to exit the scene.
            if(event->key == InputKeyDown) {
                m->page = (m->page < ABOUT_PAGES - 1) ? m->page + 1 : 0;
                handled = true;
            } else if(event->key == InputKeyUp) {
                m->page = (m->page > 0) ? m->page - 1 : ABOUT_PAGES - 1;
                handled = true;
            }
        },
        true);
    return handled; // Back -> dispatcher -> previous scene (home menu)
}

void help_scene_on_enter(void* context) {
    Ghost5App* app = context;
    with_view_model(app->about_view, AboutModel * m, { m->app = app; m->page = 0; }, true);
    view_dispatcher_switch_to_view(app->view_dispatcher, aboutView);
}

bool help_scene_on_event(void* context, SceneManagerEvent event) {
    UNUSED(context);
    UNUSED(event);
    return false;
}

void help_scene_on_exit(void* context) {
    UNUSED(context);
}

void popup_scene_on_enter(void* context) {
    Ghost5App* app = context;
    popup_reset(app->popup);
    // Use the full screen for the error copy. The former x=0/AlignCenter coordinates placed half
    // the text off-screen, so the ready gate showed only the dolphin icon with no explanation.
    popup_set_header(app->popup, "ERROR", 64, 7, AlignCenter, AlignTop);
    popup_set_text(app->popup, message, 64, 25, AlignCenter, AlignTop);
    view_dispatcher_switch_to_view(app->view_dispatcher, popupView);
    UNUSED(context);
}

bool popup_scene_on_event(void* context, SceneManagerEvent event) {
    UNUSED(context);
    UNUSED(event);
    return false;
}

void popup_scene_on_exit(void* context) {
    // Clear the shared error buffer so the next error starts fresh (symmetric with
    // credentials[0]='\0'; the ERR: handler also overwrites from offset 0).
    message[0] = '\0';
    UNUSED(context);
}

void security_change_callback(VariableItem* item) {
    FURI_LOG_D(TAG, __func__);
    int index = variable_item_get_current_value_index(item);
    Ghost5App* app = variable_item_get_context(item);
    variable_item_set_current_value_text(item, securityType[index]);
    app->securityAP = index;
    view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_CONFIG_AP_REBUILD);
}

void channel_change_callback(VariableItem* item) {
    FURI_LOG_D(TAG, __func__);
    int index = variable_item_get_current_value_index(item);
    Ghost5App* app = variable_item_get_context(item);
    variable_item_set_current_value_text(item, channelList[index]);
    app->channelAP = index;
}

static void config_ap_start(Ghost5App* app) {
    char cmd[100] = "";
    if(app->securityAP == 1) {
        snprintf(cmd, 74, "PASSWORD %s\n", app->passwordAP);
        uart_helper_send(app->uart_helper, cmd, strlen(cmd));
        furi_delay_ms(200);
    }
    snprintf(cmd, 25, "APMAC %s\n", app->customMac);
    uart_helper_send(app->uart_helper, cmd, strlen(cmd));
    furi_delay_ms(200);
    snprintf(cmd, 25, "CHANNEL %s\n", channelList[app->channelAP]);
    uart_helper_send(app->uart_helper, cmd, strlen(cmd));
    furi_delay_ms(200);
    snprintf(cmd, 13, "PORTAL %d\n", app->captivePortal);
    uart_helper_send(app->uart_helper, cmd, strlen(cmd));
    furi_delay_ms(200);
    snprintf(cmd, 48, "APSTART %s\n", app->ssidAP);
    FURI_LOG_D(TAG, "%s", app->ssidAP);
    uart_helper_send(app->uart_helper, cmd, strlen(cmd));
    scene_manager_next_scene(app->scene_manager, evilCredsScene);
}

void config_ap_change_call_back(void* context, uint32_t index) {
    FURI_LOG_D(TAG, __func__);
    FURI_LOG_D(TAG, "%p %ld", context, index);
    Ghost5App* app = context;
    if(index == app->config_ap_layout.ap_name) {
        text_input_reset(app->text_input);
        text_input_set_header_text(app->text_input, "Acces Point Name");
        text_input_set_result_callback(
            app->text_input, config_ap_scene_on_enter, app, app->ssidAP, app->ssidAPLength, true);
        view_dispatcher_switch_to_view(app->view_dispatcher, apNameTextInputView);
    } else if(index == app->config_ap_layout.password) {
        text_input_reset(app->text_input);
        text_input_set_header_text(app->text_input, "Acces Point Password");
        text_input_set_result_callback(
            app->text_input,
            config_ap_scene_on_enter,
            app,
            app->passwordAP,
            app->passwordAPLength,
            true);
        view_dispatcher_switch_to_view(app->view_dispatcher, apPasswordTextInputView);
    } else if(index == app->config_ap_layout.portal_file) {
        // Never nest dialog_file_browser_show() in this VariableItemList input callback.
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_LOAD_PORTAL);
    } else if(index == app->config_ap_layout.custom_mac) {
        scene_manager_next_scene(app->scene_manager, aPmacAddresScene);
    } else if(index == app->config_ap_layout.start) {
        if(app->captivePortal == CUSTOM_PORTAL_IDX && !app->custom_portal_ready) {
            snprintf(
                message,
                sizeof(message),
                "%s",
                app->custom_portal_load_failed ?
                    "Portal upload failed.\nSelect Portal File again." :
                    "Custom portal not ready.\nSelect Portal File first.");
            scene_manager_next_scene(app->scene_manager, popupScene);
            return;
        }
        // config_ap_start sends several paced UART commands. Running those delays inside the
        // VariableItemList input callback holds the ViewPort lock long enough to trip the GUI
        // watchdog. Defer the complete start sequence to the dispatcher loop.
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_CONFIG_AP_START);
    }
}

void config_ap_scene_on_enter(void* context) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;
    VariableItem* item;
    app->menuIndex = CreateAP;
    credentials[0] = '\0';
    app->creds_path[0] = '\0'; // start a new creds file for this AP session
    variable_item_list_reset(app->variableList);
    app->config_ap_layout = ghost_config_ap_layout(
        app->securityAP == 1,
        app->mac_type == 2,
        app->captivePortal == CUSTOM_PORTAL_IDX);
    uint32_t row = 0;

    furi_check(row++ == app->config_ap_layout.ap_name);
    item = variable_item_list_add(app->variableList, "AP NAME", 1, NULL, NULL);
    variable_item_set_current_value_text(item, app->ssidAP);
    variable_item_set_current_value_index(item, 0);

    furi_check(row++ == app->config_ap_layout.security);
    item = variable_item_list_add(app->variableList, "SECURITY", 2, security_change_callback, app);
    variable_item_set_current_value_text(item, securityType[app->securityAP]);
    variable_item_set_current_value_index(item, app->securityAP);

    if(app->securityAP != 0) {
        furi_check(row++ == app->config_ap_layout.password);
        item = variable_item_list_add(app->variableList, "Password", 1, NULL, NULL);
        variable_item_set_current_value_text(item, app->passwordAP);
        variable_item_set_current_value_index(item, 0);
    }

    furi_check(row++ == app->config_ap_layout.channel);
    item = variable_item_list_add(app->variableList, "Channel", 59, channel_change_callback, app);
    variable_item_set_current_value_text(item, channelList[app->channelAP]);
    variable_item_set_current_value_index(item, app->channelAP);

    furi_check(row++ == app->config_ap_layout.portal_type);
    item = variable_item_list_add(
        app->variableList, "Portal Type", CAPTIVE_PORTAL_SIZE, portal_type_change_call_back, app);
    variable_item_set_current_value_index(item, app->captivePortal);
    variable_item_set_current_value_text(item, captive_portals[app->captivePortal]);

    if(app->captivePortal == CUSTOM_PORTAL_IDX) {
        furi_check(row++ == app->config_ap_layout.portal_file);
        item = variable_item_list_add(app->variableList, "Portal File", 1, NULL, app);
        variable_item_set_current_value_index(item, 0);
        variable_item_set_current_value_text(
            item,
            app->custom_portal_ready ?
                app->custom_portal_basename :
                (app->custom_portal_load_failed ? "Upload failed" : "Select..."));
    }

    furi_check(row++ == app->config_ap_layout.mac_type);
    item =
        variable_item_list_add(app->variableList, "Mac Type", 3, mac_type_change_call_back, app);
    variable_item_set_current_value_index(item, app->mac_type);
    variable_item_set_current_value_text(item, mac_type[app->mac_type]);

    if(app->mac_type == 2) {
        furi_check(row++ == app->config_ap_layout.custom_mac);
        item = variable_item_list_add(app->variableList, app->customMac, 0, NULL, NULL);
    }

    furi_check(row++ == app->config_ap_layout.start);
    item = variable_item_list_add(app->variableList, "Start", 1, NULL, app);
    variable_item_list_set_enter_callback(app->variableList, config_ap_change_call_back, app);
    furi_check(row == app->config_ap_layout.count);

    view_dispatcher_switch_to_view(app->view_dispatcher, configAPView);
}

bool config_ap_scene_on_event(void* context, SceneManagerEvent event) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;

    FURI_LOG_I("5Ghost", "%s event.type: %d", __func__, event.type);
    FURI_LOG_I("5Ghost", "%s event.event: %ldd", __func__, event.event);
    char cmd[40];
    switch(event.type) {
    case SceneManagerEventTypeCustom:
        if(event.event == GHOST_EVT_LOAD_PORTAL) {
            scene_manager_next_scene(app->scene_manager, customPortalFileScene);
            return true;
        }
        if(event.event == GHOST_EVT_CONFIG_AP_REBUILD) {
            config_ap_scene_on_enter(app);
            return true;
        }
        if(event.event == GHOST_EVT_CONFIG_AP_START) {
            config_ap_start(app);
            return true;
        }
        switch(event.event) {
        case SsidAPInputSceneSaveEvent:
            FURI_LOG_D(TAG, "ssidAPLenght %d", strlen(app->ssidAP));

            snprintf(cmd, 6 + strlen(app->ssidAP) + 2, "BSSID %s\n", app->ssidAP);
            FURI_LOG_D(TAG, cmd);
            break;
        }
        return true;
    default:
        break;
    }
    return false;
}

void config_ap_scene_on_exit(void* context) {
    UNUSED(context);
}

// ---- 5Ghost P2: handshake capture scenes ------------------------------------
// Custom events posted from the UART worker thread to refresh the GUI on the main
// thread (widget/storage work must not run in the UART callback).
#define GHOST_EVT_HS_UPDATE 0x201u // a captured frame arrived
#define GHOST_EVT_HS_DONE   0x202u // HSDONE: capture finished
#define GHOST_EVT_HS_ERROR  0x203u // HSERR: firmware error
#define GHOST_EVT_PMKID_UPDATE 0x207u // 5Ghost B3: PMKID on/st progress line arrived
#define GHOST_EVT_PMKID_DONE   0x208u // 5Ghost B3: PMKID terminal line (ok/fail/err)
// 5Ghost: AP picker "Rescan" row -> the select scene's on_event re-sweeps. Keeps the heavy
// scan/rebuild off the submenu item callback (matches the worker->custom-event->on_event pattern).
#define GHOST_EVT_AP_RESCAN    0x209u

// 5Ghost: sentinel submenu id for the "Rescan" row in the AP pickers (handshake/PMKID).
// Real rows carry the wifiList index (0..wifiCount-1), so a high value never collides.
#define GHOST_AP_RESCAN_ID 0x7FFFFFFFu

// Forward decls: the item callback (Rescan row) and the scan/build helpers reference each other.
static void handshake_ap_item_callback(void* context, uint32_t index);
static void handshake_scan_aps(Ghost5App* app);
static void handshake_build_menu(Ghost5App* app);

// Passive LISTAP sweep into app->wifiList (blocking ~7.5-15s, dim-blue pulse while scanning).
// Active scan (SCAN) returns nothing on Ameba 3.1.7, so the handshake flow always uses LISTAP.
static void handshake_scan_aps(Ghost5App* app) {
    view_dispatcher_switch_to_view(app->view_dispatcher, loadingView);

    for(int i = 0; i < app->wifiCount; i++) {
        free(app->wifiList[i].APssid);
    }
    free(app->wifiList);
    app->wifiList = NULL;
    app->wifiCount = 0;

    uart_helper_send(app->uart_helper, "LISTAP\n", 7);
    scanFinish = false;
    int times = 0;
    // LISTAP sweeps 38 channels at 280ms each (~10.6s) before emitting AP:/SCAN:OK.
    while(scanFinish == false && times < 50) {
        notification_message(app->notif, &seq_scan_pulse); // 5Ghost task8: dim-blue scanning pulse
        furi_delay_ms(500);
        times++;
    }
    notification_message(app->notif, &sequence_reset_blue); // 5Ghost task8: LED off when sweep ends
}

// Build the picker submenu from the current app->wifiList (5G only) with a Rescan row on top,
// then show it. Used both for a fresh sweep and for the cached-list reuse path.
static void handshake_build_menu(Ghost5App* app) {
    app->submenuIndex = 0;
    submenu_reset(app->submenu);
    submenu_set_header(app->submenu, "Pick 5G AP (handshake)");
    // Row 0 = Rescan (sentinel id); real AP rows follow at positions 1..N.
    submenu_add_item(app->submenu, "Rescan", GHOST_AP_RESCAN_ID, handshake_ap_item_callback, app);
    int first_ap_pos = 0; // submenu position of the first AP (0 = none -> cursor stays on Rescan)
    int pos = 1;          // running submenu position (row 0 is Rescan)
    for(int i = 0; i < app->wifiCount; i++) {
        // Handshake capture needs 5GHz (this chip can't hear the client's 2.4G uplink), so list
        // only 5G APs. Dropping the "5G|/2G|" prefix lets the SSID use the full row width — the
        // submenu left-aligns and trims with an ellipsis, so the prefix used to eat the visible head.
        if(app->wifiList[i].channel <= 14) continue;
        // same-SSID Mesh nodes: append the BSSID tail so duplicate names stay distinguishable
        bool dup = false;
        for(int j = 0; j < app->wifiCount; j++) {
            if(j != i && app->wifiList[j].channel > 14 &&
               strcmp(app->wifiList[j].APssid, app->wifiList[i].APssid) == 0) {
                dup = true;
                break;
            }
        }
        // strcat() is disabled in the official firmware API; build the row with snprintf instead.
        char temp[230];
        // Sanitize like the main scan list (wifiListView): non-ASCII (e.g. CJK) SSIDs render
        // blank in the 1-bit font and empty/hidden ones draw nothing — fold them the same way
        // so this picker never shows blank rows.
        char ssid[34];
        ghost_ui_ssid(app->wifiList[i].APssid, ssid, sizeof(ssid));
        if(!ssid[0]) strcpy(ssid, "<hidden>");
        const char* bssid = app->wifiList[i].APbssid;
        size_t bl = strlen(bssid);
        if(dup && ssid[0] && bl >= 2) {
            snprintf(temp, sizeof(temp), "%s .%s", ssid, bssid + bl - 2);
        } else {
            snprintf(temp, sizeof(temp), "%s", ssid);
        }
        // item id = real wifiList index (capture scene indexes wifiList by selectedWifi); passing i
        // instead of a running counter keeps the mapping correct after filtering out the 2.4G rows.
        submenu_add_item(app->submenu, temp, i, handshake_ap_item_callback, app);
        if(first_ap_pos == 0) first_ap_pos = pos;
        pos++;
    }
    submenu_set_selected_item(app->submenu, first_ap_pos); // land on the first AP, not Rescan
    view_dispatcher_switch_to_view(app->view_dispatcher, scannedWifisView);
}

// Submenu callback: the Rescan row re-sweeps in place; any other row = a picked target AP.
static void handshake_ap_item_callback(void* context, uint32_t index) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;
    if(index == GHOST_AP_RESCAN_ID) {
        // Re-sweep off the submenu callback: the scene's on_event does the heavy scan/rebuild.
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_AP_RESCAN);
        return;
    }
    app->selectedWifi = index;
    if(index < (uint32_t)app->wifiCount && !g5_tx_ch(app->wifiList[index].channel)) {
        g5_show_rx_only(app);
        return;
    }
    scene_manager_next_scene(app->scene_manager, handshakeCaptureScene);
}

// Select scene: reuse the cached AP list when returning from a capture (app->ap_reuse) so the
// picker opens instantly; otherwise sweep fresh (fresh entry from the main menu, or empty cache).
void handshake_select_scene_on_enter(void* context) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;
    app->menuIndex = 0;
    if(app->ap_reuse && app->wifiCount > 0) {
        app->ap_reuse = false;
        handshake_build_menu(app);
        return;
    }
    app->ap_reuse = false;
    handshake_scan_aps(app);
    handshake_build_menu(app);
}

bool handshake_select_scene_on_event(void* context, SceneManagerEvent event) {
    Ghost5App* app = context;
    if(event.type == SceneManagerEventTypeCustom && event.event == GHOST_EVT_AP_RESCAN) {
        handshake_scan_aps(app);
        handshake_build_menu(app);
        return true;
    }
    return false;
}

void handshake_select_scene_on_exit(void* context) {
    Ghost5App* app = context;
    submenu_reset(app->submenu);
}

static const char* ghost_hs_result_ui(const Ghost5App* app) {
    if(app->hs_error[0]) return app->hs_error;
    switch(app->hs_quality.result) {
    case G5CqResultNoEapol: return "No valid EAPOL";
    case G5CqResultNoBeacon: return "No target beacon";
    case G5CqResultNoM2: return "Missing client M2";
    case G5CqResultNoApNonce: return "Missing AP nonce";
    case G5CqResultStaMismatch: return "Mixed client frames";
    case G5CqResultReplayMismatch: return "Replay mismatch";
    case G5CqResultInvalidCrypto: return "Bad nonce / MIC";
    case G5CqResultWrongTarget: return "Wrong target";
    case G5CqResultMalformed: return "Malformed EAPOL";
    case G5CqResultCountMismatch: return "UART frame loss";
    case G5CqResultCapacity: return "Capture overflow";
    case G5CqResultValidM1M2:
    case G5CqResultValidM2M3: return "Valid capture";
    case G5CqResultLive: return "Capture stopped";
    }
    return "Capture stopped";
}

// Render the capture progress / result on app->widget. Main thread only.
static void handshake_draw(Ghost5App* app) {
    widget_reset(app->widget);
    char line[96];
    widget_add_string_element(app->widget, 64, 2, AlignCenter, AlignTop, FontPrimary, "Handshake");
    snprintf(line, sizeof(line), "%s  ch%d", app->hs_ssid, app->hs_channel);
    widget_add_string_element(app->widget, 64, 16, AlignCenter, AlignTop, FontSecondary, line);

    if(app->hs_done) {
        if(app->hs_path[0] != '\0') {
            const char* fn = strrchr(app->hs_path, '/');
            fn = fn ? fn + 1 : app->hs_path;
            char mstr[8];
            ghost_hs_m_str(g5_cq_message_mask(&app->hs_quality), mstr, sizeof(mstr));
            snprintf(
                line,
                sizeof(line),
                "%u unique  %s",
                app->hs_quality.record_count,
                g5_cq_pair_name(app->hs_quality.pair));
            widget_add_string_element(app->widget, 2, 27, AlignLeft, AlignTop, FontSecondary, line);
            // filename is ~30 chars; a text box wraps it across lines instead of clipping it
            widget_add_text_box_element(
                app->widget, 0, 39, 128, 25, AlignLeft, AlignTop, fn, false);
        } else {
            widget_add_string_element(
                app->widget, 64, 31, AlignCenter, AlignTop, FontSecondary, "Partial / rejected");
            widget_add_string_element(
                app->widget, 64, 45, AlignCenter, AlignTop, FontSecondary, ghost_hs_result_ui(app));
        }
    } else if(app->hs_stopping) {
        char mstr[8];
        ghost_hs_m_str(g5_cq_message_mask(&app->hs_quality), mstr, sizeof(mstr));
        snprintf(line, sizeof(line), "Stopping %d  %s", app->hs_eapol_count, mstr);
        widget_add_string_element(app->widget, 64, 30, AlignCenter, AlignTop, FontSecondary, line);
        widget_add_string_element(
            app->widget, 64, 46, AlignCenter, AlignTop, FontSecondary, "Validating evidence...");
    } else {
        char mstr[8];
        ghost_hs_m_str(g5_cq_message_mask(&app->hs_quality), mstr, sizeof(mstr));
        snprintf(
            line,
            sizeof(line),
            "EAPOL:%d%s  %s",
            app->hs_eapol_count,
            app->hs_have_beacon ? " B" : "",
            mstr);
        widget_add_string_element(app->widget, 64, 28, AlignCenter, AlignTop, FontSecondary, line);
        if(g5_cq_has_pair(&app->hs_quality)) {
            snprintf(
                line, sizeof(line), "Valid %s - Back", g5_cq_pair_name(app->hs_quality.pair));
            widget_add_string_element(app->widget, 64, 41, AlignCenter, AlignTop, FontSecondary, line);
        } else if(app->hs_channel > 0 && app->hs_channel <= 14) {
            widget_add_string_element(
                app->widget, 64, 41, AlignCenter, AlignTop, FontSecondary, "2.4G weak; 5G best");
        } else {
            widget_add_string_element(
                app->widget, 64, 41, AlignCenter, AlignTop, FontSecondary, "Reconnect a client");
        }
    }
    view_dispatcher_switch_to_view(app->view_dispatcher, handshakeView);
}

// Capture scene: deauth-trigger + capture the 4-way handshake into a PCAP on SD.
void handshake_capture_scene_on_enter(void* context) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;

    if(app->selectedWifi >= 0 && app->selectedWifi < app->wifiCount) {
        strncpy(
            app->hs_ssid, app->wifiList[app->selectedWifi].APssid, sizeof(app->hs_ssid) - 1);
        app->hs_ssid[sizeof(app->hs_ssid) - 1] = '\0';
        strncpy(
            app->hs_bssid, app->wifiList[app->selectedWifi].APbssid, sizeof(app->hs_bssid) - 1);
        app->hs_bssid[sizeof(app->hs_bssid) - 1] = '\0';
        app->hs_channel = app->wifiList[app->selectedWifi].channel;
    } else {
        app->hs_ssid[0] = '\0';
        app->hs_bssid[0] = '\0';
        app->hs_channel = 0;
    }

    // CAPTURE <bssid> <ch>: firmware sets channel, enables promisc, runs the
    // burst-then-listen deauth cycle, streams HSBEACON:/HSFRAME: back as hex.
    // Stay on this scene if DFS: next_scene(popup) from on_enter re-enters
    // capture on Back and loops. Picker already gates; this is belt-and-suspenders.
    if(!g5_tx_ch(app->hs_channel)) {
        app->ap_reuse = true;
        app->hs_done = true;
        snprintf(app->hs_error, sizeof(app->hs_error), "DFS ch — RX only");
        handshake_draw(app);
        return;
    }

    // Prepare the PCAP buffer on the main thread (no malloc in the UART callback).
    ghost_hs_begin(app);

    char cmd[40];
    snprintf(cmd, sizeof(cmd), "CAPTURE %s %d\n", app->hs_bssid, app->hs_channel);
    uart_helper_send(app->uart_helper, cmd, strlen(cmd));

    handshake_draw(app);
}

bool handshake_capture_scene_on_event(void* context, SceneManagerEvent event) {
    Ghost5App* app = context;
    if(event.type == SceneManagerEventTypeBack) {
        // While capturing, Back stops the capture and stays put until HSDONE flushes the PCAP
        // (firmware emits HSDONE only in response to CAPSTOP, and the flush runs in the HSDONE
        // event below). Once done, Back returns to the AP picker — which reuses the cached list
        // (app->ap_reuse) instead of the slow post-capture LISTAP re-sweep (~50s) that made the
        // old code jump to the main menu.
        if(app->hs_done) {
            app->ap_reuse = true;
            scene_manager_previous_scene(app->scene_manager);
            return true;
        }
        uart_helper_send(app->uart_helper, "CAPSTOP\n", 8);
        app->hs_stopping = true;
        handshake_draw(app); // show "Stopping, saving..."
        return true; // consume Back -> stay on this scene until HSDONE arrives
    }
    if(event.type == SceneManagerEventTypeCustom) {
        switch(event.event) {
        case GHOST_EVT_HS_UPDATE:
            handshake_draw(app);
            return true;
        case GHOST_EVT_HS_DONE:
            ghost_hs_flush(app); // write the PCAP to SD (main thread)
            app->hs_done = true;
            handshake_draw(app);
            return true;
        case GHOST_EVT_HS_ERROR:
            app->hs_done = true;
            ghost_hs_abort(app);
            handshake_draw(app);
            return true;
        default:
            break;
        }
    }
    return false;
}

void handshake_capture_scene_on_exit(void* context) {
    Ghost5App* app = context;
    // Stop the firmware only if we're leaving mid-capture (forced teardown / app exit). After a
    // normal finish (hs_done) the capture is already stopped, so skip a redundant CAPSTOP. Don't
    // free hs_buf here: an in-flight HSFRAME on the UART worker thread may still be writing into
    // it; the next ghost_hs_begin() frees the stale buffer and app_free() is the final backstop.
    if(!app->hs_done) uart_helper_send(app->uart_helper, "CAPSTOP\n", 8);
}

// ============================================================================
// 5Ghost B3: clientless PMKID capture. Same scene shape as the handshake flow
// (LISTAP picker -> capture screen sharing app->widget / handshakeView), but the
// firmware runs the active auth/assoc itself, so there is NO PCAP buffer: the UART
// worker parses the PMKID: status lines (pmkid_report.h), and the main thread
// classifies into 6 quality states + writes a hashcat 22000 record and JSON sidecar.
// PMKID needs no client and works on 2.4G + 5G, so the picker lists every band.
// ============================================================================

// Submenu callback: a target AP was picked -> capture its PMKID.
// Forward decls: the item callback (Rescan row) and the scan/build helpers reference each other.
static void pmkid_ap_item_callback(void* context, uint32_t index);
static void pmkid_scan_aps(Ghost5App* app);
static void pmkid_build_menu(Ghost5App* app);

// Passive LISTAP sweep into app->wifiList (blocking ~7.5-15s, dim-blue pulse while scanning).
static void pmkid_scan_aps(Ghost5App* app) {
    view_dispatcher_switch_to_view(app->view_dispatcher, loadingView);

    for(int i = 0; i < app->wifiCount; i++) {
        free(app->wifiList[i].APssid);
    }
    free(app->wifiList);
    app->wifiList = NULL;
    app->wifiCount = 0;

    uart_helper_send(app->uart_helper, "LISTAP\n", 7);
    scanFinish = false;
    int times = 0;
    while(scanFinish == false && times < 50) {
        notification_message(app->notif, &seq_scan_pulse);
        furi_delay_ms(500);
        times++;
    }
    notification_message(app->notif, &sequence_reset_blue);
}

// Build the picker submenu from the current app->wifiList (all bands) with a Rescan row on top.
static void pmkid_build_menu(Ghost5App* app) {
    app->submenuIndex = 0;
    submenu_reset(app->submenu);
    submenu_set_header(app->submenu, "Pick AP (PMKID)");
    // Row 0 = Rescan (sentinel id); real AP rows follow at positions 1..N.
    submenu_add_item(app->submenu, "Rescan", GHOST_AP_RESCAN_ID, pmkid_ap_item_callback, app);
    int first_ap_pos = 0; // submenu position of the first AP (0 = none -> cursor stays on Rescan)
    int pos = 1;          // running submenu position (row 0 is Rescan)
    for(int i = 0; i < app->wifiCount; i++) {
        // PMKID is clientless (the firmware auths itself), so list every band — no 5G filter.
        bool dup = false;
        for(int j = 0; j < app->wifiCount; j++) {
            if(j != i && strcmp(app->wifiList[j].APssid, app->wifiList[i].APssid) == 0) {
                dup = true;
                break;
            }
        }
        char temp[230];
        char ssid[34];
        ghost_ui_ssid(app->wifiList[i].APssid, ssid, sizeof(ssid));
        if(!ssid[0]) strcpy(ssid, "<hidden>");
        const char* bssid = app->wifiList[i].APbssid;
        size_t bl = strlen(bssid);
        if(dup && ssid[0] && bl >= 2) {
            snprintf(temp, sizeof(temp), "%s .%s", ssid, bssid + bl - 2);
        } else {
            snprintf(temp, sizeof(temp), "%s", ssid);
        }
        submenu_add_item(app->submenu, temp, i, pmkid_ap_item_callback, app);
        if(first_ap_pos == 0) first_ap_pos = pos;
        pos++;
    }
    submenu_set_selected_item(app->submenu, first_ap_pos); // land on the first AP, not Rescan
    view_dispatcher_switch_to_view(app->view_dispatcher, scannedWifisView);
}

// Submenu callback: the Rescan row re-sweeps in place; any other row = a picked target AP.
static void pmkid_ap_item_callback(void* context, uint32_t index) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;
    if(index == GHOST_AP_RESCAN_ID) {
        // Re-sweep off the submenu callback: the scene's on_event does the heavy scan/rebuild.
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_AP_RESCAN);
        return;
    }
    app->selectedWifi = index;
    if(index < (uint32_t)app->wifiCount && !g5_tx_ch(app->wifiList[index].channel)) {
        g5_show_rx_only(app);
        return;
    }
    scene_manager_next_scene(app->scene_manager, pmkidCaptureScene);
}

// Select scene: reuse the cached AP list when returning from a capture (app->ap_reuse) so the
// picker opens instantly; otherwise sweep fresh (fresh entry from the main menu, or empty cache).
void pmkid_select_scene_on_enter(void* context) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;
    app->menuIndex = 0;
    if(app->ap_reuse && app->wifiCount > 0) {
        app->ap_reuse = false;
        pmkid_build_menu(app);
        return;
    }
    app->ap_reuse = false;
    pmkid_scan_aps(app);
    pmkid_build_menu(app);
}

bool pmkid_select_scene_on_event(void* context, SceneManagerEvent event) {
    Ghost5App* app = context;
    if(event.type == SceneManagerEventTypeCustom && event.event == GHOST_EVT_AP_RESCAN) {
        pmkid_scan_aps(app);
        pmkid_build_menu(app);
        return true;
    }
    return false;
}

void pmkid_select_scene_on_exit(void* context) {
    Ghost5App* app = context;
    submenu_reset(app->submenu);
}

// Human-readable label for each PMKID quality state (capture screen).
static const char* pmkid_state_ui(G5PmkidState s) {
    switch(s) {
    case G5PmkidPending: return "Working...";
    case G5PmkidValid: return "Valid PMKID";
    case G5PmkidDuplicate: return "Duplicate";
    case G5PmkidWrongTarget: return "Wrong target";
    case G5PmkidPartial: return "AP refused";
    case G5PmkidTimeout: return "No response";
    case G5PmkidUnsupported: return "No PMKID (unfit AP)";
    case G5PmkidError: return "Bad command";
    }
    return "Working...";
}

// Short token for the JSON "state" field.
static const char* pmkid_state_token(G5PmkidState s) {
    switch(s) {
    case G5PmkidPending: return "pending";
    case G5PmkidValid: return "valid";
    case G5PmkidDuplicate: return "duplicate";
    case G5PmkidWrongTarget: return "wrong_target";
    case G5PmkidPartial: return "partial";
    case G5PmkidTimeout: return "timeout";
    case G5PmkidUnsupported: return "unsupported";
    case G5PmkidError: return "error";
    }
    return "pending";
}

// Render PMKID capture progress / result on app->widget (reuses handshakeView). Main thread only.
static void pmkid_draw(Ghost5App* app) {
    widget_reset(app->widget);
    char line[96];
    widget_add_string_element(app->widget, 64, 2, AlignCenter, AlignTop, FontPrimary, "PMKID");
    snprintf(line, sizeof(line), "%s  ch%d", app->pmkid_ssid, app->pmkid_channel);
    widget_add_string_element(app->widget, 64, 16, AlignCenter, AlignTop, FontSecondary, line);

    if(app->pmkid_done) {
        widget_add_string_element(
            app->widget, 64, 30, AlignCenter, AlignTop, FontSecondary, pmkid_state_ui(app->pmkid_state));
        if(app->pmkid_state == G5PmkidValid && app->pmkid_path[0]) {
            const char* fn = strrchr(app->pmkid_path, '/');
            fn = fn ? fn + 1 : app->pmkid_path;
            widget_add_text_box_element(app->widget, 0, 42, 128, 22, AlignLeft, AlignTop, fn, false);
        } else if(app->pmkid_report.reason[0]) {
            snprintf(line, sizeof(line), "%s", app->pmkid_report.reason);
            widget_add_string_element(app->widget, 64, 46, AlignCenter, AlignTop, FontSecondary, line);
        }
    } else {
        widget_add_string_element(
            app->widget, 64, 32, AlignCenter, AlignTop, FontSecondary, "Auth/Assoc -> M1...");
        widget_add_string_element(
            app->widget, 64, 46, AlignCenter, AlignTop, FontSecondary, "Back to stop");
    }
    view_dispatcher_switch_to_view(app->view_dispatcher, handshakeView);
}

// Write a .22000 (Valid only) + a 5ghost.capture.v1 JSON sidecar. Main thread only.
static void pmkid_flush(Ghost5App* app) {
    app->pmkid_path[0] = '\0';
    Storage* storage = furi_record_open(RECORD_STORAGE);
    ghost_ensure_data_dir(storage);
    char session_id[G5_SESSION_ID_MAX];
    char hc_path[112];
    char json_path[112];
    if(!ghost_resolve_session_id(app, session_id, sizeof(session_id)) ||
       !ghost_session_path(hc_path, sizeof(hc_path), G5AuditFilePmkid22000, session_id) ||
       !ghost_session_path(json_path, sizeof(json_path), G5AuditFilePmkidJson, session_id)) {
        furi_record_close(RECORD_STORAGE);
        return;
    }

    if(app->pmkid_state == G5PmkidValid) {
        // .22000 record on the HEAP too — same 2KB-stack discipline as the json below and as
        // ghost_hs_flush (its PCAP lives in app->hs_buf on the heap, never on the stack).
        char* record = malloc(200);
        if(record) {
            size_t rn = g5_pmkid_build_22000(&app->pmkid_report, record, 200);
            if(rn > 0 && rn + 1 < 200) {
                record[rn] = '\n';
                if(ghost_evidence_atomic_write(storage, hc_path, (const uint8_t*)record, rn + 1)) {
                    strncpy(app->pmkid_path, hc_path, sizeof(app->pmkid_path) - 1);
                    app->pmkid_path[sizeof(app->pmkid_path) - 1] = '\0';
                }
            }
            free(record);
        }
    }

    // JSON on the HEAP, not the 2KB FAP stack — mirrors ghost_hs_flush (malloc(1024)).
    // A stack json[512] plus the atomic write's rename overflowed on real hardware.
    char* json = malloc(1024);
    if(json) {
        G5PmkidJsonIn in = {
            .session_id = session_id,
            .ssid = app->pmkid_ssid,
            .bssid = app->pmkid_bssid,
            .channel = app->pmkid_channel,
            .fw_version = app->fw_version,
            .fw_caps = app->fw_caps,
            .result = pmkid_state_token(app->pmkid_state),
            .essid_hex = app->pmkid_report.essid_hex,
            .pmkid_hex = app->pmkid_report.pmkid_hex,
            .reason = app->pmkid_report.reason,
            .have_22000 = app->pmkid_path[0] != '\0',
        };
        const size_t jn = g5_audit_build_pmkid_json(&in, json, 1024);
        if(jn > 0)
            ghost_evidence_atomic_write(storage, json_path, (const uint8_t*)json, jn);
        free(json);
    }
    furi_record_close(RECORD_STORAGE);
}

// Capture scene: send PMKID <bssid> <ch>, then let the UART worker drive the result.
void pmkid_capture_scene_on_enter(void* context) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;

    if(app->selectedWifi >= 0 && app->selectedWifi < app->wifiCount) {
        strncpy(app->pmkid_ssid, app->wifiList[app->selectedWifi].APssid, sizeof(app->pmkid_ssid) - 1);
        app->pmkid_ssid[sizeof(app->pmkid_ssid) - 1] = '\0';
        strncpy(app->pmkid_bssid, app->wifiList[app->selectedWifi].APbssid, sizeof(app->pmkid_bssid) - 1);
        app->pmkid_bssid[sizeof(app->pmkid_bssid) - 1] = '\0';
        app->pmkid_channel = app->wifiList[app->selectedWifi].channel;
    } else {
        app->pmkid_ssid[0] = '\0';
        app->pmkid_bssid[0] = '\0';
        app->pmkid_channel = 0;
    }
    memset(&app->pmkid_report, 0, sizeof(app->pmkid_report));
    app->pmkid_state = G5PmkidPending;
    app->pmkid_done = false;
    app->pmkid_path[0] = '\0';

    if(!g5_tx_ch(app->pmkid_channel)) {
        app->ap_reuse = true;
        app->pmkid_done = true;
        app->pmkid_state = G5PmkidError;
        snprintf(app->pmkid_report.reason, sizeof(app->pmkid_report.reason), "DFS ch — RX only");
        pmkid_draw(app);
        return;
    }
    char cmd[40];
    snprintf(cmd, sizeof(cmd), "PMKID %s %d\n", app->pmkid_bssid, app->pmkid_channel);
    uart_helper_send(app->uart_helper, cmd, strlen(cmd));

    pmkid_draw(app);
}

bool pmkid_capture_scene_on_event(void* context, SceneManagerEvent event) {
    Ghost5App* app = context;
    if(event.type == SceneManagerEventTypeBack) {
        // Return to the AP picker (not the main menu) and reuse the cached list; on_exit sends
        // STOP if we're still mid-capture. Avoids the slow post-capture LISTAP re-sweep.
        app->ap_reuse = true;
        scene_manager_previous_scene(app->scene_manager);
        return true;
    }
    if(event.type == SceneManagerEventTypeCustom) {
        switch(event.event) {
        case GHOST_EVT_PMKID_UPDATE:
            pmkid_draw(app);
            return true;
        case GHOST_EVT_PMKID_DONE: {
            if(app->pmkid_report.ok) {
                uint8_t target[6];
                const bool have_target = parse_mac(app->pmkid_bssid, target);
                bool seen = false;
                for(int i = 0; i < app->pmkid_seen_count; i++) {
                    if(strncmp(app->pmkid_seen[i], app->pmkid_bssid, sizeof(app->pmkid_seen[0])) == 0) {
                        seen = true;
                        break;
                    }
                }
                app->pmkid_state =
                    g5_pmkid_classify_ok(&app->pmkid_report, have_target ? target : NULL, seen);
                const int cap = (int)(sizeof(app->pmkid_seen) / sizeof(app->pmkid_seen[0]));
                if(app->pmkid_state == G5PmkidValid && app->pmkid_seen_count < cap) {
                    strncpy(
                        app->pmkid_seen[app->pmkid_seen_count], app->pmkid_bssid,
                        sizeof(app->pmkid_seen[0]) - 1);
                    app->pmkid_seen[app->pmkid_seen_count][sizeof(app->pmkid_seen[0]) - 1] = '\0';
                    app->pmkid_seen_count++;
                }
            } else {
                app->pmkid_state = app->pmkid_report.state;
            }
            app->pmkid_done = true;
            pmkid_flush(app);
            pmkid_draw(app);
            return true;
        }
        default:
            break;
        }
    }
    return false;
}

void pmkid_capture_scene_on_exit(void* context) {
    Ghost5App* app = context;
    if(!app->pmkid_done) uart_helper_send(app->uart_helper, "STOP\n", 5);
}

// ============================================================================
// 5Ghost P8: Channel Analyzer — per-band congestion histogram + best-channel pick.
// Reuses the AP list from the last "Scan Wifi" (LISTAP fills app->wifiList). Own Canvas
// View + view model; Left/Right toggles the 2.4GHz / 5GHz band. 128x64. No firmware
// change — channel/RSSI already arrive in the AP rows.
// ============================================================================
typedef struct {
    uint8_t count24[14]; // APs per 2.4GHz channel; indices [1..13]
    uint8_t max24; // tallest 2.4G channel count (bar scaling)
    int best24; // recommended non-overlapping 2.4G channel (1/6/11), -1 if none
    int total24;
    // 5GHz uses a sparse axis: only channels actually seen, in parallel arrays.
    uint8_t ch5[32]; // distinct 5G channel numbers present (25 legal 20 MHz + headroom)
    uint8_t cnt5[32]; // AP count per present 5G channel
    int n5; // number of distinct 5G channels
    uint8_t max5;
    int best5; // least-busy present 5G channel, -1 if none
    int total5;
} ChannelStats;

typedef struct {
    ChannelStats s;
    int scroll; // horizontal pan offset (first visible channel column)
    int nu; // number of present channels on the unified axis (for clamping)
} ChannelModel;

#define CHAN_SLOT 16 // px per channel column (fits a 3-digit 5G channel label)
#define CHAN_VIS  7 // channel columns visible at once

static void channel_compute_stats(ChannelStats* s, Ghost5App* app) {
    memset(s, 0, sizeof(*s));
    s->best24 = -1;
    s->best5 = -1;
    for(int i = 0; i < app->wifiCount; i++) {
        int ch = app->wifiList[i].channel;
        if(ch >= 1 && ch <= 13) {
            s->count24[ch]++;
            s->total24++;
            if(s->count24[ch] > s->max24) s->max24 = s->count24[ch];
        } else if(ch > 14) {
            s->total5++;
            int j = 0;
            for(; j < s->n5; j++)
                if(s->ch5[j] == ch) break;
            if(j == s->n5 && s->n5 < (int)sizeof(s->ch5)) {
                s->ch5[s->n5] = ch;
                s->n5++;
            }
            if(j < (int)sizeof(s->ch5)) {
                s->cnt5[j]++;
                if(s->cnt5[j] > s->max5) s->max5 = s->cnt5[j];
            }
        }
    }
    // Best 2.4G: among 1/6/11, fewest APs within +/-2 channels (~22 MHz overlap). Ties -> lower.
    if(s->total24 > 0) {
        const int cand[3] = {1, 6, 11};
        int best_cost = 100000;
        for(int k = 0; k < 3; k++) {
            int c = cand[k], cost = 0;
            for(int ch = c - 2; ch <= c + 2; ch++)
                if(ch >= 1 && ch <= 13) cost += s->count24[ch];
            if(cost < best_cost) {
                best_cost = cost;
                s->best24 = c;
            }
        }
    }
    // Sort present 5G channels ascending (insertion sort; n5 <= 32) so the list reads in order.
    for(int a = 1; a < s->n5; a++) {
        uint8_t kc = s->ch5[a], kn = s->cnt5[a];
        int b = a - 1;
        while(b >= 0 && s->ch5[b] > kc) {
            s->ch5[b + 1] = s->ch5[b];
            s->cnt5[b + 1] = s->cnt5[b];
            b--;
        }
        s->ch5[b + 1] = kc;
        s->cnt5[b + 1] = kn;
    }
    // Best 5G: the least-busy channel we actually saw (5G channels don't overlap). Ties -> lower.
    if(s->n5 > 0) {
        int best_cost = 100000;
        for(int j = 0; j < s->n5; j++) {
            if(s->cnt5[j] < best_cost ||
               (s->cnt5[j] == best_cost && s->best5 > 0 && s->ch5[j] < s->best5)) {
                best_cost = s->cnt5[j];
                s->best5 = s->ch5[j];
            }
        }
    }
}

static void channel_analyzer_draw_callback(Canvas* canvas, void* model) {
    ChannelModel* m = model;
    ChannelStats* s = &m->s;
    canvas_clear(canvas);
    canvas_set_color(canvas, ColorBlack);

    int total = s->total24 + s->total5;
    if(total == 0) {
        ghost_ui_header(canvas, "Channel Map", NULL);
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 64, 32, AlignCenter, AlignCenter, "No scan data");
        canvas_set_font(canvas, FontSecondary);
        canvas_draw_str_aligned(canvas, 64, 46, AlignCenter, AlignCenter, "Run Scan first");
        return;
    }

    char hstat[20]; // -Wformat-truncation headroom for "%d APs"
    snprintf(hstat, sizeof(hstat), "%d APs", total);
    ghost_ui_header(canvas, "Channel Map", hstat);

    // Unified channel axis: present 2.4G channels, then present 5G channels (already sorted).
    // One horizontal spectrum; bar height = AP count; Left/Right pans across all channels.
    uint8_t uch[40], ucnt[40];
    bool ubest[40];
    int nu = 0;
    for(int ch = 1; ch <= 13 && nu < 40; ch++) {
        if(s->count24[ch] > 0) {
            uch[nu] = ch;
            ucnt[nu] = s->count24[ch];
            ubest[nu] = (ch == s->best24);
            nu++;
        }
    }
    int first5 = nu; // index where 5G begins (for the band divider)
    for(int j = 0; j < s->n5 && nu < 40; j++) {
        uch[nu] = s->ch5[j];
        ucnt[nu] = s->cnt5[j];
        ubest[nu] = (s->ch5[j] == s->best5);
        nu++;
    }
    int maxc = s->max24 > s->max5 ? s->max24 : s->max5;
    if(maxc < 1) maxc = 1;

    const int base_y = 47, top_y = 16;
    int start = m->scroll;
    if(start < 0) start = 0;
    if(start > nu - 1) start = nu - 1;
    int end = start + CHAN_VIS;
    if(end > nu) end = nu;
    canvas_set_font(canvas, FontSecondary);
    for(int i = start; i < end; i++) {
        int x = 6 + (i - start) * CHAN_SLOT;
        int h = 1 + (ucnt[i] * (base_y - top_y)) / maxc;
        int bw = CHAN_SLOT - 5;
        if(ubest[i])
            canvas_draw_box(canvas, x, base_y - h, bw, h); // filled = recommended
        else
            canvas_draw_frame(canvas, x, base_y - h, bw, h); // outline = busy
        char cl[6];
        snprintf(cl, sizeof(cl), "%d", uch[i]);
        int clw = canvas_string_width(canvas, cl);
        canvas_draw_str(canvas, x + (bw - clw) / 2, base_y + 9, cl); // channel num centered under bar
        if(i == first5 && i > start)
            canvas_draw_line(canvas, x - 3, top_y, x - 3, base_y); // 2.4G | 5G divider
    }
    canvas_draw_line(canvas, 0, base_y, 127, base_y); // baseline

    // pan arrows when there are channels off-screen
    if(start > 0) canvas_draw_str(canvas, 0, 33, "<");
    if(end < nu) canvas_draw_str(canvas, 123, 33, ">");

    // footer: per-band best-channel recommendations. With both bands, split the line — 2.4G
    // left-aligned, 5G right-aligned — so the two numbers spread across the row instead of
    // crowding into "Best 2.4G:6 5G:40" jammed together (task#12, on-device).
    if(s->total24 > 0 && s->total5 > 0) {
        char f24[20], f5[16];
        snprintf(f24, sizeof(f24), "Best 2.4G: %d", s->best24);
        snprintf(f5, sizeof(f5), "5G: %d", s->best5);
        canvas_draw_str(canvas, 2, 63, f24);
        canvas_draw_str(canvas, 124 - canvas_string_width(canvas, f5), 63, f5);
    } else {
        char foot[28];
        if(s->total24 > 0)
            snprintf(foot, sizeof(foot), "Best 2.4G channel %d", s->best24);
        else
            snprintf(foot, sizeof(foot), "Best 5G channel %d", s->best5);
        canvas_draw_str(canvas, 2, 63, foot);
    }
}

static bool channel_analyzer_input_callback(InputEvent* event, void* context) {
    Ghost5App* app = context;
    // Left/Up pans left, Right/Down pans right across the unified channel spectrum.
    // Back falls through (return false) to the dispatcher's navigation handler.
    if(event->type != InputTypeShort && event->type != InputTypeRepeat) return false;
    bool handled = false;
    with_view_model(
        app->channel_view,
        ChannelModel * m,
        {
            int maxs = m->nu - CHAN_VIS;
            if(maxs < 0) maxs = 0;
            if(event->key == InputKeyLeft || event->key == InputKeyUp) {
                if(m->scroll > 0) m->scroll--;
                handled = true;
            } else if(event->key == InputKeyRight || event->key == InputKeyDown) {
                if(m->scroll < maxs) m->scroll++;
                handled = true;
            }
        },
        true);
    return handled;
}

void channel_analyzer_scene_on_enter(void* context) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;
    with_view_model(
        app->channel_view,
        ChannelModel * m,
        {
            channel_compute_stats(&m->s, app);
            int nu = 0;
            for(int ch = 1; ch <= 13; ch++)
                if(m->s.count24[ch] > 0) nu++;
            nu += m->s.n5;
            m->nu = nu;
            m->scroll = 0;
        },
        true);
    view_dispatcher_switch_to_view(app->view_dispatcher, channelAnalyzerView);
}
bool channel_analyzer_scene_on_event(void* context, SceneManagerEvent event) {
    UNUSED(context);
    UNUSED(event);
    return false; // Back is handled by the dispatcher's navigation callback -> previous scene
}
void channel_analyzer_scene_on_exit(void* context) {
    UNUSED(context);
}

// Scene event-handler arrays
// ── 5Ghost P6: BLE detector (CSV export + list view + scenes) ──────────────
// Mirrors the Wi-Fi scan/list path. Passive: FAP sends BLESCAN and renders what
// the module streams back. Reuses csv_escape / ghost_ensure_data_dir /
// ghost_notify_saved / ghost_ui_header / ghost_ui_ssid / seq_scan_pulse.

// 5Ghost P6: map a Bluetooth SIG company identifier (the manufacturer-data prefix
// carried in the advert) to a short vendor name for the list/detail views. IDs are
// from the official Bluetooth SIG Assigned Numbers registry (Nordic bluetooth-
// numbers-database mirror). Returns NULL for unknown IDs or mfg==0 (no mfg data).
static const char* ble_vendor_name(unsigned mfg) {
    switch(mfg) {
    case 0x004C: return "Apple";
    case 0x0006: return "Microsoft";
    case 0x00E0: return "Google";
    case 0x0075: return "Samsung";
    case 0x038F: return "Xiaomi";
    case 0x027D: return "Huawei";
    case 0x012D: return "Sony";
    case 0x009E: return "Bose";
    case 0x0087: return "Garmin";
    case 0x067C: return "Tile";
    case 0x01DA: return "Logitech";
    case 0x0171: return "Amazon";
    case 0x0059: return "Nordic";
    case 0x005D: return "Realtek";
    case 0x02E5: return "Espressif";
    case 0x0553: return "Nintendo";
    case 0x049C: return "Sennheiser";
    case 0x075A: return "Harman";
    default: return NULL;
    }
}

// 5Ghost FUNC-D: WiFi AP vendor from the BSSID's OUI (first 3 MAC bytes = the
// 24-bit IEEE Organizationally Unique Identifier). This is a DIFFERENT namespace
// from ble_vendor_name()'s 16-bit Bluetooth SIG company id — a MAC OUI and a SIG
// company id never coincide, so the two tables share nothing but the lookup shape.
// Curated top-N of common home/SOHO router makers, NOT the full registry (Flipper
// flash is finite — TP-Link alone holds 261 OUIs). Every prefix below is a real
// IEEE-registered assignment (source: Netify MAC vendor DB / IEEE OUI registry,
// fetched 2026-07). A BSSID whose OUI isn't listed shows no vendor — the full MAC
// is already on the card and carries the OUI for anyone who wants to look it up.
// APbssid is always upper-hex "AA:BB:CC:.." (firmware prints %02X, recon.cpp), so
// a plain strncmp on the 8-char "AA:BB:CC" prefix suffices — no case folding.
static const struct {
    const char* oui;
    const char* vendor;
} g5_wifi_oui[] = {
    {"00:14:78", "TP-Link"},  {"00:1D:0F", "TP-Link"},  {"14:CC:20", "TP-Link"},
    {"14:CF:92", "TP-Link"},  {"50:C7:BF", "TP-Link"},  {"60:3A:7C", "TP-Link"},
    {"00:09:5B", "Netgear"},  {"00:14:6C", "Netgear"},  {"00:1B:2F", "Netgear"},
    {"20:0C:C8", "Netgear"},  {"2C:30:33", "Netgear"},  {"A0:40:A0", "Netgear"},
    {"00:0D:88", "D-Link"},   {"00:0F:3D", "D-Link"},   {"00:11:95", "D-Link"},
    {"00:17:9A", "D-Link"},   {"00:1B:11", "D-Link"},   {"1C:7E:E5", "D-Link"},
    {"00:1B:FC", "ASUS"},     {"00:1E:8C", "ASUS"},     {"00:22:15", "ASUS"},
    {"00:24:8C", "ASUS"},     {"04:D9:F5", "ASUS"},     {"2C:4D:54", "ASUS"},
    {"50:4F:3B", "Xiaomi"},   {"5C:40:71", "Xiaomi"},   {"A4:C3:BE", "Xiaomi"},
    {"FC:43:45", "Xiaomi"},
    {"00:18:82", "Huawei"},   {"00:25:68", "Huawei"},   {"10:86:F4", "Huawei"},
    {"28:45:AC", "Huawei"},   {"4C:2B:3B", "Huawei"},   {"58:B1:8F", "Huawei"},
    {"08:40:F3", "Tenda"},    {"50:0F:F5", "Tenda"},    {"50:2B:73", "Tenda"},
    {"B0:DF:C1", "Tenda"},    {"C8:3A:35", "Tenda"},    {"D8:32:14", "Tenda"},
    {"00:15:6D", "Ubiquiti"}, {"00:27:22", "Ubiquiti"}, {"04:18:D6", "Ubiquiti"},
    {"24:A4:3C", "Ubiquiti"}, {"44:D9:E7", "Ubiquiti"}, {"F0:9F:C2", "Ubiquiti"},
    {"00:0C:41", "Linksys"},  {"00:14:BF", "Linksys"},  {"00:18:39", "Linksys"},
    {"00:1A:70", "Linksys"},  {"00:21:29", "Linksys"},  {"00:23:69", "Linksys"},
    {"00:0C:42", "MikroTik"}, {"08:55:31", "MikroTik"}, {"2C:C8:1B", "MikroTik"},
    {"48:8F:5A", "MikroTik"}, {"6C:3B:6B", "MikroTik"}, {"74:4D:28", "MikroTik"},
    {"00:1A:11", "Google"},   {"3C:5A:B4", "Google"},   {"54:60:09", "Google"},
    {"94:95:A0", "Google"},   {"D8:6C:63", "Google"},   {"F4:F5:E8", "Google"},
    {"00:71:47", "Amazon"},   {"34:D2:70", "Amazon"},   {"44:65:0D", "Amazon"},
    {"68:37:E9", "Amazon"},   {"74:75:48", "Amazon"},   {"FC:65:DE", "Amazon"},
};

// Return the vendor for a BSSID whose OUI is in the curated table, else NULL.
// strncmp (not strncasecmp) — APbssid is canonical upper hex; also dodges the
// str*casecmp functions some official firmware builds strip. bssid shorter than
// the prefix is safe: strncmp stops at the embedded NUL and reports a mismatch.
static const char* wifi_oui_vendor(const char* bssid) {
    if(!bssid) return NULL;
    for(size_t i = 0; i < sizeof(g5_wifi_oui) / sizeof(g5_wifi_oui[0]); i++) {
        if(strncmp(bssid, g5_wifi_oui[i].oui, 8) == 0) return g5_wifi_oui[i].vendor;
    }
    return NULL;
}

static void ghost_export_ble_csv(Ghost5App* app) {
    if(app->bleCount <= 0) return;
    Storage* storage = furi_record_open(RECORD_STORAGE);
    ghost_ensure_data_dir(storage);
    DateTime dt;
    furi_hal_rtc_get_datetime(&dt);
    char path[96];
    snprintf(
        path,
        sizeof(path),
        GHOST_DATA_DIR "/ble_%04d%02d%02d_%02d%02d%02d.csv",
        dt.year,
        dt.month,
        dt.day,
        dt.hour,
        dt.minute,
        dt.second);
    File* file = storage_file_alloc(storage);
    bool ok = false;
    if(storage_file_open(file, path, FSAM_WRITE, FSOM_CREATE_ALWAYS)) {
        const char* hdr = "idx,type,addr,rssi,mfg,vendor,name\n";
        storage_file_write(file, hdr, strlen(hdr));
        char name_esc[48];
        char row[128];
        for(int i = 0; i < app->bleCount; i++) {
            csv_escape(app->bleList[i].name, name_esc, sizeof(name_esc));
            const char* vend = ble_vendor_name(app->bleList[i].mfg);
            int n = snprintf(
                row,
                sizeof(row),
                "%d,%c,%s,%d,%04X,%s,%s\n",
                app->bleList[i].idx,
                app->bleList[i].type,
                app->bleList[i].addr,
                app->bleList[i].rssi,
                app->bleList[i].mfg,
                vend ? vend : "",
                name_esc);
            if(n > 0) storage_file_write(file, row, (size_t)n);
        }
        app->ble_exported = true;
        ok = true;
        FURI_LOG_I(TAG, "5Ghost: BLE scan exported -> %s", path);
    } else {
        FURI_LOG_E(TAG, "5Ghost: BLE export failed: %s", storage_file_get_error_desc(file));
    }
    storage_file_close(file);
    storage_file_free(file);
    furi_record_close(RECORD_STORAGE);
    ghost_notify_saved(ok);
}

// BLE list rows: one-char type badge (F=Flipper, A=Find My tracker, blank=plain),
// name (or address when unnamed), RSSI. Header carries the Flipper/tracker tally.
// 5Ghost: BLE list ordering — defensive-first. Trackers ('A') then Flippers
// ('F') sort to the top (the signals a user actually cares about), plain
// devices after; within a class, stronger RSSI first. Applied once when the
// list scene opens (single-threaded, scan already finished — no race).
static int ble_type_rank(char t) {
    return (t == 'A') ? 0 : (t == 'F') ? 1 : 2;
}
// Insertion sort (Flipper's API disables qsort). bleCount is small (tens) so
// O(n^2) is fine. Stable: equal rank + equal RSSI keeps discovery order.
static void ble_sort_list(BLEDeviceDetails* a, int n) {
    for(int i = 1; i < n; i++) {
        BLEDeviceDetails key = a[i];
        int kr = ble_type_rank(key.type);
        int j = i - 1;
        while(j >= 0) {
            int jr = ble_type_rank(a[j].type);
            bool after = (jr > kr) || (jr == kr && a[j].rssi < key.rssi);
            if(!after) break;
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = key;
    }
}

// 阶段1: "alarms only" filter. Because ble_sort_list orders trackers ('A') then
// Flippers ('F') ahead of every plain device, the alarm devices form a contiguous
// prefix of the sorted list — so filtering is just capping the effective length to
// the alarm count, with no index remap (the list stays sorted from the scene's
// on_enter). Requires the list to be sorted; only ever read after ble_list_scene_on_enter.
static int ble_alarm_count(Ghost5App* app) {
    int n = 0;
    for(int i = 0; i < app->bleCount; i++)
        if(app->bleList[i].type == 'F' || app->bleList[i].type == 'A') n++;
    return n;
}
static int ble_eff_count(Ghost5App* app) {
    return app->ble_filter_alarms ? ble_alarm_count(app) : app->bleCount;
}

// 5Ghost anti-stalk: 把"存在追踪器"细化为"是否疑似跟踪你"。参考 AirGuard
// (TU Darmstadt SEEMOO): 一个 tracker 只有近距离 + 跨多轮 BLESCAN 持续出现,
// 才是 stalking 信号,而非路过的别人的 AirTag。RSSI + seen 都来自现有累积逻辑,
// 零新结构体字段。0 = 非跟踪信号;1 = 近距离追踪器(单轮,仅提示);
// 2 = 疑似跟踪(近距离 + 持续,触发震动告警)。
#define BLE_STALK_NEAR_RSSI (-70) // 近距离阈值(约数米内)
#define BLE_STALK_MIN_ROUNDS 3    // 跨多少轮 BLESCAN 持续出现算"跟随"
static int ble_stalk_level(const BLEDeviceDetails* d) {
    if(d->type != 'A') return 0;
    if(d->rssi < BLE_STALK_NEAR_RSSI) return 0;
    return (d->seen >= BLE_STALK_MIN_ROUNDS) ? 2 : 1;
}
// Count devices at stalk level 2 (near + persistent). Drives the vibro alarm and
// the "!STALK n" header chip. Read only after ble_list_scene_on_enter (sorted).
static int ble_stalk_count(Ghost5App* app) {
    int n = 0;
    for(int i = 0; i < app->bleCount; i++)
        if(ble_stalk_level(&app->bleList[i]) >= 2) n++;
    return n;
}

static void ble_list_draw_callback(Canvas* canvas, void* model) {
    ListModel* m = model;
    Ghost5App* app = m->app;
    canvas_clear(canvas);
    canvas_set_color(canvas, ColorBlack);

    if(!app || app->bleCount <= 0) {
        const char* main_s;
        const char* sub_s;
        ghost_uart_empty_copy(
            app,
            app && app->ble_scan_timed_out,
            "No BLE devices",
            "Press OK to scan",
            &main_s,
            &sub_s);
        ghost_ui_header(canvas, "BLE", NULL);
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 64, 32, AlignCenter, AlignCenter, main_s);
        canvas_set_font(canvas, FontSecondary);
        canvas_draw_str_aligned(canvas, 64, 46, AlignCenter, AlignCenter, sub_s);
        return;
    }

    int nf = 0, na = 0;
    for(int i = 0; i < app->bleCount; i++) {
        if(app->bleList[i].type == 'F') nf++;
        else if(app->bleList[i].type == 'A') na++;
    }
    int eff = ble_eff_count(app); // 阶段1: rows shown = all, or alarms-only prefix

    // 阶段1: filter is on but this scan has no Flipper/tracker — guide back to the
    // full list instead of a blank screen (Left toggles the filter).
    if(app->ble_filter_alarms && eff <= 0) {
        ghost_ui_header(canvas, "Alerts 0", NULL);
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 64, 32, AlignCenter, AlignCenter, "No alarms");
        canvas_set_font(canvas, FontSecondary);
        canvas_draw_str_aligned(canvas, 64, 46, AlignCenter, AlignCenter, "Left: show all");
        return;
    }

    // Header: left title = current view ("BLE n" all / "Alerts n" filtered). F/A stay
    // hidden while zero (they are 0 ~90% of the time = noise); the moment a Flipper or a
    // Find My tracker is seen, the right ">scan" hint is replaced by an inverted alert
    // chip so a detection reads as an alarm, not a tally. Tracker takes priority — it is
    // the defensive anti-stalk signal. When filtered, the title already carries the
    // alarm count, so the right slot hints that Left returns to the full list.
    char title[20]; // "Alerts " + int; wider than "BLE %d" to satisfy -Wformat-truncation
    if(app->ble_filter_alarms) {
        snprintf(title, sizeof(title), "Alerts %d", eff);
        ghost_ui_header(canvas, title, "Left=all");
    } else {
        snprintf(title, sizeof(title), "BLE %d", app->bleCount);
        if(nf > 0 || na > 0) {
            char chip[28]; // headroom so -Wformat-truncation is satisfied (nf/na are <= 48)
            int ns = ble_stalk_count(app); // anti-stalk: near + persistent trackers
            if(ns > 0)
                snprintf(chip, sizeof(chip), "!STALK %d", ns);
            else if(nf > 0 && na > 0)
                snprintf(chip, sizeof(chip), "!F%d T%d", nf, na);
            else if(na > 0)
                snprintf(chip, sizeof(chip), "!Track %d", na);
            else
                snprintf(chip, sizeof(chip), "!Flip %d", nf);
            ghost_ui_header(canvas, title, NULL);
            canvas_set_font(canvas, FontSecondary);
            int w = canvas_string_width(canvas, chip);
            canvas_draw_box(canvas, 124 - w - 2, 1, w + 3, 11);
            canvas_set_color(canvas, ColorWhite);
            canvas_draw_str(canvas, 124 - w, 9, chip);
            canvas_set_color(canvas, ColorBlack);
        } else {
            ghost_ui_header(canvas, title, ">scan");
        }
    }

    for(int row = 0; row < GHOST_LIST_ROWS; row++) {
        int i = m->top + row;
        if(i >= eff) break;
        BLEDeviceDetails* d = &app->bleList[i];
        int y = GHOST_LIST_TOP + row * GHOST_LIST_RH;
        int yb = y + GHOST_LIST_RH - 3;
        bool sel = (i == m->sel);
        if(sel) {
            canvas_set_color(canvas, ColorBlack);
            canvas_draw_box(canvas, 0, y, 121, GHOST_LIST_RH);
            canvas_set_color(canvas, ColorWhite);
        } else {
            canvas_set_color(canvas, ColorBlack);
        }
        canvas_set_font(canvas, FontSecondary);

        int sl = ble_stalk_level(d);
        const char* badge = (d->type == 'F') ? "F" :
                            (sl >= 2)        ? "!" : // anti-stalk: near + persistent tracker
                            (d->type == 'A') ? "A" :
                                               "";
        int textx = 4;
        if(badge[0]) {
            canvas_draw_str(canvas, 4, yb, badge);
            textx = 13;
        }

        char rs[12];
        if(d->rssi < 0)
            snprintf(rs, sizeof(rs), "%d", d->rssi);
        else
            strcpy(rs, "--");
        int rw = canvas_string_width(canvas, rs);
        canvas_draw_str(canvas, 116 - rw, yb, rs);

        char label[40];
        label[0] = '\0';
        if(d->name[0] && strcmp(d->name, "-") != 0) ghost_ui_ssid(d->name, label, sizeof(label));
        if(!label[0]) {
            // no advertised name: fall back to "~Vendor" from the mfg company id so a
            // plain device reads as e.g. ~Apple instead of a raw MAC; MAC if unknown.
            const char* v = ble_vendor_name(d->mfg);
            if(v) {
                label[0] = '~';
                strncpy(label + 1, v, sizeof(label) - 2);
                label[sizeof(label) - 1] = '\0';
            }
        }
        if(!label[0]) {
            strncpy(label, d->addr, sizeof(label) - 1);
            label[sizeof(label) - 1] = '\0';
        }
        int labelw = 112 - rw - textx;
        while(label[0] && canvas_string_width(canvas, label) > labelw)
            label[strlen(label) - 1] = '\0';
        canvas_draw_str(canvas, textx, yb, label);
    }

    canvas_set_color(canvas, ColorBlack);
    if(eff > GHOST_LIST_ROWS)
        elements_scrollbar_pos(canvas, 125, GHOST_LIST_TOP, 64 - GHOST_LIST_TOP, m->sel, eff);
}

static bool ble_list_input_callback(InputEvent* event, void* context) {
    Ghost5App* app = context;
    if(event->type != InputTypeShort && event->type != InputTypeRepeat) return false;

    if(app->bleCount <= 0) {
        if(event->key == InputKeyOk) {
            app->ble_accumulate = false; // empty list: re-scan as a fresh session
            scene_manager_next_scene(app->scene_manager, bleScanScene);
            return true;
        }
        return false;
    }

    // OK opens the per-device detail page; Right re-scans in place. Suppressed when the
    // alarms-only view is empty (nothing selectable — the draw shows "No alarms").
    if(event->key == InputKeyOk) {
        if(ble_eff_count(app) <= 0) return true;
        with_view_model(app->ble_list_view, ListModel * m, { app->selectedBle = m->sel; }, false);
        scene_manager_next_scene(app->scene_manager, bleInfoScene);
        return true;
    }
    if(event->key == InputKeyRight) {
        app->ble_accumulate = true; // 5Ghost FUNC-C: re-scan merges into the accumulated list (dedup by MAC)
        scene_manager_next_scene(app->scene_manager, bleScanScene);
        return true;
    }
    // 阶段1: Left toggles the alarms-only filter. Alarm devices are the sorted prefix,
    // so this just changes the effective length; reset sel/top to a valid 0 either way.
    if(event->key == InputKeyLeft) {
        app->ble_filter_alarms = !app->ble_filter_alarms;
        with_view_model(
            app->ble_list_view, ListModel * m, { m->sel = 0; m->top = 0; }, true);
        return true;
    }

    int eff = ble_eff_count(app);
    bool handled = false;
    with_view_model(
        app->ble_list_view,
        ListModel * m,
        {
            if(event->key == InputKeyUp) {
                if(m->sel > 0) m->sel--;
                if(m->sel < m->top) m->top = m->sel;
                handled = true;
            } else if(event->key == InputKeyDown) {
                if(m->sel < eff - 1) m->sel++;
                if(m->sel >= m->top + GHOST_LIST_ROWS) m->top = m->sel - GHOST_LIST_ROWS + 1;
                handled = true;
            }
        },
        true);
    return handled;
}

// bleScanScene: send BLESCAN, block on loading view until BLE:OK (or timeout),
// then go to the results list. bleListScene: auto-export CSV once + show the list.
void ble_scan_scene_on_enter(void* context) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;

    // 5Ghost: a new/refreshed sweep starts selection at the top. Only a Back from the detail
    // card keeps the prior row, and that path does NOT pass through this scene — so resetting
    // here lets ble_list_scene_on_enter restore selectedBle unconditionally (fresh -> row 0).
    app->selectedBle = 0;

    // 5Ghost FUNC-C: a fresh session (menu entry) clears; accumulate mode (Right re-scan)
    // keeps the list so this sweep merges (dedup by MAC) into what's already there.
    if(!app->ble_accumulate) {
        free(app->bleList); // fixed-width rows: no per-item free (names aren't strdup'd)
        app->bleList = NULL;
        app->bleCount = 0;
    }
    app->ble_exported = false;

    if(app->uart_port_busy || !app->uart_helper) {
        app->ble_scan_timed_out = true;
        scene_manager_next_scene(app->scene_manager, bleListScene);
        return;
    }

    view_dispatcher_switch_to_view(app->view_dispatcher, loadingView);
    // BLESCAN runs a ~8s passive scan, streaming BLE: rows then BLE:OK.
    // Wait up to ~12s (24 x 500ms); reuse the scan LED pulse.
    uart_helper_send(app->uart_helper, "BLESCAN\n", 8);
    bleScanFinish = false;
    int times = 0;
    while(bleScanFinish == false && times < 24) {
        notification_message(app->notif, &seq_scan_pulse);
        furi_delay_ms(500);
        times++;
    }
    notification_message(app->notif, &sequence_reset_blue);
    app->ble_scan_timed_out = (bleScanFinish == false);

    scene_manager_next_scene(app->scene_manager, bleListScene);
}
bool ble_scan_scene_on_event(void* context, SceneManagerEvent event) {
    UNUSED(context);
    if(event.type == SceneManagerEventTypeCustom) return true;
    return false;
}
void ble_scan_scene_on_exit(void* context) {
    UNUSED(context);
}

void ble_list_scene_on_enter(void* context) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;
    if(app->bleCount > 0 && !app->ble_exported) {
        ghost_export_ble_csv(app);
    }
    // Order the list defensive-first (trackers/Flippers on top, then by RSSI) so
    // the alarm-worthy devices don't scroll off the bottom. Done here, after the
    // scan finished and before the view binds, so sel/top start at a sorted 0.
    if(app->bleCount > 1) {
        ble_sort_list(app->bleList, app->bleCount);
    }
    // 5Ghost anti-stalk: 疑似跟踪(近距离 + 持续)时震动告警一次,让用户不必盯屏幕。
    if(ble_stalk_count(app) > 0) {
        notification_message(app->notif, &sequence_single_vibro);
    }
    with_view_model(
        app->ble_list_view,
        ListModel * m,
        {
            m->app = app;
            // Restore the selection so Back from the detail card returns to the same row (not
            // row 0). A fresh/refreshed scan reset selectedBle to 0 in ble_scan_scene_on_enter,
            // so that path still lands on the top. Clamp top to keep sel visible (like wifiList).
            m->sel = (app->selectedBle >= 0 && app->selectedBle < app->bleCount) ?
                         app->selectedBle : 0;
            if(m->sel < m->top) m->top = m->sel;
            if(m->sel >= m->top + GHOST_LIST_ROWS) m->top = m->sel - GHOST_LIST_ROWS + 1;
            if(m->top < 0) m->top = 0;
        },
        true);
    view_dispatcher_switch_to_view(app->view_dispatcher, bleListView);
}
bool ble_list_scene_on_event(void* context, SceneManagerEvent event) {
    Ghost5App* app = context;
    if(event.type == SceneManagerEventTypeBack) {
        scene_manager_search_and_switch_to_previous_scene(app->scene_manager, mainMenuScene);
        return true;
    }
    return false;
}
void ble_list_scene_on_exit(void* context) {
    UNUSED(context);
}

// 5Ghost P6: single BLE device detail card. Kind spelled out (from the firmware
// type byte), MAC, RSSI, and vendor (company-id lookup + raw hex). Own Canvas View;
// reads the selected device live via app->selectedBle. Back returns to the list.
// 5Ghost ③④: one hex nibble, or -1 if not a hex digit (no ctype dependency).
static int hex_nib(char c) {
    if(c >= '0' && c <= '9') return c - '0';
    if(c >= 'A' && c <= 'F') return c - 'A' + 10;
    if(c >= 'a' && c <= 'f') return c - 'a' + 10;
    return -1;
}

// 5Ghost ④: Google Find My Device (FMDN) verdict over raw advert bytes — service data
// (AD type 0x16) with 16-bit UUID 0xFEAA whose frame byte is 0x41. Mirrors the firmware
// g5_is_fmdn (ble.cpp); 0xFEAA + non-0x41 (Eddystone) is NOT FMDN. Bounds match the
// firmware walk (length>1, AD structure fits in 31B).
static bool fap_is_fmdn(const uint8_t* raw, uint8_t len) {
    uint8_t pos = 0;
    while(pos < len) {
        uint8_t length = raw[pos++];
        if(length > 0x01 && (pos + length) <= 31) {
            if(raw[pos] == 0x16 && (length - 1) >= 3) {
                uint16_t uuid = (uint16_t)raw[pos + 1] | ((uint16_t)raw[pos + 2] << 8);
                if(uuid == 0xFEAA && raw[pos + 3] == 0x41) return true;
            }
        }
        pos += length;
    }
    return false;
}

static void ble_info_draw_callback(Canvas* canvas, void* model) {
    InfoModel* m = model;
    Ghost5App* app = m->app;
    canvas_clear(canvas);
    canvas_set_color(canvas, ColorBlack);
    if(!app || app->selectedBle < 0 || app->selectedBle >= app->bleCount) {
        ghost_ui_header(canvas, "BLE INFO", NULL);
        canvas_set_font(canvas, FontSecondary);
        canvas_draw_str_aligned(canvas, 64, 38, AlignCenter, AlignCenter, "No device");
        return;
    }
    BLEDeviceDetails* d = &app->bleList[app->selectedBle];
    const char* vendor = ble_vendor_name(d->mfg);

    // header: advertised name if any, else the vendor, else a generic label
    char title[34];
    title[0] = '\0';
    if(d->name[0] && strcmp(d->name, "-") != 0) ghost_ui_ssid(d->name, title, sizeof(title));
    if(!title[0] && vendor) {
        strncpy(title, vendor, sizeof(title) - 1);
        title[sizeof(title) - 1] = '\0';
    }
    if(!title[0]) strcpy(title, "BLE Device");
    canvas_set_font(canvas, FontPrimary);
    while(title[0] && canvas_string_width(canvas, title) > 122)
        title[strlen(title) - 1] = '\0';
    ghost_ui_header(canvas, title, NULL);

    canvas_set_font(canvas, FontSecondary);
    // line 1: device kind (firmware type byte) on the left, RSSI right-aligned
    const char* kind = (d->type == 'F') ? "Flipper Zero" :
                       (d->type == 'A') ? "Tracker" :
                                          "Device";
    canvas_draw_str(canvas, 4, 24, kind);
    char rs[20];
    snprintf(rs, sizeof(rs), "%d dBm", d->rssi);
    int rw = canvas_string_width(canvas, rs);
    canvas_draw_str(canvas, 126 - rw, 24, rs);

    // line 2: MAC (left) + round count (right, accumulate mode only — persistent presence)
    canvas_draw_str(canvas, 4, 37, d->addr);
    if(d->seen > 1) {
        char sn[12];
        snprintf(sn, sizeof(sn), "x%d", d->seen);
        int sw = canvas_string_width(canvas, sn);
        canvas_draw_str(canvas, 126 - sw, 37, sn);
    }

    // line 3: vendor name + raw company id. A Google FMDN tracker advertises via service
    // data (0xFEAA frame 0x41) and carries no manufacturer company id, so it would fall to
    // "No vendor data" — label it explicitly (④: the fourth tracker family, from raw bytes).
    char vend[32];
    if(d->type == 'A' && fap_is_fmdn(d->raw, d->raw_len))
        strcpy(vend, "Google FMDN");
    else if(vendor)
        snprintf(vend, sizeof(vend), "%s (%04X)", vendor, d->mfg);
    else if(d->mfg)
        snprintf(vend, sizeof(vend), "Vendor ID %04X", d->mfg);
    else
        strcpy(vend, "No vendor data");
    canvas_draw_str(canvas, 4, 49, vend);

    // line 4: anti-stalk verdict. Only trackers ('A') reach level >= 1 (ble_stalk_level
    // gates on type). Level 2 = near + seen across rounds -> inverted alarm bar.
    int sl = ble_stalk_level(d);
    if(sl >= 2) {
        canvas_draw_box(canvas, 0, 52, 128, 12);
        canvas_set_color(canvas, ColorWhite);
        canvas_draw_str(canvas, 4, 61, "! Possible tracking");
        canvas_set_color(canvas, ColorBlack);
    } else if(sl == 1) {
        canvas_draw_str(canvas, 4, 61, "Nearby tracker - rescan");
    } else {
        // 5Ghost ②③: line4 hint for a non-alarm device — GATT active recon (OK, caps 'C')
        // and/or the raw-advert view (Right, available once a BLERAW line was parsed).
        const bool gatt = fw_has_cap(app, 'C');
        const bool raw = d->raw_len > 0;
        if(gatt && raw)
            canvas_draw_str(canvas, 4, 61, "OK:GATT  Right:Raw");
        else if(gatt)
            canvas_draw_str(canvas, 4, 61, "OK: GATT probe");
        else if(raw)
            canvas_draw_str(canvas, 4, 61, "Right: Raw adv");
    }
}

static bool ble_info_input_callback(InputEvent* event, void* context) {
    Ghost5App* app = context;
    // 5Ghost ②: OK starts a GATT active-recon probe of the selected device (caps 'C').
    // 5Ghost ③: Right opens the raw-advert view. Only POST the custom event here — the
    // scene's on_event does the next_scene, never an input callback (ViewPort lock; ⑦b
    // regression).
    if(event->type == InputTypeShort && event->key == InputKeyOk && fw_has_cap(app, 'C')) {
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_GATT_PROBE);
        return true;
    }
    if(event->type == InputTypeShort && event->key == InputKeyRight) {
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_BLE_RAW);
        return true;
    }
    return false; // all other keys (incl. Back) go to the dispatcher -> Back returns to the list
}

void ble_info_scene_on_enter(void* context) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;
    with_view_model(app->ble_info_view, InfoModel * m, { m->app = app; }, true);
    view_dispatcher_switch_to_view(app->view_dispatcher, bleInfoView);
}
bool ble_info_scene_on_event(void* context, SceneManagerEvent event) {
    Ghost5App* app = context;
    if(event.type == SceneManagerEventTypeCustom && event.event == GHOST_EVT_GATT_PROBE) {
        scene_manager_next_scene(app->scene_manager, gattProbeScene);
        return true;
    }
    if(event.type == SceneManagerEventTypeCustom && event.event == GHOST_EVT_BLE_RAW) {
        scene_manager_next_scene(app->scene_manager, bleRawScene);
        return true;
    }
    return false;
}
void ble_info_scene_on_exit(void* context) {
    UNUSED(context);
}

// ============================ 5Ghost ②: GATT active recon =====================
// BLE central connect + service fingerprint for the BLE detail card's selected device.
// gatt_probe_scene_on_enter sends BLEGATTPROBE and blocks on loadingView (mirrors
// ble_scan_scene_on_enter), then switches to gattView IN THE SAME SCENE (no next_scene)
// to show the result; Back from gattView returns to the BLE detail card.
#define GATT_VIEW_ROWS 4 // visible content rows below the header (tune on hardware)
#define GATT_VIEW_TOP  22 // y of the first content row

// Number of scrollable content rows in the gattView result body: Device Info fields that
// are present + SVC hits, or 1 for the "no known services" fallback. The error card has
// no scrollable rows. Shared by the draw and input callbacks so Up/Down bounds always
// match what's rendered.
static int gatt_result_row_count(Ghost5App* app) {
    if(app->gatt_err[0]) return 0;
    int n = 0;
    if(app->gatt_info_name[0]) n++;
    if(app->gatt_info_mfg[0]) n++;
    if(app->gatt_info_model[0]) n++;
    if(app->gatt_info_fw[0]) n++;
    n += app->gatt_svc_count;
    if(n == 0) n = 1; // "No known services found" fallback row
    return n;
}

// Render content row `i` (0-based, same order gatt_result_row_count counts: Device Info
// fields first, then SVC hits by label) into out[out_sz].
static void gatt_result_row_text(Ghost5App* app, int i, char* out, size_t out_sz) {
    if(app->gatt_info_name[0]) {
        if(i == 0) {
            snprintf(out, out_sz, "Name: %s", app->gatt_info_name);
            return;
        }
        i--;
    }
    if(app->gatt_info_mfg[0]) {
        if(i == 0) {
            snprintf(out, out_sz, "Mfg: %s", app->gatt_info_mfg);
            return;
        }
        i--;
    }
    if(app->gatt_info_model[0]) {
        if(i == 0) {
            snprintf(out, out_sz, "Model: %s", app->gatt_info_model);
            return;
        }
        i--;
    }
    if(app->gatt_info_fw[0]) {
        if(i == 0) {
            snprintf(out, out_sz, "FW: %s", app->gatt_info_fw);
            return;
        }
        i--;
    }
    if(i < app->gatt_svc_count) {
        snprintf(out, out_sz, "SVC: %s", app->gatt_svcs[i].label);
        return;
    }
    snprintf(out, out_sz, "No known services found");
}

static void gatt_view_draw_callback(Canvas* canvas, void* model) {
    ListModel* m = model;
    Ghost5App* app = m->app;
    canvas_clear(canvas);
    canvas_set_color(canvas, ColorBlack);
    if(!app || app->selectedBle < 0 || app->selectedBle >= app->bleCount) {
        ghost_ui_header(canvas, "GATT PROBE", NULL);
        canvas_set_font(canvas, FontSecondary);
        canvas_draw_str_aligned(canvas, 64, 38, AlignCenter, AlignCenter, "No device");
        return;
    }
    BLEDeviceDetails* d = &app->bleList[app->selectedBle];

    // header: advertised name if any, else the MAC (this card is about the GATT profile,
    // not the BLE advert, so no vendor fallback here unlike ble_info_draw_callback).
    char title[24];
    title[0] = '\0';
    if(d->name[0] && strcmp(d->name, "-") != 0) ghost_ui_ssid(d->name, title, sizeof(title));
    if(!title[0]) {
        strncpy(title, d->addr, sizeof(title) - 1);
        title[sizeof(title) - 1] = '\0';
    }
    ghost_ui_header(canvas, title, NULL);
    canvas_set_font(canvas, FontSecondary);

    if(app->gatt_err[0]) {
        const char* msg;
        if(strcmp(app->gatt_err, "notfound") == 0) msg = "Target not found";
        else if(strcmp(app->gatt_err, "conntimeout") == 0) msg = "Not connectable";
        else if(strcmp(app->gatt_err, "disctimeout") == 0) msg = "Discovery timeout";
        else if(strcmp(app->gatt_err, "args") == 0) msg = "Bad request";
        else if(strcmp(app->gatt_err, "timeout") == 0) msg = "No response (timeout)";
        else msg = app->gatt_err; // unknown code: show the raw token (bounded, gatt_err[16])
        canvas_draw_str_aligned(canvas, 64, 38, AlignCenter, AlignCenter, msg);
        return;
    }

    int total = gatt_result_row_count(app);
    for(int i = m->top; i < total && i < m->top + GATT_VIEW_ROWS; i++) {
        char row[48]; // stack-bounded: FAP has a 2KB stack, one row at a time, never accumulated
        gatt_result_row_text(app, i, row, sizeof(row));
        while(row[0] && canvas_string_width(canvas, row) > 122)
            row[strlen(row) - 1] = '\0';
        canvas_draw_str(canvas, 4, GATT_VIEW_TOP + (i - m->top) * 10, row);
    }

    canvas_set_color(canvas, ColorBlack);
    if(total > GATT_VIEW_ROWS)
        elements_scrollbar_pos(canvas, 125, GATT_VIEW_TOP - 8, 64 - (GATT_VIEW_TOP - 8), m->top, total);
}

static bool gatt_view_input_callback(InputEvent* event, void* context) {
    Ghost5App* app = context;
    if(event->type != InputTypeShort && event->type != InputTypeRepeat) return false;
    if(event->key != InputKeyUp && event->key != InputKeyDown) return false; // Back -> dispatcher

    int total = gatt_result_row_count(app);
    int max_top = (total > GATT_VIEW_ROWS) ? total - GATT_VIEW_ROWS : 0;
    bool handled = false;
    with_view_model(
        app->gatt_view,
        ListModel * m,
        {
            if(event->key == InputKeyUp) {
                if(m->top > 0) m->top--;
                handled = true;
            } else if(event->key == InputKeyDown) {
                if(m->top < max_top) m->top++;
                handled = true;
            }
        },
        true);
    return handled;
}

void gatt_probe_scene_on_enter(void* context) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;

    // Clear the previous probe's result so a stale SVC/Device Info/error can't leak into
    // this run (app_alloc only initializes these once at startup, not per-probe).
    app->gatt_svc_count = 0;
    app->gatt_result_svc = 0;
    app->gatt_info_name[0] = '\0';
    app->gatt_info_mfg[0] = '\0';
    app->gatt_info_model[0] = '\0';
    app->gatt_info_fw[0] = '\0';
    app->gatt_err[0] = '\0';

    view_dispatcher_switch_to_view(app->view_dispatcher, loadingView);

    char cmd[40];
    snprintf(cmd, sizeof(cmd), "BLEGATTPROBE %s\n", app->bleList[app->selectedBle].addr);
    uart_helper_send(app->uart_helper, cmd, strlen(cmd));

    // Probe worst case is ~31s: firmware retries the locate scan up to 2 rounds (8s each)
    // + connect up to 6s + discover up to 8s (default disc_secs). 68 x 500ms = 34s ceiling
    // leaves margin (mirrors ble_scan_scene_on_enter's 24 x 500ms pattern, scaled up for
    // the longer, retrying probe) — a tighter ceiling would misreport a slow probe as timeout.
    gattProbeFinish = false;
    int times = 0;
    while(gattProbeFinish == false && times < 68) {
        notification_message(app->notif, &seq_scan_pulse);
        furi_delay_ms(500);
        times++;
    }
    notification_message(app->notif, &sequence_reset_blue);
    app->gatt_timed_out = (gattProbeFinish == false);
    if(app->gatt_timed_out && !app->gatt_err[0]) {
        // FAP-side ceiling elapsed with no GATT:OK/ERR:GATT:* ever seen (firmware hang or
        // lost UART) — distinct from the firmware's own disctimeout, which already sets
        // gatt_err and would have set gattProbeFinish before this branch is reached.
        strncpy(app->gatt_err, "timeout", sizeof(app->gatt_err) - 1);
        app->gatt_err[sizeof(app->gatt_err) - 1] = '\0';
    }

    with_view_model(app->gatt_view, ListModel * m, { m->app = app; m->sel = 0; m->top = 0; }, true);
    view_dispatcher_switch_to_view(app->view_dispatcher, gattView);
}
bool gatt_probe_scene_on_event(void* context, SceneManagerEvent event) {
    Ghost5App* app = context;
    if(event.type == SceneManagerEventTypeBack) {
        scene_manager_search_and_switch_to_previous_scene(app->scene_manager, bleInfoScene);
        return true;
    }
    return false;
}
void gatt_probe_scene_on_exit(void* context) {
    UNUSED(context);
}
// ========================== end 5Ghost ②: GATT active recon ===================

// ============================ 5Ghost ③: raw-advert view ======================
// The BLE detail card's Right key opens this: the selected device's FULL raw advert
// bytes (firmware BLERAW: line) as a hex dump plus a per-AD-structure breakdown, with the
// 0xFEAA/0x41 service data called out as Google FMDN (④). Read-only, no UART — the bytes
// are already in bleList[selectedBle].raw. Scrolls with the ListModel top index, same
// pattern as gattView. Back returns to the detail card (dispatcher).
#define BLE_RAW_VIEW_ROWS   4  // visible content rows below the header (matches gattView)
#define BLE_RAW_VIEW_TOP    22 // y of the first content row — clears the header bar (was 16, overlapped)
#define BLE_RAW_HEX_PER_ROW 10 // advert bytes per hex row (20 chars ~ fits 128px)

// Short AD-type label for the breakdown (BT Core Spec CSS common data types).
static const char* ble_ad_type_name(uint8_t t) {
    switch(t) {
    case 0x01: return "Flags";
    case 0x02:
    case 0x03: return "UUID16";
    case 0x04:
    case 0x05: return "UUID32";
    case 0x06:
    case 0x07: return "UUID128";
    case 0x08:
    case 0x09: return "Name";
    case 0x0A: return "TxPower";
    case 0x16: return "SvcData";
    case 0xFF: return "MfgData";
    default: return "";
    }
}

// Count AD structures in raw[0..len). Bounded walk, same shape as fap_is_fmdn: a structure
// needs its length byte AND a type byte, so stop once the length byte was the last one.
static int ble_raw_ad_count(const uint8_t* raw, uint8_t len) {
    int n = 0;
    uint8_t pos = 0;
    while(pos < len) {
        uint8_t length = raw[pos++];
        if(length == 0 || pos >= len) break;
        n++;
        pos += length;
    }
    return n;
}

// Rows: [0] "Len: N" header, then hex rows, then one row per AD structure. 1 fallback row
// ("No raw data" / "No device") when nothing is available.
static int ble_raw_row_count(Ghost5App* app) {
    if(app->selectedBle < 0 || app->selectedBle >= app->bleCount) return 1;
    const BLEDeviceDetails* d = &app->bleList[app->selectedBle];
    if(d->raw_len == 0) return 1;
    int hex_rows = (d->raw_len + BLE_RAW_HEX_PER_ROW - 1) / BLE_RAW_HEX_PER_ROW;
    return 1 + hex_rows + ble_raw_ad_count(d->raw, d->raw_len);
}

// Render content row i (0-based) into out[out_sz], matching ble_raw_row_count's order.
static void ble_raw_row_text(Ghost5App* app, int i, char* out, size_t out_sz) {
    if(app->selectedBle < 0 || app->selectedBle >= app->bleCount) {
        snprintf(out, out_sz, "No device");
        return;
    }
    const BLEDeviceDetails* d = &app->bleList[app->selectedBle];
    if(d->raw_len == 0) {
        snprintf(out, out_sz, "No raw data");
        return;
    }
    if(i == 0) {
        snprintf(out, out_sz, "Len: %u bytes", d->raw_len);
        return;
    }
    i--;
    int hex_rows = (d->raw_len + BLE_RAW_HEX_PER_ROW - 1) / BLE_RAW_HEX_PER_ROW;
    if(i < hex_rows) {
        int start = i * BLE_RAW_HEX_PER_ROW;
        int off = 0;
        for(int b = start; b < start + BLE_RAW_HEX_PER_ROW && b < d->raw_len; b++)
            off += snprintf(out + off, out_sz - off, "%02X", d->raw[b]);
        return;
    }
    i -= hex_rows;
    // i-th AD structure — same bounded walk as ble_raw_ad_count.
    uint8_t pos = 0;
    int k = 0;
    while(pos < d->raw_len) {
        uint8_t length = d->raw[pos++];
        if(length == 0 || pos >= d->raw_len) break;
        if(k == i) {
            uint8_t type = d->raw[pos];
            bool ib = (pos + length) <= d->raw_len; // full structure in-bounds -> fields safe
            if(type == 0x16 && length >= 4 && ib) {
                uint16_t uuid = (uint16_t)d->raw[pos + 1] | ((uint16_t)d->raw[pos + 2] << 8);
                uint8_t frame = d->raw[pos + 3];
                if(uuid == 0xFEAA && frame == 0x41)
                    snprintf(out, out_sz, "SvcData %04X f=%02X FMDN", uuid, frame);
                else
                    snprintf(out, out_sz, "SvcData %04X f=%02X", uuid, frame);
            } else if(type == 0xFF && length >= 3 && ib) {
                uint16_t cid = (uint16_t)d->raw[pos + 1] | ((uint16_t)d->raw[pos + 2] << 8);
                snprintf(out, out_sz, "MfgData %04X", cid);
            } else {
                snprintf(out, out_sz, "%02X %s", type, ble_ad_type_name(type));
            }
            return;
        }
        k++;
        pos += length;
    }
    snprintf(out, out_sz, "-");
}

static void ble_raw_view_draw_callback(Canvas* canvas, void* model) {
    ListModel* m = model;
    Ghost5App* app = m->app;
    canvas_clear(canvas);
    canvas_set_color(canvas, ColorBlack);

    char title[24];
    if(app && app->selectedBle >= 0 && app->selectedBle < app->bleCount) {
        const BLEDeviceDetails* d = &app->bleList[app->selectedBle];
        if(d->name[0] && strcmp(d->name, "-") != 0)
            ghost_ui_ssid(d->name, title, sizeof(title));
        else {
            strncpy(title, d->addr, sizeof(title) - 1);
            title[sizeof(title) - 1] = '\0';
        }
    } else {
        strcpy(title, "RAW ADV");
    }
    ghost_ui_header(canvas, title, NULL);
    canvas_set_font(canvas, FontSecondary);

    int total = ble_raw_row_count(app);
    for(int i = m->top; i < total && i < m->top + BLE_RAW_VIEW_ROWS; i++) {
        char row[48]; // stack-bounded, one row at a time (FAP 2KB stack), same as gattView
        ble_raw_row_text(app, i, row, sizeof(row));
        while(row[0] && canvas_string_width(canvas, row) > 122)
            row[strlen(row) - 1] = '\0';
        canvas_draw_str(canvas, 4, BLE_RAW_VIEW_TOP + (i - m->top) * 10, row);
    }
    if(total > BLE_RAW_VIEW_ROWS)
        elements_scrollbar_pos(
            canvas, 125, BLE_RAW_VIEW_TOP - 8, 64 - (BLE_RAW_VIEW_TOP - 8), m->top, total);
}

static bool ble_raw_view_input_callback(InputEvent* event, void* context) {
    Ghost5App* app = context;
    if(event->type != InputTypeShort && event->type != InputTypeRepeat) return false;
    if(event->key != InputKeyUp && event->key != InputKeyDown) return false; // Back -> dispatcher

    int total = ble_raw_row_count(app);
    int max_top = (total > BLE_RAW_VIEW_ROWS) ? total - BLE_RAW_VIEW_ROWS : 0;
    bool handled = false;
    with_view_model(
        app->ble_raw_view,
        ListModel * m,
        {
            if(event->key == InputKeyUp) {
                if(m->top > 0) m->top--;
                handled = true;
            } else if(event->key == InputKeyDown) {
                if(m->top < max_top) m->top++;
                handled = true;
            }
        },
        true);
    return handled;
}

void ble_raw_scene_on_enter(void* context) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;
    with_view_model(
        app->ble_raw_view, ListModel * m, { m->app = app; m->sel = 0; m->top = 0; }, true);
    view_dispatcher_switch_to_view(app->view_dispatcher, bleRawView);
}
bool ble_raw_scene_on_event(void* context, SceneManagerEvent event) {
    UNUSED(context);
    UNUSED(event);
    return false; // Back -> dispatcher pops back to the BLE detail card
}
void ble_raw_scene_on_exit(void* context) {
    UNUSED(context);
}
// ========================== end 5Ghost ③: raw-advert view =====================

// ============================ 5Ghost FUNC-A: station list ====================
// WiFi station (client) list for ONE AP. Rich rows (MAC + RSSI), mirrors the
// wifi/BLE list views. OK on a row sends a PRECISE per-client DEAUTH (that
// station's MAC as the <client> token, not the broadcast FFFFFFFFFFFF).
static void sta_list_draw_callback(Canvas* canvas, void* model) {
    ListModel* m = model;
    Ghost5App* app = m->app;
    canvas_clear(canvas);
    canvas_set_color(canvas, ColorBlack);

    if(!app || app->staCount <= 0) {
        const char* main_s;
        const char* sub_s;
        ghost_uart_empty_copy(
            app,
            app && app->sta_scan_timed_out,
            "No clients",
            "5GHz AP, or none active",
            &main_s,
            &sub_s);
        ghost_ui_header(canvas, "Clients", NULL);
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str_aligned(canvas, 64, 32, AlignCenter, AlignCenter, main_s);
        canvas_set_font(canvas, FontSecondary);
        canvas_draw_str_aligned(canvas, 64, 46, AlignCenter, AlignCenter, sub_s);
        return;
    }

    char title[24];
    snprintf(title, sizeof(title), "Clients: %d", app->staCount);
    ghost_ui_header(canvas, title, NULL);

    for(int row = 0; row < GHOST_LIST_ROWS; row++) {
        int i = m->top + row;
        if(i >= app->staCount) break;
        StaDetails* st = &app->staList[i];
        int y = GHOST_LIST_TOP + row * GHOST_LIST_RH;
        int yb = y + GHOST_LIST_RH - 3;
        bool sel = (i == m->sel);
        if(sel) {
            canvas_set_color(canvas, ColorBlack);
            canvas_draw_box(canvas, 0, y, 121, GHOST_LIST_RH); // room for scrollbar
            canvas_set_color(canvas, ColorWhite);
        } else {
            canvas_set_color(canvas, ColorBlack);
        }
        canvas_set_font(canvas, FontSecondary);

        // RSSI right-aligned (negative dBm; 0/positive = not reported -> "--")
        char rs[12];
        if(st->rssi < 0)
            snprintf(rs, sizeof(rs), "%d", st->rssi);
        else
            strcpy(rs, "--");
        int rw = canvas_string_width(canvas, rs);
        canvas_draw_str(canvas, 116 - rw, yb, rs);

        // MAC "AA:BB:CC:DD:EE:FF" from the colon-less 12hex, left; truncate only if
        // it would collide with the RSSI (hex MACs are narrow, so it rarely does).
        char mac[18];
        snprintf(mac, sizeof(mac), "%c%c:%c%c:%c%c:%c%c:%c%c:%c%c",
                 st->mac[0], st->mac[1], st->mac[2], st->mac[3], st->mac[4], st->mac[5],
                 st->mac[6], st->mac[7], st->mac[8], st->mac[9], st->mac[10], st->mac[11]);
        int macw = 112 - rw;
        while(mac[0] && canvas_string_width(canvas, mac) > macw)
            mac[strlen(mac) - 1] = '\0';
        canvas_draw_str(canvas, 4, yb, mac);
    }

    canvas_set_color(canvas, ColorBlack);
    if(app->staCount > GHOST_LIST_ROWS)
        elements_scrollbar_pos(
            canvas, 125, GHOST_LIST_TOP, 64 - GHOST_LIST_TOP, m->sel, app->staCount);
}

static bool sta_list_input_callback(InputEvent* event, void* context) {
    Ghost5App* app = context;
    if(event->type != InputTypeShort && event->type != InputTypeRepeat) return false;

    if(app->staCount <= 0) return false; // Back -> dispatcher -> previous scene

    if(event->key == InputKeyUp || event->key == InputKeyDown) {
        with_view_model(
            app->sta_list_view,
            ListModel * m,
            {
                if(event->key == InputKeyUp) {
                    if(m->sel > 0) m->sel--;
                } else {
                    if(m->sel < app->staCount - 1) m->sel++;
                }
                if(m->sel < m->top) m->top = m->sel;
                if(m->sel >= m->top + GHOST_LIST_ROWS) m->top = m->sel - GHOST_LIST_ROWS + 1;
            },
            true);
        return true;
    }

    if(event->key == InputKeyOk) {
        int sel = 0;
        with_view_model(app->sta_list_view, ListModel * m, { sel = m->sel; }, false);
        if(sel < 0) sel = 0;
        if(sel >= app->staCount) sel = app->staCount - 1;
        app->selectedSta = sel;
        // A3 precise deauth: bssid = selected AP (colon-less), client = this station's
        // MAC (already colon-less 12hex from STASCAN), ch = AP channel. Unlike the detail
        // card's broadcast FFFFFFFFFFFF, this deauths ONLY this one station.
        if(app->selectedWifi >= 0 && app->selectedWifi < app->wifiCount) {
            APDetails* ap = &app->wifiList[app->selectedWifi];
            if(!g5_tx_ch(ap->channel)) {
                g5_show_rx_only(app);
                return true;
            }
            char bssid12[13];
            int n = 0;
            for(const char* p = ap->APbssid; *p && n < 12; p++)
                if(*p != ':') bssid12[n++] = *p;
            bssid12[n] = '\0';
            char cmd[48];
            snprintf(
                cmd, sizeof(cmd), "DEAUTH %s %s %d\n", bssid12, app->staList[sel].mac, ap->channel);
            uart_helper_send(app->uart_helper, cmd, strlen(cmd));
            notification_message(app->notif, &sequence_single_vibro);
        }
        return true;
    }
    return false;
}

// staListScene: send STASCAN for the selected AP, block on the loading view until
// STA:OK (or timeout), then show the client list. Single fused scene (scan+list),
// like ble_scan+ble_list but with no separate results scene needed.
void sta_list_scene_on_enter(void* context) {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = context;

    free(app->staList); // fixed-width rows: single free
    app->staList = NULL;
    app->staCount = 0;

    if(app->uart_port_busy || !app->uart_helper) {
        app->sta_scan_timed_out = true;
        with_view_model(
            app->sta_list_view,
            ListModel * m,
            {
                m->app = app;
                m->sel = 0;
                m->top = 0;
            },
            true);
        view_dispatcher_switch_to_view(app->view_dispatcher, staListView);
        return;
    }

    view_dispatcher_switch_to_view(app->view_dispatcher, loadingView);
    // STASCAN scans ONE AP's clients on its channel: colon-less BSSID + channel + 8s.
    if(app->selectedWifi >= 0 && app->selectedWifi < app->wifiCount) {
        APDetails* ap = &app->wifiList[app->selectedWifi];
        char bssid12[13];
        int n = 0;
        for(const char* p = ap->APbssid; *p && n < 12; p++)
            if(*p != ':') bssid12[n++] = *p;
        bssid12[n] = '\0';
        char cmd[48];
        snprintf(cmd, sizeof(cmd), "STASCAN %s %d 8\n", bssid12, ap->channel);
        uart_helper_send(app->uart_helper, cmd, strlen(cmd));
    }
    staScanFinish = false;
    int times = 0;
    while(staScanFinish == false && times < 24) { // ~12s: 8s scan + slack
        notification_message(app->notif, &seq_scan_pulse);
        furi_delay_ms(500);
        times++;
    }
    notification_message(app->notif, &sequence_reset_blue);
    app->sta_scan_timed_out = (staScanFinish == false);

    with_view_model(
        app->sta_list_view,
        ListModel * m,
        {
            m->app = app;
            m->sel = 0;
            m->top = 0;
        },
        true);
    view_dispatcher_switch_to_view(app->view_dispatcher, staListView);
}
bool sta_list_scene_on_event(void* context, SceneManagerEvent event) {
    Ghost5App* app = context;
    if(event.type == SceneManagerEventTypeBack) {
        scene_manager_search_and_switch_to_previous_scene(app->scene_manager, wifiInfoScene);
        return true;
    }
    return false;
}
void sta_list_scene_on_exit(void* context) {
    UNUSED(context);
}
// ========================== end 5Ghost FUNC-A: station list ==================

// ---- P1 Guided Audit A2: event-driven LISTAP / STASCAN / CAPTURE ------------
static void audit_ap_item_callback(void* context, uint32_t index);
static void audit_build_menu(Ghost5App* app);
static void audit_draw(Ghost5App* app);
static void audit_timer_stop(Ghost5App* app);
static void audit_apply_decision(Ghost5App* app, G5AuditDecision d);

static void audit_timer_callback(void* context) {
    Ghost5App* app = context;
    view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_AUDIT_TICK);
}

static void audit_timer_stop(Ghost5App* app) {
    app->audit_wait_ticks = 0;
    app->audit_wait_kind = AUDIT_WAIT_NONE;
    if(app->audit_timer) furi_timer_stop(app->audit_timer);
    notification_message(app->notif, &sequence_reset_blue);
}

static void audit_timer_start(Ghost5App* app, int kind, int ticks) {
    audit_timer_stop(app);
    app->audit_wait_kind = kind;
    app->audit_wait_ticks = ticks;
    furi_timer_start(app->audit_timer, furi_ms_to_ticks(AUDIT_TICK_MS));
}

static void audit_clear_wifi_list(Ghost5App* app) {
    for(int i = 0; i < app->wifiCount; i++) {
        free(app->wifiList[i].APssid);
    }
    free(app->wifiList);
    app->wifiList = NULL;
    app->wifiCount = 0;
}

static void audit_start_listap(Ghost5App* app) {
    view_dispatcher_switch_to_view(app->view_dispatcher, loadingView);
    audit_clear_wifi_list(app);
    scanFinish = false;
    app->scan_timed_out = false;
    uart_helper_send(app->uart_helper, "LISTAP\n", 7);
    audit_timer_start(app, AUDIT_WAIT_LISTAP, AUDIT_LISTAP_TICKS);
}

static void audit_write_sidecar(Ghost5App* app) {
    if(!g5_session_id_valid(app->session_id)) return;
    char json_path[112];
    if(!ghost_session_path(json_path, sizeof(json_path), G5AuditFileAuditJson, app->session_id))
        return;
    char* json = malloc(1024);
    if(!json) return;
    G5AuditJsonIn in = {
        .session_id = app->session_id,
        .ssid = app->audit_ssid,
        .bssid = app->audit_bssid,
        .channel = app->audit_channel,
        .pmf = app->audit_pmf,
        .fw_version = app->fw_version,
        .fw_caps = app->fw_caps,
        .path = app->audit_path,
        .result = app->audit_result,
        .have_capture_pcap = app->hs_path[0] != '\0',
        .have_capture_json = (app->audit_path == G5AuditPathHs) &&
                             ((app->audit_result == G5AuditResultComplete) ||
                              (app->audit_result == G5AuditResultPartial)),
        .have_pmkid_22000 = app->pmkid_path[0] != '\0',
        .have_pmkid_json = (app->audit_path == G5AuditPathPmkid) && app->pmkid_done,
    };
    const size_t n = g5_audit_build_audit_json(&in, json, 1024);
    if(n > 0) {
        Storage* storage = furi_record_open(RECORD_STORAGE);
        ghost_ensure_data_dir(storage);
        ghost_evidence_atomic_write(storage, json_path, (const uint8_t*)json, n);
        furi_record_close(RECORD_STORAGE);
    }
    free(json);
}

static void audit_finish(Ghost5App* app, G5AuditResult result) {
    audit_timer_stop(app);
    app->audit_result = result;
    app->audit_done = true;
    app->audit_next = G5AuditNextStop;
    audit_write_sidecar(app);
    audit_draw(app);
}

static void audit_start_capture(Ghost5App* app) {
    if(!g5_tx_ch(app->audit_channel)) {
        audit_finish(app, G5AuditResultUnsupported);
        return;
    }
    strncpy(app->hs_ssid, app->audit_ssid, sizeof(app->hs_ssid) - 1);
    app->hs_ssid[sizeof(app->hs_ssid) - 1] = '\0';
    strncpy(app->hs_bssid, app->audit_bssid, sizeof(app->hs_bssid) - 1);
    app->hs_bssid[sizeof(app->hs_bssid) - 1] = '\0';
    app->hs_channel = app->audit_channel;
    ghost_hs_begin(app);
    if(!app->hs_buf) {
        audit_finish(app, G5AuditResultTimeout);
        return;
    }
    char cmd[40];
    snprintf(cmd, sizeof(cmd), "CAPTURE %s %d\n", app->hs_bssid, app->hs_channel);
    uart_helper_send(app->uart_helper, cmd, strlen(cmd));
    app->audit_next = G5AuditNextCapture;
    app->audit_path = G5AuditPathHs;
    app->audit_done = false;
    /* Firmware streams until CAPSTOP then HSDONE. Do not treat dwell as success. */
    audit_timer_start(app, AUDIT_WAIT_CAPTURE, AUDIT_CAPTURE_TICKS);
    audit_draw(app);
}

static void audit_capstop(Ghost5App* app) {
    if(app->hs_done || app->hs_stopping) return;
    audit_timer_stop(app);
    uart_helper_send(app->uart_helper, "CAPSTOP\n", 8);
    app->hs_stopping = true;
    audit_draw(app);
}

static void audit_start_pmkid(Ghost5App* app) {
    if(!g5_tx_ch(app->audit_channel)) {
        audit_finish(app, G5AuditResultUnsupported);
        return;
    }
    strncpy(app->pmkid_ssid, app->audit_ssid, sizeof(app->pmkid_ssid) - 1);
    app->pmkid_ssid[sizeof(app->pmkid_ssid) - 1] = '\0';
    strncpy(app->pmkid_bssid, app->audit_bssid, sizeof(app->pmkid_bssid) - 1);
    app->pmkid_bssid[sizeof(app->pmkid_bssid) - 1] = '\0';
    app->pmkid_channel = app->audit_channel;
    memset(&app->pmkid_report, 0, sizeof(app->pmkid_report));
    app->pmkid_state = G5PmkidPending;
    app->pmkid_done = false;
    app->pmkid_path[0] = '\0';
    char cmd[40];
    snprintf(cmd, sizeof(cmd), "PMKID %s %d\n", app->pmkid_bssid, app->pmkid_channel);
    uart_helper_send(app->uart_helper, cmd, strlen(cmd));
    app->audit_next = G5AuditNextPmkid;
    app->audit_path = G5AuditPathPmkid;
    app->audit_done = false;
    audit_draw(app);
}

static void audit_start_stascan(Ghost5App* app) {
    free(app->staList);
    app->staList = NULL;
    app->staCount = 0;
    app->sta_scan_timed_out = false;
    staScanFinish = false;
    char bssid12[13];
    int n = 0;
    for(const char* p = app->audit_bssid; *p && n < 12; p++)
        if(*p != ':') bssid12[n++] = *p;
    bssid12[n] = '\0';
    char cmd[48];
    snprintf(cmd, sizeof(cmd), "STASCAN %s %d 8\n", bssid12, app->audit_channel);
    uart_helper_send(app->uart_helper, cmd, strlen(cmd));
    app->audit_next = G5AuditNextStascan;
    app->audit_done = false;
    audit_timer_start(app, AUDIT_WAIT_STASCAN, AUDIT_STASCAN_TICKS);
    audit_draw(app);
}

static void audit_apply_decision(Ghost5App* app, G5AuditDecision d) {
    app->audit_next = d.next;
    app->audit_path = d.path;
    app->audit_result = d.result;
    if(d.next == G5AuditNextStop) {
        audit_finish(app, d.result);
        return;
    }
    if(d.next == G5AuditNextCapture) {
        audit_start_capture(app);
        return;
    }
    if(d.next == G5AuditNextStascan) {
        audit_start_stascan(app);
        return;
    }
    if(d.next == G5AuditNextPmkid) {
        audit_start_pmkid(app);
        return;
    }
    audit_finish(app, d.result != G5AuditResultNone ? d.result : G5AuditResultTimeout);
}

static void audit_on_hs_done(Ghost5App* app) {
    const bool quality_valid = ghost_hs_quality_valid(app->hs_quality.result);
    const bool flushed = ghost_hs_flush(app);
    const bool have_pcap = app->hs_path[0] != '\0';
    const bool have_json = flushed || !quality_valid;
    app->hs_done = true;
    app->audit_path = G5AuditPathHs;
    audit_finish(app, g5_audit_map_hs(quality_valid, have_pcap, have_json));
}

static void audit_on_pmkid_done(Ghost5App* app) {
    if(app->pmkid_report.ok) {
        uint8_t target[6];
        const bool have_target = parse_mac(app->pmkid_bssid, target);
        bool seen = false;
        for(int i = 0; i < app->pmkid_seen_count; i++) {
            if(strncmp(app->pmkid_seen[i], app->pmkid_bssid, sizeof(app->pmkid_seen[0])) == 0) {
                seen = true;
                break;
            }
        }
        app->pmkid_state =
            g5_pmkid_classify_ok(&app->pmkid_report, have_target ? target : NULL, seen);
        const int cap = (int)(sizeof(app->pmkid_seen) / sizeof(app->pmkid_seen[0]));
        if(app->pmkid_state == G5PmkidValid && app->pmkid_seen_count < cap) {
            strncpy(
                app->pmkid_seen[app->pmkid_seen_count],
                app->pmkid_bssid,
                sizeof(app->pmkid_seen[0]) - 1);
            app->pmkid_seen[app->pmkid_seen_count][sizeof(app->pmkid_seen[0]) - 1] = '\0';
            app->pmkid_seen_count++;
        }
    } else {
        app->pmkid_state = app->pmkid_report.state;
    }
    app->pmkid_done = true;
    pmkid_flush(app);
    const bool have_22000 = app->pmkid_path[0] != '\0';
    const bool have_json = g5_session_id_valid(app->session_id);
    app->audit_path = G5AuditPathPmkid;
    audit_finish(
        app,
        g5_audit_map_pmkid(app->pmkid_state, app->pmkid_report.reason, have_22000, have_json));
}

static void audit_build_menu(Ghost5App* app) {
    app->submenuIndex = 0;
    submenu_reset(app->submenu);
    submenu_set_header(app->submenu, "Pick AP (audit)");
    submenu_add_item(app->submenu, "Rescan", GHOST_AP_RESCAN_ID, audit_ap_item_callback, app);
    for(int i = 0; i < app->wifiCount; i++) {
        bool dup = false;
        for(int j = 0; j < app->wifiCount; j++) {
            if(j != i && strcmp(app->wifiList[j].APssid, app->wifiList[i].APssid) == 0) {
                dup = true;
                break;
            }
        }
        char temp[230];
        char ssid[34];
        ghost_ui_ssid(app->wifiList[i].APssid, ssid, sizeof(ssid));
        if(!ssid[0]) strcpy(ssid, "<hidden>");
        const char* bssid = app->wifiList[i].APbssid;
        size_t bl = strlen(bssid);
        if(dup && ssid[0] && bl >= 2) {
            snprintf(temp, sizeof(temp), "%s .%s", ssid, bssid + bl - 2);
        } else {
            snprintf(temp, sizeof(temp), "%s", ssid);
        }
        submenu_add_item(app->submenu, temp, i, audit_ap_item_callback, app);
    }
    /* submenu_set_selected_item takes the item index, not visual row.
     * Rescan is 0x7FFFFFFF; AP rows use wifiList i (0..). Passing visual
     * position 1 selected the second AP. Land on first row = Rescan. */
    submenu_set_selected_item(app->submenu, GHOST_AP_RESCAN_ID);
    view_dispatcher_switch_to_view(app->view_dispatcher, scannedWifisView);
}

static void audit_ap_item_callback(void* context, uint32_t index) {
    Ghost5App* app = context;
    if(index == GHOST_AP_RESCAN_ID) {
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_AP_RESCAN);
        return;
    }
    app->selectedWifi = index;
    scene_manager_next_scene(app->scene_manager, auditRunScene);
}

void audit_select_scene_on_enter(void* context) {
    Ghost5App* app = context;
    app->menuIndex = 0;
    if(app->wifiCount > 0) {
        audit_build_menu(app);
        return;
    }
    audit_start_listap(app);
}

bool audit_select_scene_on_event(void* context, SceneManagerEvent event) {
    Ghost5App* app = context;
    if(event.type == SceneManagerEventTypeCustom && event.event == GHOST_EVT_AP_RESCAN) {
        audit_start_listap(app);
        return true;
    }
    if(event.type == SceneManagerEventTypeCustom && event.event == GHOST_EVT_AUDIT_TICK) {
        if(app->audit_wait_kind != AUDIT_WAIT_LISTAP) return true;
        notification_message(app->notif, &seq_scan_pulse);
        if(scanFinish) {
            audit_timer_stop(app);
            app->scan_timed_out = false;
            audit_build_menu(app);
            return true;
        }
        if(app->audit_wait_ticks > 0) app->audit_wait_ticks--;
        if(app->audit_wait_ticks == 0) {
            audit_timer_stop(app);
            app->scan_timed_out = true;
            audit_build_menu(app);
        }
        return true;
    }
    return false;
}

void audit_select_scene_on_exit(void* context) {
    Ghost5App* app = context;
    if(app->audit_wait_kind == AUDIT_WAIT_LISTAP) {
        uart_helper_send(app->uart_helper, "STOP\n", 5);
    }
    audit_timer_stop(app);
    submenu_reset(app->submenu);
}

static void audit_draw(Ghost5App* app) {
    widget_reset(app->widget);
    char line[96];
    widget_add_string_element(app->widget, 64, 2, AlignCenter, AlignTop, FontPrimary, "Guided Audit");
    snprintf(line, sizeof(line), "%s  ch%d", app->audit_ssid, app->audit_channel);
    widget_add_string_element(app->widget, 64, 16, AlignCenter, AlignTop, FontSecondary, line);
    if(app->audit_done) {
        widget_add_string_element(
            app->widget,
            64,
            32,
            AlignCenter,
            AlignTop,
            FontSecondary,
            g5_audit_result_label(app->audit_result));
        if(app->hs_path[0]) {
            const char* fn = strrchr(app->hs_path, '/');
            fn = fn ? fn + 1 : app->hs_path;
            widget_add_text_box_element(app->widget, 0, 42, 128, 22, AlignLeft, AlignTop, fn, false);
        } else if(app->pmkid_path[0]) {
            const char* fn = strrchr(app->pmkid_path, '/');
            fn = fn ? fn + 1 : app->pmkid_path;
            widget_add_text_box_element(app->widget, 0, 42, 128, 22, AlignLeft, AlignTop, fn, false);
        } else {
            const char* path = g5_audit_path_name(app->audit_path);
            if(path[0]) {
                widget_add_string_element(
                    app->widget, 64, 46, AlignCenter, AlignTop, FontSecondary, path);
            }
        }
    } else {
        const char* step = app->hs_stopping ? "Stopping..." :
                                               g5_audit_next_name(app->audit_next);
        widget_add_string_element(
            app->widget, 64, 32, AlignCenter, AlignTop, FontSecondary, step[0] ? step : "...");
        widget_add_string_element(
            app->widget, 64, 46, AlignCenter, AlignTop, FontSecondary, "Back=stop");
    }
    view_dispatcher_switch_to_view(app->view_dispatcher, handshakeView);
}

void audit_run_scene_on_enter(void* context) {
    Ghost5App* app = context;
    app->audit_ssid[0] = '\0';
    app->audit_bssid[0] = '\0';
    app->audit_channel = 0;
    app->audit_pmf = 0;
    app->audit_done = false;
    app->audit_next = G5AuditNextStop;
    app->audit_path = G5AuditPathNone;
    app->audit_result = G5AuditResultNone;
    app->hs_path[0] = '\0';
    app->hs_error[0] = '\0';
    app->hs_done = false;
    app->pmkid_path[0] = '\0';
    app->pmkid_done = false;
    app->pmkid_state = G5PmkidPending;
    memset(&app->pmkid_report, 0, sizeof(app->pmkid_report));
    if(app->selectedWifi >= 0 && app->selectedWifi < app->wifiCount) {
        strncpy(
            app->audit_ssid, app->wifiList[app->selectedWifi].APssid, sizeof(app->audit_ssid) - 1);
        app->audit_ssid[sizeof(app->audit_ssid) - 1] = '\0';
        strncpy(
            app->audit_bssid,
            app->wifiList[app->selectedWifi].APbssid,
            sizeof(app->audit_bssid) - 1);
        app->audit_bssid[sizeof(app->audit_bssid) - 1] = '\0';
        app->audit_channel = app->wifiList[app->selectedWifi].channel;
        app->audit_pmf = app->wifiList[app->selectedWifi].pmf;
    }
    app->session_id[0] = '\0';
    char minted[G5_SESSION_ID_MAX];
    if(ghost_resolve_session_id(app, minted, sizeof(minted))) {
        strncpy(app->session_id, minted, sizeof(app->session_id) - 1);
        app->session_id[sizeof(app->session_id) - 1] = '\0';
    }
    G5AuditFacts facts = {
        .listap_ok = true,
        .channel = app->audit_channel,
        .pmf = app->audit_pmf,
        .stascan_done = false,
        .stascan_timed_out = false,
        .sta_count = 0,
    };
    audit_apply_decision(app, g5_audit_decide(&facts));
}

bool audit_run_scene_on_event(void* context, SceneManagerEvent event) {
    Ghost5App* app = context;
    if(event.type == SceneManagerEventTypeBack) {
        if(app->audit_next == G5AuditNextCapture && !app->hs_done) {
            audit_capstop(app);
            return true;
        }
        if(app->audit_next == G5AuditNextPmkid && !app->pmkid_done) {
            /* STOP tears PMKID down with OK:STOP, not PMKID:fail. Do not wait. */
            uart_helper_send(app->uart_helper, "STOP\n", 5);
            app->audit_path = G5AuditPathPmkid;
            audit_finish(app, G5AuditResultTimeout);
            return true;
        }
        if(!app->audit_done && app->audit_wait_kind == AUDIT_WAIT_STASCAN) {
            uart_helper_send(app->uart_helper, "STOP\n", 5);
            audit_timer_stop(app);
        }
        scene_manager_previous_scene(app->scene_manager);
        return true;
    }
    if(event.type != SceneManagerEventTypeCustom) return false;
    if(event.event == GHOST_EVT_AUDIT_TICK) {
        if(app->audit_wait_kind == AUDIT_WAIT_CAPTURE) {
            if(app->audit_wait_ticks > 0) app->audit_wait_ticks--;
            if(app->audit_wait_ticks == 0) audit_capstop(app);
            return true;
        }
        if(app->audit_wait_kind != AUDIT_WAIT_STASCAN) return true;
        notification_message(app->notif, &seq_scan_pulse);
        if(staScanFinish) {
            audit_timer_stop(app);
            G5AuditFacts facts = {
                .listap_ok = true,
                .channel = app->audit_channel,
                .pmf = app->audit_pmf,
                .stascan_done = true,
                .stascan_timed_out = false,
                .sta_count = app->staCount,
            };
            audit_apply_decision(app, g5_audit_decide(&facts));
            return true;
        }
        if(app->audit_wait_ticks > 0) app->audit_wait_ticks--;
        if(app->audit_wait_ticks == 0) {
            audit_timer_stop(app);
            app->sta_scan_timed_out = true;
            G5AuditFacts facts = {
                .listap_ok = true,
                .channel = app->audit_channel,
                .pmf = app->audit_pmf,
                .stascan_done = false,
                .stascan_timed_out = true,
                .sta_count = 0,
            };
            audit_apply_decision(app, g5_audit_decide(&facts));
        }
        return true;
    }
    if(event.event == GHOST_EVT_HS_UPDATE) {
        audit_draw(app);
        return true;
    }
    if(event.event == GHOST_EVT_HS_DONE) {
        audit_on_hs_done(app);
        return true;
    }
    if(event.event == GHOST_EVT_HS_ERROR) {
        app->hs_done = true;
        ghost_hs_abort(app);
        audit_finish(app, G5AuditResultTimeout);
        return true;
    }
    if(event.event == GHOST_EVT_PMKID_UPDATE) {
        if(app->audit_next == G5AuditNextPmkid && !app->audit_done) audit_draw(app);
        return true;
    }
    if(event.event == GHOST_EVT_PMKID_DONE) {
        if(app->audit_next != G5AuditNextPmkid || app->audit_done) return true;
        audit_on_pmkid_done(app);
        return true;
    }
    return false;
}

void audit_run_scene_on_exit(void* context) {
    Ghost5App* app = context;
    if(app->audit_wait_kind == AUDIT_WAIT_STASCAN) {
        uart_helper_send(app->uart_helper, "STOP\n", 5);
    }
    if(app->audit_next == G5AuditNextCapture && !app->hs_done) {
        uart_helper_send(app->uart_helper, "CAPSTOP\n", 8);
    }
    if(app->audit_next == G5AuditNextPmkid && !app->pmkid_done) {
        uart_helper_send(app->uart_helper, "STOP\n", 5);
    }
    audit_timer_stop(app);
    app->session_id[0] = '\0';
    widget_reset(app->widget);
}

