void uart_process_line(FuriString* line, void* context) {
    FURI_LOG_D(TAG, __func__);
    FURI_LOG_D(TAG, furi_string_get_cstr(line));
    Ghost5App* app = context;
    // 5Ghost ③: bleList row the most recent BLE: line added/updated; the BLERAW: line that
    // follows targets it. Single-writer (UART worker); the first BLE: line of each scan
    // overwrites it, so a stale value never survives into a live row.
    static int last_ble_index = -1;
    if(strncmp(furi_string_get_cstr(line), "AP:", 3) == 0) {
        // AP:idx|ssid|bssid|ch|security|rssi|pmf  — split on '|' MANUALLY. strtok() collapses
        // consecutive delimiters, so a hidden AP with an empty SSID ("AP:3||bssid|..") would make
        // every later field shift left (SSID gets the BSSID, RSSI gets the wrong value, etc.).
        // Manual splitting preserves empty fields, so hidden APs parse correctly.
        char buffer[160];
        strncpy(buffer, furi_string_get_cstr(line) + 3, sizeof(buffer) - 1); // skip "AP:"
        buffer[sizeof(buffer) - 1] = '\0';
        char* f[7] = {0};
        int nf = 0;
        f[nf++] = buffer;
        for(char* c = buffer; *c && nf < 7; c++) {
            if(*c == '|') {
                *c = '\0';
                f[nf++] = c + 1;
            }
        }
        if(nf < 6) return; // need at least idx..rssi

        // grow the list by one entry
        APDetails* temp = realloc(app->wifiList, (app->wifiCount + 1) * sizeof(APDetails));
        if(!temp) {
            printf("out of memory\n");
            return;
        }
        app->wifiList = temp;
        APDetails* newAP = &app->wifiList[app->wifiCount];

        newAP->idAP = atoi(f[0]);
        newAP->APssid = malloc(strlen(f[1]) + 1);
        if(!newAP->APssid) return;
        strcpy(newAP->APssid, f[1]); // may be empty (hidden AP) -> UI shows "<hidden>"
        strncpy(newAP->APbssid, f[2], 17);
        newAP->APbssid[17] = '\0';
        newAP->channel = atoi(f[3]);
        newAP->security = atoi(f[4]);
        newAP->rssi = atoi(f[5]);
        // 7th field (precise PMF from the beacon RSN IE): absent on legacy/older firmware -> -1,
        // so the UI falls back to the ap_has_pmf(security) heuristic instead of dropping the AP.
        newAP->pmf = (nf >= 7 && f[6][0]) ? atoi(f[6]) : -1;
        newAP->deauth = false;
        newAP->selected = false; // 5Ghost MULTI-AP C2: fresh row starts unticked (malloc'd, not zeroed)

        app->wifiCount++;
    } else if(strncmp(furi_string_get_cstr(line), "SCAN:OK", 7) == 0) {
        scanFinish = true;
        FURI_LOG_D(TAG, "SCAN FINISH");
    } else if(strncmp(furi_string_get_cstr(line), "BLE:OK", 6) == 0) {
        // 5Ghost P6: BLESCAN finished. Tested BEFORE the "BLE:" device prefix
        // below (BLE:OK also starts with "BLE:").
        bleScanFinish = true;
    } else if(strncmp(furi_string_get_cstr(line), "BLE:", 4) == 0) {
        // 5Ghost P6: one BLE device -> BLEDeviceDetails. Format:
        // BLE:<idx>|<type>|<addr>|<rssi>|<mfg>|<name>. Manual '|' split (no strtok).
        char buffer[96];
        strncpy(buffer, furi_string_get_cstr(line) + 4, sizeof(buffer) - 1);
        buffer[sizeof(buffer) - 1] = '\0';
        char* fields[6] = {0};
        int nf = 0;
        char* p = buffer;
        fields[nf++] = p;
        while(nf < 6 && (p = strchr(p, '|')) != NULL) {
            *p = '\0';
            p++;
            fields[nf++] = p;
        }
        if(nf >= 6) {
            BLEDeviceDetails d = {0};
            d.type = fields[1][0] ? fields[1][0] : '.';
            strncpy(d.addr, fields[2], sizeof(d.addr) - 1);
            d.rssi = atoi(fields[3]);
            d.mfg = (unsigned)strtol(fields[4], NULL, 16);
            strncpy(d.name, fields[5], sizeof(d.name) - 1);
            // 5Ghost FUNC-C: dedup by MAC. In accumulate mode (Right re-scan) the list already
            // holds prior rounds; a device seen again refreshes its RSSI + classification and
            // bumps its round count instead of adding a duplicate row. This runs in the UART
            // worker thread, but the main thread sits on the loading view (not reading bleList)
            // until BLE:OK, so the sweep + merge is single-writer — no lock needed (same model
            // the fresh-scan path already relies on).
            int found = -1;
            for(int i = 0; i < app->bleCount; i++) {
                if(strcmp(app->bleList[i].addr, d.addr) == 0) {
                    found = i;
                    break;
                }
            }
            if(found >= 0) {
                BLEDeviceDetails* e = &app->bleList[found];
                e->rssi = d.rssi;                    // newest RSSI = current distance
                if(d.type != '.') e->type = d.type;  // keep the more specific classification (F/A over '.')
                if(d.mfg) e->mfg = d.mfg;
                if(d.name[0] && strcmp(d.name, "-") != 0) {
                    strncpy(e->name, d.name, sizeof(e->name) - 1);
                    e->name[sizeof(e->name) - 1] = '\0'; // e isn't zero-inited; guarantee NUL
                }
                if(e->seen < 0x7FFFFFFF) e->seen++;
            } else {
                d.idx = app->bleCount; // stable FAP index (firmware idx restarts at 0 each round)
                d.seen = 1;
                app->bleCount++;
                BLEDeviceDetails* grown =
                    realloc(app->bleList, sizeof(BLEDeviceDetails) * app->bleCount);
                if(grown) {
                    app->bleList = grown;
                    app->bleList[app->bleCount - 1] = d;
                } else {
                    app->bleCount--;
                }
            }
            // 5Ghost ③: remember which row this BLE: line touched, so the BLERAW: line that
            // immediately follows fills the right device (firmware idx != our stable idx).
            last_ble_index = (found >= 0) ? found : (app->bleCount - 1);
        }
    } else if(strncmp(furi_string_get_cstr(line), "BLERAW:", 7) == 0) {
        // 5Ghost ③: raw advert bytes (hex) for the device the preceding BLE: line touched.
        // Format BLERAW:<idx>|<hex>. idx is the firmware's per-round index, not our stable
        // one, so fill last_ble_index (set just above), never idx.
        if(last_ble_index >= 0 && last_ble_index < app->bleCount) {
            const char* bar = strchr(furi_string_get_cstr(line) + 7, '|');
            if(bar) {
                const char* h = bar + 1;
                BLEDeviceDetails* e = &app->bleList[last_ble_index];
                int n = 0, hi, lo;
                while(n < 31 && (hi = hex_nib(h[0])) >= 0 && (lo = hex_nib(h[1])) >= 0) {
                    e->raw[n++] = (uint8_t)((hi << 4) | lo);
                    h += 2;
                }
                e->raw_len = (uint8_t)n;
            }
        }
    } else if(strncmp(furi_string_get_cstr(line), "GATT:OK", 7) == 0) {
        // 5Ghost ②: BLEGATTPROBE finished successfully. Tested BEFORE the "GATT:" catch-all
        // below (GATT:OK/GATT:SVC/GATT:INFO all start with "GATT:").
        // Format: GATT:OK svc=<N> heap=<M> — the first '=' is svc's (heap follows); no strtok.
        char* eq = strchr(furi_string_get_cstr(line) + 7, '=');
        app->gatt_result_svc = eq ? atoi(eq + 1) : 0;
        gattProbeFinish = true;
    } else if(strncmp(furi_string_get_cstr(line), "ERR:GATT:", 9) == 0) {
        // 5Ghost ②: probe failed (notfound/conntimeout/disctimeout/args). Tested here, BEFORE
        // the generic "ERR:" handler later in this chain, so a GATT failure lands on the
        // gattView result card instead of falling into the generic error popup.
        strncpy(app->gatt_err, furi_string_get_cstr(line) + 9, sizeof(app->gatt_err) - 1);
        app->gatt_err[sizeof(app->gatt_err) - 1] = '\0';
        gattProbeFinish = true;
    } else if(strncmp(furi_string_get_cstr(line), "GATT:SVC ", 9) == 0) {
        // GATT:SVC <label> <uuid> — one known-service hit. Manual split on the single space
        // (no strtok); copied into a fixed-width slot, capped at 8 hits.
        char buffer[64];
        strncpy(buffer, furi_string_get_cstr(line) + 9, sizeof(buffer) - 1);
        buffer[sizeof(buffer) - 1] = '\0';
        char* sp = strchr(buffer, ' ');
        if(sp && app->gatt_svc_count < 8) {
            *sp = '\0';
            GattSvcHit* hit = &app->gatt_svcs[app->gatt_svc_count];
            strncpy(hit->label, buffer, sizeof(hit->label) - 1);
            hit->label[sizeof(hit->label) - 1] = '\0';
            strncpy(hit->uuid, sp + 1, sizeof(hit->uuid) - 1);
            hit->uuid[sizeof(hit->uuid) - 1] = '\0';
            app->gatt_svc_count++;
        }
    } else if(strncmp(furi_string_get_cstr(line), "GATT:INFO ", 10) == 0) {
        // GATT:INFO <field>="<value>" — one Device Information string. Manual split on '='
        // then strip the surrounding quotes (no strtok).
        char buffer[96];
        strncpy(buffer, furi_string_get_cstr(line) + 10, sizeof(buffer) - 1);
        buffer[sizeof(buffer) - 1] = '\0';
        char* eqf = strchr(buffer, '=');
        if(eqf) {
            *eqf = '\0';
            char* val = eqf + 1;
            size_t vl = strlen(val);
            if(vl >= 2 && val[0] == '"' && val[vl - 1] == '"') {
                val[vl - 1] = '\0';
                val++;
            }
            if(strcmp(buffer, "name") == 0) {
                strncpy(app->gatt_info_name, val, sizeof(app->gatt_info_name) - 1);
                app->gatt_info_name[sizeof(app->gatt_info_name) - 1] = '\0';
            } else if(strcmp(buffer, "mfg") == 0) {
                strncpy(app->gatt_info_mfg, val, sizeof(app->gatt_info_mfg) - 1);
                app->gatt_info_mfg[sizeof(app->gatt_info_mfg) - 1] = '\0';
            } else if(strcmp(buffer, "model") == 0) {
                strncpy(app->gatt_info_model, val, sizeof(app->gatt_info_model) - 1);
                app->gatt_info_model[sizeof(app->gatt_info_model) - 1] = '\0';
            } else if(strcmp(buffer, "fw") == 0) {
                strncpy(app->gatt_info_fw, val, sizeof(app->gatt_info_fw) - 1);
                app->gatt_info_fw[sizeof(app->gatt_info_fw) - 1] = '\0';
            }
        }
    } else if(strncmp(furi_string_get_cstr(line), "GATT:", 5) == 0) {
        // GATT:SCAN / GATT:CONN progress lines — loadingView doesn't render them; ignored.
    } else if(strncmp(furi_string_get_cstr(line), "STA:OK", 6) == 0) {
        // 5Ghost FUNC-A: STASCAN finished. Tested BEFORE "STA:" (STA:OK starts with STA:).
        staScanFinish = true;
    } else if(strncmp(furi_string_get_cstr(line), "STAT:", 5) == 0) {
        // 5Ghost FUNC-A: STASCAN diagnostic (dframes/match/stas). UI ignores it; on a UART
        // console it tells "no data frames" (2.4GHz uplink-deaf) from "frames seen but none
        // matched this AP". proto=1: safe to ignore. (STAT != STA:, tested after STA:OK.)
    } else if(strncmp(furi_string_get_cstr(line), "STA:", 4) == 0) {
        // 5Ghost FUNC-A: one station -> StaDetails. STA:<idx>|<mac12hex>|<rssi>|<frames>.
        // Manual '|' split (no strtok). MAC stays colon-less 12hex (feeds DEAUTH directly).
        char buffer[64];
        strncpy(buffer, furi_string_get_cstr(line) + 4, sizeof(buffer) - 1);
        buffer[sizeof(buffer) - 1] = '\0';
        char* fields[4] = {0};
        int nf = 0;
        char* p = buffer;
        fields[nf++] = p;
        while(nf < 4 && (p = strchr(p, '|')) != NULL) {
            *p = '\0';
            p++;
            fields[nf++] = p;
        }
        if(nf >= 4) {
            StaDetails d = {0};
            d.idx = atoi(fields[0]);
            strncpy(d.mac, fields[1], sizeof(d.mac) - 1);
            d.rssi = atoi(fields[2]);
            d.frames = atoi(fields[3]);
            app->staCount++;
            StaDetails* grown = realloc(app->staList, sizeof(StaDetails) * app->staCount);
            if(grown) {
                app->staList = grown;
                app->staList[app->staCount - 1] = d;
            } else {
                app->staCount--;
            }
        }
    } else if(strncmp(furi_string_get_cstr(line), "PHTMLOK", 7) == 0) {
        app->phtml_ok = true; // task10: firmware stored the custom portal HTML
    } else if(strncmp(furi_string_get_cstr(line), "BADBLEOK", 8) == 0) {
        app->badble_ack = true; // 5Ghost ⑧b: firmware ACKed a BadBLE payload chunk (upload pacing)
    } else if(strncmp(furi_string_get_cstr(line), "BADBLE:", 7) == 0) {
        // 5Ghost ⑧b: run-scene status from g5_ble_badble (BADBLE:START/INJECT/t=/OK). Worker only
        // updates state + signals; the run scene redraws on the custom event.
        const char* r = furi_string_get_cstr(line) + 7;
        if(strncmp(r, "OK", 2) == 0) {
            app->badble_running = false;
            app->badble_done = true;
            view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_BADBLE_DONE);
        } else if(strncmp(r, "INJECT", 6) == 0) {
            app->badble_inject_count++;
            app->badble_last_fallback = (strstr(r, "fallback") != NULL);
            view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_BADBLE_UPDATE);
        } else if(strncmp(r, "START", 5) == 0) {
            app->badble_running = true;
            view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_BADBLE_UPDATE);
        } else if(strncmp(r, "t=", 2) == 0) {
            const char* cc = strstr(r, "conn=");
            const char* yy = strstr(r, "ready=");
            if(cc) app->badble_conn = atoi(cc + 5);
            if(yy) app->badble_notify_ready = atoi(yy + 6);
            view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_BADBLE_UPDATE);
        }
    } else if(strncmp(furi_string_get_cstr(line), "EV:", 3) == 0) {
        // Runs on the UART worker thread (1KB stack): only parse + buffer the credential and post
        // a custom event. The SD write + GUI must run on the main thread (same rule as the
        // handshake events) — doing them here overflowed the worker stack so the capture never showed.
        // strtok()/strcat() are disabled in the official firmware API. Take the field after
        // "EV:" up to the next '|' by hand, then append with bounded snprintf.
        const char* src = furi_string_get_cstr(line) + 3; // skip "EV:"
        char cred[128];
        size_t n = 0;
        while(src[n] && src[n] != '|' && n < sizeof(cred) - 1) {
            cred[n] = src[n];
            n++;
        }
        cred[n] = '\0';
        if(n == 0) return;
        size_t cl = strlen(credentials);
        snprintf(credentials + cl, sizeof(credentials) - cl, "%s\n", cred);
        strncpy(ev_last, cred, sizeof(ev_last) - 1);
        ev_last[sizeof(ev_last) - 1] = '\0';
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_EV_CRED);
    } else if(strncmp(furi_string_get_cstr(line), "ERR:", 4) == 0) {
        // P4 contract: fw emits machine-parseable ERR:<VERB>:<code> (e.g. ERR:DEAUTH:chan).
        const char* src = furi_string_get_cstr(line) + 4; // skip "ERR:"
        // ERR:UNKNOWN = fw doesn't implement this verb. Under capability negotiation this is
        // NORMAL: the FAP may send a command the fw's caps don't cover — e.g. info_wifi
        // on_enter pushes APMAC/PORTAL, which a DSB-only fw doesn't have yet. Do NOT
        // pop a user-facing error for it, or merely opening an AP detail card throws a
        // dolphin error popup. Only real operation failures (ERR:DEAUTH:chan etc.) pop.
        if(strncmp(src, "UNKNOWN", 7) == 0) {
            FURI_LOG_D(TAG, "fw ERR:UNKNOWN (unsupported verb, ignored)");
        } else {
            // Overwrite from offset 0 (not append): message is a single global buffer shown
            // by popupScene. Appending across errors piled a garbled string and, once the
            // 128B filled, silently dropped new ones. popup_scene_on_exit also clears it.
            snprintf(message, sizeof(message), "%s", src);
            scene_manager_next_scene(app->scene_manager, popupScene);
        }
    } else if(strncmp(furi_string_get_cstr(line), "IDENT:", 6) == 0) {
        // 5Ghost L1 handshake response (current clean-room fw):
        // IDENT:brand=5GHOST;fw=2.1.0;proto=1;caps=DSBH;board=A1
        char buffer[160];
        strncpy(buffer, furi_string_get_cstr(line) + 6, sizeof(buffer) - 1);
        buffer[sizeof(buffer) - 1] = '\0';
        bool is_5ghost = false;
        // strtok() is disabled in the official firmware API; split on ';' by hand.
        char* kv = buffer;
        while(*kv) {
            char* sep = strchr(kv, ';');
            if(sep) *sep = '\0'; // terminate this key=value token
            if(strncmp(kv, "brand=", 6) == 0) {
                is_5ghost = (strcmp(kv + 6, "5GHOST") == 0);
            } else if(strncmp(kv, "fw=", 3) == 0) {
                strncpy(app->fw_version, kv + 3, sizeof(app->fw_version) - 1);
                app->fw_version[sizeof(app->fw_version) - 1] = '\0';
            } else if(strncmp(kv, "caps=", 5) == 0) {
                strncpy(app->fw_caps, kv + 5, sizeof(app->fw_caps) - 1);
                app->fw_caps[sizeof(app->fw_caps) - 1] = '\0';
            }
            if(!sep) break;
            kv = sep + 1;
        }
        app->fw_status = is_5ghost ? FwOfficial : FwUnofficial;
        FURI_LOG_I(
            TAG,
            "5Ghost handshake: status=%d fw=%s caps=%s",
            app->fw_status,
            app->fw_version,
            app->fw_caps);
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_SPLASH_TICK);
    } else if(strncmp(furi_string_get_cstr(line), "HSFRAME:", 8) == 0) {
        // Strict decode + quality ingest stay in the worker; storage remains main-thread only.
        if(app->hs_buf) {
            size_t n = 0;
            if(g5_cq_hex_decode_exact(
                   furi_string_get_cstr(line) + 8,
                   app->hs_decode,
                   sizeof(app->hs_decode),
                   &n)) {
                if(ghost_hs_add_frame(app, app->hs_decode, n))
                    app->hs_eapol_count++;
                else
                    app->hs_buffer_complete = false;
                g5_cq_ingest_frame(&app->hs_quality, app->hs_decode, n);
                view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_HS_UPDATE);
            }
        }
    } else if(strncmp(furi_string_get_cstr(line), "HSBEACON:", 9) == 0) {
        // Only a beacon whose BSSID equals the selected target enters the PCAP evidence.
        if(app->hs_buf) {
            size_t n = 0;
            if(g5_cq_hex_decode_exact(
                   furi_string_get_cstr(line) + 9,
                   app->hs_decode,
                   sizeof(app->hs_decode),
                   &n) &&
               g5_cq_ingest_beacon(&app->hs_quality, app->hs_decode, n)) {
                if(ghost_hs_add_frame(app, app->hs_decode, n))
                    app->hs_have_beacon = true;
                else
                    app->hs_buffer_complete = false;
                view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_HS_UPDATE);
            }
        }
    } else if(strncmp(furi_string_get_cstr(line), "HSDONE:", 7) == 0) {
        const char* count_text = furi_string_get_cstr(line) + 7;
        char* end = NULL;
        long count = strtol(count_text, &end, 10);
        app->hs_reported_count =
            (end != count_text && *end == '\0' && count >= 0 && count <= 255) ? (int)count : -1;
        g5_cq_finish(&app->hs_quality, app->hs_reported_count);
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_HS_DONE);
    } else if(strncmp(furi_string_get_cstr(line), "HSERR:", 6) == 0) {
        FURI_LOG_W(TAG, "5Ghost: %s", furi_string_get_cstr(line));
        strncpy(app->hs_error, furi_string_get_cstr(line) + 6, sizeof(app->hs_error) - 1);
        app->hs_error[sizeof(app->hs_error) - 1] = '\0';
        view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_HS_ERROR);
    } else if(strncmp(furi_string_get_cstr(line), "PMKID:", 6) == 0) {
        // 5Ghost B3: worker only parses + signals; classify/build/storage stay main-thread.
        if(g5_pmkid_parse_line(furi_string_get_cstr(line), &app->pmkid_report))
            view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_PMKID_DONE);
        else if(app->pmkid_report.state == G5PmkidPending)
            view_dispatcher_send_custom_event(app->view_dispatcher, GHOST_EVT_PMKID_UPDATE);
    }
}

static void animation_timer_callback(void* context) {
    Ghost5App* app = context;
    if(app->rickIndex % 4 == 0) {
        widget_reset(app->widget);
        widget_add_string_element(
            app->widget, 90, 10, AlignCenter, AlignTop, FontPrimary, "Ghost");
        if(app->rickIndex >= 4) {
            widget_add_string_multiline_element(
                app->widget,
                128,
                30,
                AlignRight,
                AlignCenter,
                FontSecondary,
                "Haunting the\nairwaves");
        }
        if(app->rickIndex >= 8) {
            widget_add_string_multiline_element(
                app->widget,
                64,
                53,
                AlignLeft,
                AlignCenter,
                FontSecondary,
                "5Ghost\nBeacon");
        }
    }
    app->rickIndex = (app->rickIndex + 1) % GHOST_ANIM_FRAMES;

    widget_add_icon_element(app->widget, 0, 0, ghost_anim[app->rickIndex]);

    //furi_timer_start(app->timer, 300);
}

static Ghost5App* app_alloc() {
    FURI_LOG_D(TAG, __func__);
    Ghost5App* app = malloc(sizeof(Ghost5App));
    // 5Ghost: ssidAP/passwordAP are heap buffers the text_input widget writes into when the user
    // edits the fake-AP name/password. Upstream malloc'd ssidAP then immediately reassigned the
    // pointer to a string literal ("TEST"), which (a) leaked the malloc, (b) made the text_input
    // write into read-only memory (crash on edit), (c) never allocated passwordAP at all yet
    // free()'d it on exit (UB). Allocate both properly and copy the defaults in.
    app->ssidAPLength = 32;
    app->ssidAP = malloc(app->ssidAPLength);
    strncpy(app->ssidAP, "PINGEQUA", app->ssidAPLength - 1); // branded default fake-AP SSID
    app->ssidAP[app->ssidAPLength - 1] = '\0';
    app->passwordAPLength = 64;
    app->passwordAP = malloc(app->passwordAPLength);
    strncpy(app->passwordAP, "password123", app->passwordAPLength - 1);
    app->passwordAP[app->passwordAPLength - 1] = '\0';
    // 5Ghost L1: identity strings stay empty until IDENT arrives, so menu/About rendering before
    // the handshake never reads uninitialised heap (fw_has_cap/sscanf would otherwise scan garbage).
    app->fw_caps[0] = '\0';
    app->fw_version[0] = '\0';
    app->status_label[0] = '\0';
    app->menuIndex = 0;
    app->submenuIndex = 0;
    app->home_target = ScanWifi;
    app->wifiList = NULL;
    app->wifiCount = 0; // guard first-scan free loop against uninitialised count
    app->multi_deauth_active = false; // 5Ghost MULTI-AP C2: no multi-deauth round at startup
    // 5Ghost ⑦b: app is malloc'd (NOT zeroed). Clear the iBeacon identity so the ByteInput
    // shows all-zero on first entry; default the duration (the duration scene always sets it).
    memset(app->ibeacon_store, 0, sizeof(app->ibeacon_store));
    app->ibeacon_secs = 30;
    app->ap_reuse = false; // malloc'd app is NOT zeroed: a garbage value would make the first
                           // handshake/PMKID entry reuse a stale/empty list (see pmkid_seen_count)
    // 5Ghost: BLE detector fields. app is malloc'd (NOT zeroed). Historically these were only ever
    // assigned before use (menu entry sets ble_accumulate; bleScan on_enter normalizes bleList/
    // bleCount), so nothing read them uninitialised — initialize defensively anyway so any future
    // early read (e.g. a reuse fast-path) can't walk a garbage bleList (adversarial-review finding).
    app->bleList = NULL;
    app->bleCount = 0;
    app->ble_exported = false;
    app->ble_accumulate = false;
    app->ble_filter_alarms = false;
    app->ble_scan_timed_out = false;
    app->selectedBle = 0;
    // 5Ghost ②: GATT probe result state. app is malloc'd (NOT zeroed) — gatt_svc_count is
    // used as a loop bound (gatt_result_row_text/draw) and gatt_info_*/gatt_err are read as
    // NUL-terminated strings before any probe ever runs (gattView could in principle be
    // reached with stale/garbage data otherwise); see [[fap-app-malloc-uninit-fields]].
    app->gatt_svc_count = 0;
    app->gatt_result_svc = 0;
    app->gatt_info_name[0] = '\0';
    app->gatt_info_mfg[0] = '\0';
    app->gatt_info_model[0] = '\0';
    app->gatt_info_fw[0] = '\0';
    app->gatt_err[0] = '\0';
    app->gatt_timed_out = false;
    app->scan_exported = false;
    app->scan_timed_out = false;
    app->phtml_ok = false;
    app->custom_portal_ready = false;
    app->custom_portal_load_failed = false;
    app->custom_portal_basename[0] = '\0';
    // 5Ghost ⑧b: BadBLE HID state (app is malloc'd, NOT zeroed — see fap-app-malloc-uninit-fields)
    app->badble_ack = false;
    app->badble_ready = false;
    app->badble_load_failed = false;
    app->badble_source = 0; // first preset
    app->badble_secs = 30;
    app->badble_name[0] = '\0';
    app->badble_running = false;
    app->badble_done = false;
    app->badble_inject_count = 0;
    app->badble_last_fallback = false;
    app->badble_conn = 0;
    app->badble_notify_ready = 0;
    app->creds_path[0] = '\0';
    // 5Ghost P2: handshake capture state (buffer is lazily allocated per capture)
    app->hs_buf = NULL;
    app->hs_buf_len = 0;
    app->hs_eapol_count = 0;
    app->hs_reported_count = -1;
    app->hs_buffer_complete = true;
    g5_cq_reset(&app->hs_quality, NULL);
    app->hs_have_beacon = false;
    app->hs_done = false;
    app->hs_stopping = false;
    app->hs_path[0] = '\0';
    app->hs_error[0] = '\0';
    app->hs_ssid[0] = '\0';
    app->hs_bssid[0] = '\0';
    app->hs_channel = 0;
    // 5Ghost B3: session dedup list starts empty. app is malloc'd (NOT zeroed), and
    // pmkid_seen_count is used as a loop bound in the capture DONE handler — leaving it
    // uninitialised let a real PMKID:ok walk pmkid_seen[garbage] and hard-fault the board
    // (real-hardware gate finding; source review + compile both missed it).
    app->pmkid_seen_count = 0;
    app->session_id[0] = '\0'; // Guided Audit injects; standalone menus mint per flush
    app->audit_next = G5AuditNextStop;
    app->audit_path = G5AuditPathNone;
    app->audit_result = G5AuditResultNone;
    app->audit_done = false;
    app->audit_ssid[0] = '\0';
    app->audit_bssid[0] = '\0';
    app->audit_channel = 0;
    app->audit_pmf = 0;
    app->audit_wait_ticks = 0;
    app->audit_wait_kind = AUDIT_WAIT_NONE;
    //app->ssidAPLength = 0;
    app->captivePortal = 0;
    app->deauthReason = 2;
    app->mac_type = 0;
    app->securityAP = 0;
    app->channelAP = 9;
    app->config_ap_layout = ghost_config_ap_layout(false, false, false);
    app->scene_manager = scene_manager_alloc(&Ghost5App_scene_manager_handlers, app);
    app->view_dispatcher = view_dispatcher_alloc();
    //strncpy(app->customMac, "00:E0:4C:01:02:03", 18);
    snprintf(app->customMac, sizeof(app->customMac), "00:E0:4C:01:02:03");
    parse_mac(app->customMac, app->byte_input_store);

    view_dispatcher_set_event_callback_context(app->view_dispatcher, app);
    view_dispatcher_set_custom_event_callback(app->view_dispatcher, Ghost5App_custom_callback);
    view_dispatcher_set_navigation_event_callback(
        app->view_dispatcher, Ghost5App_back_event_callback);

    app->splash_view = view_alloc();
    view_set_context(app->splash_view, app);
    view_allocate_model(app->splash_view, ViewModelTypeLocking, sizeof(SplashModel));
    view_set_draw_callback(app->splash_view, ghost_splash_draw_callback);
    view_set_input_callback(app->splash_view, ghost_splash_input_callback);
    view_dispatcher_add_view(app->view_dispatcher, splashView, app->splash_view);

    // 5Ghost UI redesign: L1 home is a custom Canvas view (replaces the stock Menu module).
    app->home_view = view_alloc();
    view_set_context(app->home_view, app);
    view_allocate_model(app->home_view, ViewModelTypeLocking, sizeof(HomeModel));
    with_view_model(app->home_view, HomeModel * m, { m->app = app; m->sel = 0; m->top = 0; }, false);
    view_set_draw_callback(app->home_view, ghost_home_draw_callback);
    view_set_input_callback(app->home_view, ghost_home_input_callback);
    view_dispatcher_add_view(app->view_dispatcher, mainMenuView, app->home_view);

    app->submenu = submenu_alloc();
    view_dispatcher_add_view(
        app->view_dispatcher, scannedWifisView, submenu_get_view(app->submenu));
    view_dispatcher_add_view(app->view_dispatcher, beaconListView, submenu_get_view(app->submenu));

    app->text_input = text_input_alloc();
    view_dispatcher_add_view(
        app->view_dispatcher, bssidTextInputView, text_input_get_view(app->text_input));
    view_dispatcher_add_view(
        app->view_dispatcher, apNameTextInputView, text_input_get_view(app->text_input));
    view_dispatcher_add_view(
        app->view_dispatcher, apPasswordTextInputView, text_input_get_view(app->text_input));

    app->loading = loading_alloc();
    view_dispatcher_add_view(app->view_dispatcher, loadingView, loading_get_view(app->loading));

    // wifiInfoView no longer shares app->widget — it has its own info_view (registered below).
    app->widget = widget_alloc();
    view_dispatcher_add_view(app->view_dispatcher, beaconInfoView, widget_get_view(app->widget));
    view_dispatcher_add_view(app->view_dispatcher, helpView, widget_get_view(app->widget));
    view_dispatcher_add_view(
        app->view_dispatcher, handshakeView, widget_get_view(app->widget));

    // 5Ghost evil-portal redo: evilCredsView gets its own TextBox (was sharing app->widget).
    app->text_box = text_box_alloc();
    view_dispatcher_add_view(
        app->view_dispatcher, evilCredsView, text_box_get_view(app->text_box));

    // 5Ghost P8: channel analyzer gets its own Canvas View + model (Left/Right toggles band).
    app->channel_view = view_alloc();
    view_set_context(app->channel_view, app);
    view_allocate_model(app->channel_view, ViewModelTypeLocking, sizeof(ChannelModel));
    view_set_draw_callback(app->channel_view, channel_analyzer_draw_callback);
    view_set_input_callback(app->channel_view, channel_analyzer_input_callback);
    view_dispatcher_add_view(app->view_dispatcher, channelAnalyzerView, app->channel_view);

    // 5Ghost: paged About (brand / info+QR / legal) — own Canvas view.
    app->about_view = view_alloc();
    view_set_context(app->about_view, app);
    view_allocate_model(app->about_view, ViewModelTypeLocking, sizeof(AboutModel));
    view_set_draw_callback(app->about_view, ghost_about_draw_callback);
    view_set_input_callback(app->about_view, ghost_about_input_callback);
    view_dispatcher_add_view(app->view_dispatcher, aboutView, app->about_view);

    // 5Ghost P8 UI redesign: scan list + AP detail get their own Canvas Views + models
    // (rich rows / structured card; off the shared submenu+widget that capped the look).
    app->list_view = view_alloc();
    view_set_context(app->list_view, app);
    view_allocate_model(app->list_view, ViewModelTypeLocking, sizeof(ListModel));
    view_set_draw_callback(app->list_view, ghost_list_draw_callback);
    view_set_input_callback(app->list_view, ghost_list_input_callback);
    view_dispatcher_add_view(app->view_dispatcher, wifiListView, app->list_view);

    // 5Ghost P6: BLE device list (own Canvas View, mirrors list_view)
    app->ble_list_view = view_alloc();
    view_allocate_model(app->ble_list_view, ViewModelTypeLocking, sizeof(ListModel));
    view_set_context(app->ble_list_view, app);
    view_set_draw_callback(app->ble_list_view, ble_list_draw_callback);
    view_set_input_callback(app->ble_list_view, ble_list_input_callback);
    view_dispatcher_add_view(app->view_dispatcher, bleListView, app->ble_list_view);

    // 5Ghost P6: BLE device detail card (own Canvas View, mirrors info_view)
    app->ble_info_view = view_alloc();
    view_set_context(app->ble_info_view, app);
    view_allocate_model(app->ble_info_view, ViewModelTypeLocking, sizeof(InfoModel));
    view_set_draw_callback(app->ble_info_view, ble_info_draw_callback);
    view_set_input_callback(app->ble_info_view, ble_info_input_callback);
    view_dispatcher_add_view(app->view_dispatcher, bleInfoView, app->ble_info_view);

    // 5Ghost ②: GATT probe result (own Canvas View, reuses ListModel for sel/top scrolling)
    app->gatt_view = view_alloc();
    view_set_context(app->gatt_view, app);
    view_allocate_model(app->gatt_view, ViewModelTypeLocking, sizeof(ListModel));
    view_set_draw_callback(app->gatt_view, gatt_view_draw_callback);
    view_set_input_callback(app->gatt_view, gatt_view_input_callback);
    view_dispatcher_add_view(app->view_dispatcher, gattView, app->gatt_view);

    // 5Ghost ③: raw-advert view (own Canvas View, reuses ListModel for top scrolling)
    app->ble_raw_view = view_alloc();
    view_set_context(app->ble_raw_view, app);
    view_allocate_model(app->ble_raw_view, ViewModelTypeLocking, sizeof(ListModel));
    view_set_draw_callback(app->ble_raw_view, ble_raw_view_draw_callback);
    view_set_input_callback(app->ble_raw_view, ble_raw_view_input_callback);
    view_dispatcher_add_view(app->view_dispatcher, bleRawView, app->ble_raw_view);

    // 5Ghost FUNC-A: station (client) list (own Canvas View, mirrors ble_list_view)
    app->sta_list_view = view_alloc();
    view_allocate_model(app->sta_list_view, ViewModelTypeLocking, sizeof(ListModel));
    view_set_context(app->sta_list_view, app);
    view_set_draw_callback(app->sta_list_view, sta_list_draw_callback);
    view_set_input_callback(app->sta_list_view, sta_list_input_callback);
    view_dispatcher_add_view(app->view_dispatcher, staListView, app->sta_list_view);

    app->info_view = view_alloc();
    view_set_context(app->info_view, app);
    view_allocate_model(app->info_view, ViewModelTypeLocking, sizeof(InfoModel));
    view_set_draw_callback(app->info_view, ghost_info_draw_callback);
    view_set_input_callback(app->info_view, ghost_info_input_callback);
    view_dispatcher_add_view(app->view_dispatcher, wifiInfoView, app->info_view);

    app->variableList = variable_item_list_alloc();
    view_dispatcher_add_view(
        app->view_dispatcher, configAttackView, variable_item_list_get_view(app->variableList));
    view_dispatcher_add_view(
        app->view_dispatcher, configAPView, variable_item_list_get_view(app->variableList));

    app->byteInput = byte_input_alloc();
    view_dispatcher_add_view(
        app->view_dispatcher, aPmacAddresView, byte_input_get_view(app->byteInput));

    app->popup = popup_alloc();
    view_dispatcher_add_view(app->view_dispatcher, popupView, popup_get_view(app->popup));

    app->uart_helper = uart_helper_alloc();
    app->uart_port_busy = (app->uart_helper == NULL);
    if(app->uart_helper) {
        uart_helper_set_baud_rate(app->uart_helper, DEVICE_BAUDRATE);
        uart_helper_set_delimiter(app->uart_helper, LINE_DELIMITER, INCLUDE_LINE_DELIMITER);
        uart_helper_set_callback(app->uart_helper, uart_process_line, app);
    }

    app->notif = furi_record_open(RECORD_NOTIFICATION); // 5Ghost task8: scan-indicator LED
    app->timer = furi_timer_alloc(animation_timer_callback, FuriTimerTypePeriodic, app);
    app->splash_timer = furi_timer_alloc(ghost_splash_timer_callback, FuriTimerTypePeriodic, app);
    app->audit_timer = furi_timer_alloc(audit_timer_callback, FuriTimerTypePeriodic, app);
    return app;
}

void Ghost5App_wifimenu_callback(void* context, uint32_t index) {
    FURI_LOG_D(TAG, __func__);
    UNUSED(context);
    UNUSED(index);
}

static void app_free(Ghost5App* app) {
    FURI_LOG_D(TAG, __func__);
    furi_assert(app);

    uart_helper_free(app->uart_helper);

    view_dispatcher_remove_view(app->view_dispatcher, splashView);
    view_dispatcher_remove_view(app->view_dispatcher, mainMenuView);
    view_dispatcher_remove_view(app->view_dispatcher, scannedWifisView);
    view_dispatcher_remove_view(app->view_dispatcher, bssidTextInputView);
    view_dispatcher_remove_view(app->view_dispatcher, loadingView);
    view_dispatcher_remove_view(app->view_dispatcher, wifiInfoView);
    view_dispatcher_remove_view(app->view_dispatcher, configAttackView);
    view_dispatcher_remove_view(app->view_dispatcher, evilCredsView);
    view_dispatcher_remove_view(app->view_dispatcher, aPmacAddresView);
    view_dispatcher_remove_view(app->view_dispatcher, beaconListView);
    view_dispatcher_remove_view(app->view_dispatcher, beaconInfoView);
    view_dispatcher_remove_view(app->view_dispatcher, configAPView);
    view_dispatcher_remove_view(app->view_dispatcher, helpView);
    view_dispatcher_remove_view(app->view_dispatcher, popupView);
    view_dispatcher_remove_view(app->view_dispatcher, handshakeView);
    view_dispatcher_remove_view(app->view_dispatcher, channelAnalyzerView);
    view_dispatcher_remove_view(app->view_dispatcher, wifiListView); // 5Ghost P8 UI redesign
    view_dispatcher_remove_view(app->view_dispatcher, bleListView); // 5Ghost P6
    view_dispatcher_remove_view(app->view_dispatcher, bleInfoView); // 5Ghost P6
    view_dispatcher_remove_view(app->view_dispatcher, gattView); // 5Ghost ②
    view_dispatcher_remove_view(app->view_dispatcher, bleRawView); // 5Ghost ③
    view_dispatcher_remove_view(app->view_dispatcher, staListView); // 5Ghost FUNC-A
    view_dispatcher_remove_view(app->view_dispatcher, aboutView); // 5Ghost paged About
    view_dispatcher_remove_view(app->view_dispatcher, apNameTextInputView);
    view_dispatcher_remove_view(app->view_dispatcher, apPasswordTextInputView);

    scene_manager_free(app->scene_manager);

    view_dispatcher_free(app->view_dispatcher); //Some events whre not processed

    notification_message(app->notif, &sequence_reset_rgb); // 5Ghost task8: LED off on any exit path
    furi_record_close(RECORD_NOTIFICATION);
    furi_timer_free(app->timer);
    furi_timer_free(app->splash_timer);
    if(app->audit_timer) {
        furi_timer_stop(app->audit_timer);
        furi_timer_free(app->audit_timer);
    }

    view_free(app->splash_view);
    view_free(app->home_view); // 5Ghost UI redesign: custom L1 home (replaced stock Menu)
    view_free(app->about_view); // 5Ghost paged About
    submenu_free(app->submenu);

    text_input_free(app->text_input);
    text_box_free(app->text_box); // 5Ghost evil-portal redo
    view_free(app->channel_view); // 5Ghost P8
    view_free(app->list_view); // 5Ghost P8 UI redesign
    view_free(app->ble_list_view); // 5Ghost P6
    view_free(app->ble_info_view); // 5Ghost P6
    view_free(app->gatt_view); // 5Ghost ②
    view_free(app->ble_raw_view); // 5Ghost ③
    view_free(app->sta_list_view); // 5Ghost FUNC-A
    view_free(app->info_view); // 5Ghost P8 UI redesign
    loading_free(app->loading);
    for(int i = 0; i < app->wifiCount; i++) {
        free(app->wifiList[i].APssid); // free the SSID string
    }

    free(app->wifiList); // free the dynamic array
    free(app->bleList); // 5Ghost P6: free the BLE dynamic array
    free(app->staList); // 5Ghost FUNC-A: free the station dynamic array
    app->wifiList = NULL; // Evitar punteros colgantes
    app->wifiCount = 0; // Resetear el contador
    app->rickIndex = 0;

    // 5Ghost P2: backstop free for an unflushed handshake buffer (e.g. user quit mid-capture).
    if(app->hs_buf) {
        free(app->hs_buf);
        app->hs_buf = NULL;
    }

    free(app->ssidAP); // both are heap buffers now (see app_alloc) — free both
    free(app->passwordAP);
    furi_record_close(RECORD_GUI);
    furi_hal_power_disable_otg();
    free(app);
}

int32_t ghost5_app(void* p) {
    FURI_LOG_D(TAG, __func__);
    UNUSED(p);

    // SDK: MUST expansion_disable BEFORE furi_hal_serial_control_acquire (uart_helper_alloc).
    Expansion* expansion = furi_record_open(RECORD_EXPANSION);
    expansion_disable(expansion);
    if(!furi_hal_power_is_otg_enabled()) furi_hal_power_enable_otg();

    Ghost5App* app = app_alloc();
    ghost_migrate_legacy_data();
    ghost_seed_portals(); // unpack bundled example portals after legacy migrate
    Gui* gui = furi_record_open(RECORD_GUI);
    view_dispatcher_attach_to_gui(app->view_dispatcher, gui, ViewDispatcherTypeFullscreen);

    scene_manager_next_scene(app->scene_manager, splashScene);
    view_dispatcher_run(app->view_dispatcher);

    // tell the module to stop any active deauth/AP/portal on exit. The old "Exit" menu item
    // did this; Back now exits the app, so we send STOP here to cover every exit path.
    if(app->uart_helper) uart_helper_send(app->uart_helper, "STOP\n", 5);
    app_free(app);
    expansion_enable(expansion);

    furi_record_close(RECORD_EXPANSION);

    return 0;
}
